// AIVC Insight 文献详情数据 v2 —— 每篇七层解读：背景脉络 / 方法详解 / 关键结果 / 局限 / 争议与后续 / 情报点评 / 延伸阅读
const PAPERS = [
{id:"p01",g:"g1",t:"How to Build the Virtual Cell with Artificial Intelligence: Priorities and Opportunities",a:"Bunne, Roohani, Rosen … Regev, Lundberg, Leskovec, Quake",v:"Cell",d:"2024-12",doi:"10.1016/j.cell.2024.11.015",
summary:"领域纲领：提出 AIVC 愿景——多尺度跨模态基础模型直接学习细胞行为，以「虚拟仪器」实现可解释的 in silico 实验。",
background:[
"2024 年之前，「用 AI 建虚拟细胞」还只是散见于各实验室的愿景陈述：有人做单细胞基础模型，有人做扰动预测，有人做空间建模，彼此之间甚至不用同一套语言描述问题。领域真正缺的不是又一个模型，而是一张共识地图——告诉大家哪些问题重要、哪些路线有希望、数据与评测的缺口在哪里。",
"这篇 Cell 立场文章正是为填补这个空白而生。它由斯坦福、CZI、Arc Institute、微软研究院、MIT、Broad 等机构的四十余位学者共同署名，横跨机器学习、单细胞生物学、生物信息学与药物发现。选择在 Cell 发表本身就是一个信号：这不是写给 ML 会议看的论文，而是要写给整个生物学界的路线宣言。"],
method:[
"文章没有提出新算法，而是做了一件更难的事：定义问题。作者把虚拟细胞定义为「一个多尺度、多模态的基础模型系统，能够对细胞状态与扰动响应做出可解释的预测，并以虚拟仪器的形式与实验闭环衔接」。",
"在此基础上，文章提出三大技术支柱：其一，细胞状态的表示学习——把基因表达、染色质状态、蛋白丰度等异构数据映射到统一表示空间；其二，扰动预测——给定基因或药物干预，预测细胞状态的改变，这是因果能力的核心；其三，生成式模拟——不仅预测差异，而是合成完整的细胞状态，用于 in silico 实验。",
"与此同时，文章系统列举了数据需求（多模态、含扰动、含时空）、评估策略（以预测的可证伪性为核心）与组织模式（开放科学、共享基准、lab-in-the-loop）。这套框架后来直接催生了 Arc Institute 的 Virtual Cell Challenge。"],
results:[
"作为纲领性文件，文章不报告实验数据，其「结果」是领域组织方式的改变：文章发表后一年内，AIVC 相关的基准赛、数据联盟、开源工具链密集出现，引用数迅速冲到数百次，成为所有后续路线图论文的引用起点。",
"更实际的证据是三大支柱的说法被广泛采纳——今天的单细胞基础模型（对应支柱一）、扰动预测模型（支柱二）与 AIDO.Cell 这类世界模型（支柱三），基本都能在这张地图上找到自己的位置。"],
limits:[
"纲领性文章的宿命是模糊性：「预测任意扰动」这一愿景的可行性，正是后续批评性文献集中质疑的焦点。Ahlmann-Eltze 等指出现有模型连简单的双基因扰动都预测不好；Bereket & Leskovec 则追问基准分数与科学发现之间的断裂。",
"此外，文章对算力成本、数据治理（谁拥有训练数据）、模型风险（虚拟细胞被误用于危险场景）等着墨有限，而这些恰恰是产业化阶段最棘手的问题。"],
debate:[
"围绕这篇文章的最大争议不是技术细节而是叙事节奏：支持者认为它像蛋白质结构预测的 CASP 前夜，一张路线图足以动员整个社区；批评者则认为它把尚未验证的假设（规模定律适用于细胞）写成了既定方向，有「把愿景当路线」的风险。",
"两种解读都能在后续事件中找到证据：一方面 VCC、X-Atlas、AIDO.Cell 等确实沿着三大支柱快速推进；另一方面 2025-2026 年的评测潮（Kedzierska、Ahlmann-Eltze、Bereket）持续给热潮降温。读这篇，建议连同两篇批评一起读。"],
takeaway:[
"这是 AIVC 领域的宪法，也是本站所有栏目的骨架：单细胞基础模型、扰动预测、衰老交叉、企业解剖，本质上都是在三大支柱的棋盘上落子。无论你是研究者、投资人还是工程师，读 AIVC 都从这篇开始。",
"但要提醒的是：地图不等于领土。三大支柱回答了「做什么」，没有回答「能不能做成」。后一个问题，要靠后面七十多篇文献逐年回答。"],
further:["p04","p05","p36","p41"]},
{id:"p02",g:"g1",t:"Towards Universal Cell Embeddings: Integrating Single-Cell RNA-seq Datasets Across Species with SATURN",a:"Rosen, Brbić … Leskovec（Stanford）",v:"Nature Methods",d:"2024-08",doi:"10.1038/s41592-024-02191-z",
summary:"以蛋白语言模型嵌入基因实现跨物种图谱整合，是「通用细胞嵌入」的方法学铺垫。",
background:[
"跨物种整合单细胞数据长期受困于一个朴素事实：人和鼠的基因命名体系不同，同源基因对应关系依赖外部知识库且覆盖不全。此前方法大多要求物种间有配对的细胞类型标签，属于「有人盯着才能整合」。",
"斯坦福 Leskovec 组换了一个思路：基因的名字不可靠，那就让基因的「语义」来对齐——用蛋白语言模型为每个基因算出嵌入，把基因比较从「名字匹配」变成「语义匹配」。"],
method:[
"SATURN 的核心是蛋白语义空间：先用 ESM2 这类蛋白语言模型为基因生成嵌入，使功能相近的基因（哪怕序列差异很大）在该空间中距离接近；再设计 MACDE 相似度度量，在此空间上做类似 UMAP 的嵌入与整合，全程不需要物种间一一对应，也不需要配对标签。",
"这一设计的关键好处是零样本：模型没见过的物种，只要其基因能算出蛋白嵌入，就能直接落入统一空间。"],
results:[
"在多个跨物种数据集上，SATURN 实现了无需微调的零样本整合，整合质量与需要配对标签的监督方法相当；蛋白嵌入空间中「功能聚类」的涌现（不同名字的同一家族基因相互靠近）本身也是一个有趣发现。",
"更重要的是方法论外溢：UCE、TranscriptFormer 等后续旗舰模型都把「基因 token = 蛋白嵌入」作为标准配置，这条技术路线可以追溯到 SATURN。"],
limits:[
"整合质量受限于蛋白嵌入质量——对非编码基因、假基因、微生物基因，蛋白语义空间基本失效；此外，嵌入空间对功能相似但调控角色不同的基因（如激动型与抑制型转录因子）区分度有限。"],
debate:[
"学界对「语义对齐是否足够」有不同意见：支持者认为它优雅地绕开了同源检索的工程噩梦；怀疑者指出，蛋白序列相似不等于表达模式相似，真正决定细胞身份的是调控逻辑而非蛋白功能，这方面 SATURN 只解决了「可比」，没有解决「可解释」。"],
takeaway:["这是把 NLP 范式引入细胞生物学的关键一跳：基因=词、蛋白语义空间=词典。今天读任何一篇跨物种 scFM 论文，你都能看到 SATURN 的影子。"],
further:["p11","p13","p12"]},
{id:"p03",g:"g1",t:"An AI-Driven Digital Organism: The AIDO Framework（GenBio AI 框架文）",a:"Song, Segal, Xing 等（GenBio AI / CMU / MBZUAI）",v:"Nature Medicine",d:"2026",doi:"10.1038/s41591-026-04595-0",
summary:"提出 AI 驱动数字有机体（AIDO）框架：多尺度基础模型家族拼接为「生物学世界模型」。",
background:[
"Bunne 纲领给出愿景之后，产业界需要一个可工程化的架构回应：如何把 RNA、蛋白、细胞、组织各层的模型组织成一个连贯系统，而不是一堆各自为政的模型？这正是 GenBio AI 的 AIDO 框架要回答的问题。",
"AIDO 的定位介于学术基础模型与工业级系统之间：它既要发论文，也要交付可部署的模型家族，因此特别强调层间接口的统一与开源分发策略。"],
method:[
"AIDO（AI-Driven Digital Organism）采用分层架构：底层是模态基础模型（AIDO.RNA 管 RNA 序列与结构，AIDO.Protein 管蛋白）→ 中层是细胞层模型（GB.Cell）→ 顶层是世界模型层，层与层之间以统一表示空间衔接。",
"这个设计的核心主张是「多尺度」：分子层的错误会向上传播，组织层的约束应向下反馈，因此各层不能独立训练，而要在统一表示下协同。"],
results:[
"文章给出从分子到表型的分层建模蓝图，并报告了各层模型的初步验证；与其 2026 年 Cell 的 AIDO.Cell 世界模型论文构成「框架 + 旗舰实现」的组合。",
"更实际的影响是开源策略：AIDO.RNA、GB.Cell 经 CZI 虚拟细胞平台等渠道分发，成为社区可直接使用的大模型之一。"],
limits:[
"框架大于实证：层间表示如何对齐、误差如何跨尺度传播，目前缺少系统的定量分析；「数字有机体」这个名字承诺的完整性（代谢、应激、分裂全都要）与已交付能力之间差距明显。"],
debate:[
"怀疑者认为 AIDO 是「用世界模型的概念包装模型全家桶」；支持者则反驳说，在所有人都只发单点模型的领域，有人先把系统工程做出来本身就是贡献。判断「多尺度是不是正确答案」为时尚早，但它把虚拟细胞的工程路径第一次画全了。"],
takeaway:["GenBio AI 的路线宣言。读 GenBio 路线必须三层连读：AIDO.RNA（地基）→ GB.Cell（细胞层）→ AIDO.Cell（世界模型），单读任何一层都会误判其野心。"],
further:["p19","p20","p21","p01"]},
{id:"p04",g:"g1",t:"The Virtual Cell Challenge: A Turing Test for Cell Biology（VCC 官方评论）",a:"Roohani, Goodarzi 等（Arc Institute）",v:"Cell",d:"2025-06",doi:"10.1016/j.cell.2025.06.008",
summary:"宣布设立虚拟细胞挑战赛，对标 CASP，称之为「虚拟细胞的图灵测试」。",
background:[
"AIVC 模型各自报喜、评测口径混乱，是 2024-2025 年最突出的领域病：每篇论文都说自己 SOTA，但数据集、基线、指标各不相同，横向比较几乎不可能。领域需要的是一个像 CASP（蛋白质结构预测关键评估）那样的公共裁判。",
"Arc Institute 站出来做了这个裁判。VCC 的雄心被打过鲜明的比喻：如果模型真的理解细胞，它就应该能通过一场盲测——这就是「虚拟细胞的图灵测试」。"],
method:[
"VCC 采用年度公开赛事形式：固定数据集（以 Tahoe-100M 为核心）、固定指标（PDS 扰动判别、差异基因识别等）、盲测排行榜，设冠军奖金与 Generalist Prize。",
"与 CASP 的关键相似点是「盲测」：测试集对参赛者不可见，且指标在赛前锁定，防止针对指标过拟合。这套设计直接借鉴了结构生物学的经验教训。"],
results:[
"2025 年首届赛事吸引 114 个国家 1200+ 团队报名，百图生科 xTrimoSCPerturb 夺冠，TransPert（纯统计框架）拿到季军——后者本身就是对指标设计的讽刺。",
"官方复盘坦承「无模型在所有指标上稳定超越简单基线」，这句话被批评者反复引用，也成为 2026 年评测方法改革的起点。"],
limits:[
"指标本身仍在演化：PDS 被 TransPert 团队复盘指出存在可被统计技巧利用的盲区；数据分布单一（以癌细胞系为主），对体内生理与稀有细胞类型的覆盖不足。",
"赛事的另一隐性风险是「指标锁定效应」：当整个领域围绕一套指标优化，指标的缺陷会被整个领域放大。"],
debate:[
"支持者认为没有 VCC 就没有 AIVC 的公共进度刻度；批评者则认为一场指标有缺陷的比赛可能把领域引向错误的方向——TransPert 季军就是证据：一个「不懂生物学」的统计框架靠 exploit 指标进前三，说明指标测的可能不是领域想测的能力。",
"这场争论的产物是健康的：VCC 官方已开始修订指标，独立基准（PertEval、scFME）也随之兴起。"],
takeaway:["VCC 是 AIVC 的「CASP 时刻」基础设施。跟比赛排名不如跟评测方法的演化——后者才是领域真实进度的刻度。本站把 VCC 指标演变列为企业与选型决策的必读项。"],
further:["p48","p40","p32","p45"]},
{id:"p05",g:"g1",t:"Grow AI Virtual Cells: Three Data Pillars and Closed-loop Learning",a:"Qian, Dong, Guo 等",v:"Cell Research",d:"2025",doi:"10.1038/s41422-025-01101-y",
summary:"提出单细胞多组学、扰动组学、时空组学「三大数据支柱」框架与闭环学习路线。",
background:[
"AIVC 讨论多聚焦模型架构，但数据侧缺少系统分类：到底需要哪些数据、当前缺口在哪、应该优先建什么？在模型军备赛吸走大部分注意力时，这篇 Cell Research 文章把镜头拉回了数据。",
"作者团队的判断很直接：模型能力的天花板由数据决定，而数据布局需要一张资产负债表式的框架。"],
method:[
"文章将 AIVC 数据需求归纳为三支柱：单细胞多组学（提供细胞状态的表示）、扰动组学（提供因果关系）、时空组学（提供上下文与动力学），并提出「模型设计实验 → 机器人执行 → 数据回流 → 模型更新」的闭环学习范式。",
"三支柱的划分不是罗列，而是有功能对应：表示、因果、上下文分别支撑虚拟细胞的三种核心能力，缺任何一根支柱，对应能力就是空中楼阁。"],
results:[
"被引 50+，成为数据基础设施布局（Tahoe-100M、X-Atlas、scBaseCamp）的引用框架；三支柱的提法在后续综述与基金申请中被广泛采用。",
"闭环学习范式则与 self-driving lab 类工作呼应，成为「AI + 自动化实验」路线的理论依据之一。"],
limits:[
"框架性工作：对数据质量（批次效应、测序深度偏差、注释噪声）与标注成本的讨论较薄，而这两项恰恰是数据落地的真实成本。"],
debate:[
"争议点在优先级：作者暗示三支柱要齐头并进，而产业界实践（如 Xaira 重注扰动数据、Arc 重注数据平台）显示资源约束下必须排序。哪种排序正确，取决于你对「规模是否解决一切」的判断——这正是 X-Cell 与 GREmLN 之争在数据层的投影。"],
takeaway:["想清楚「AIVC 缺什么数据」读这篇；对企业做数据资产布局，它是资产负债表式的参照。本站「数据与基准」栏目的分类框架即源于此。"],
further:["p48","p50","p01","p18"]},
{id:"p06",g:"g1",t:"Artificial Intelligence-enabled Multi-scale Virtual Cell: Perspective, Challenges, and Opportunities",a:"Jiang, Huang, Bi 等",v:"Briefings in Bioinformatics",d:"2026",doi:"10.1093/bib/bbag104",
summary:"从多尺度视角梳理 AIVC：分子-细胞-组织贯通建模的挑战与机会。",
background:[
"现有 AIVC 绝大多数停留在单细胞/转录组尺度，「虚拟细胞」若要走向组织与器官，多尺度耦合是必须回答的问题：分子动力学管纳米，细胞模型管微米，组织模拟管毫米，三个尺度的模型如何对话？",
"这篇综述的价值在于把「多尺度」从口号拆解成可研究的问题分类学。"],
method:[
"文章梳理分子-细胞-组织三个尺度的建模方法与贯通策略，明确数字孪生范式的边界与跨尺度数据对齐的难点：尺度间表示（同一实体在不同尺度的不同描述）、动力学耦合（时间尺度差六个数量级）、验证标准（组织级预测如何证伪）。",
"在此基础上给出机会清单：空间组学作为桥梁数据、多模态基础模型作为统一表示、因果推断作为贯通逻辑。"],
results:[
"给出多尺度 AIVC 的问题分类学，被引持续上升；成为空间 AIVC 与世界模型两条支线共同引用的框架文献。",
"其「空间组学是桥梁」的判断被 Nicheformer 等原生空间模型的崛起所验证。"],
limits:["观点性综述，无统一基准；对三个尺度各自的失败模式着墨不均，分子尺度部分明显弱于细胞尺度。"],
debate:[
"多尺度路线内部就有分歧：AIDO 主张自底向上逐层搭建，另有学派主张自顶向下（从组织表型反推细胞机制）。这篇文章两派都引，也两派都不站队——作为地图它很诚实，作为路线图它不够勇敢。"],
takeaway:["多尺度是 AIVC 的下一代主战场；这篇是最佳地图。做空间 AIVC 或组织孪生项目前，先拿它的分类学对表。"],
further:["p03","p56","p21","p57"]},
{id:"p07",g:"g2",t:"scBERT as a Large-scale Pretrained Deep Language Model for Cell Type Annotation",a:"Fan Yang 等（腾讯 AI Lab；通讯：Hui Lu / Jianhua Yao）",v:"Nature Machine Intelligence",d:"2022-09",doi:"10.1038/s42256-022-00534-z",
summary:"首个 BERT 式掩码预训练大规模应用于 scRNA-seq 的模型，开创单细胞语言模型范式。",
background:[
"scBERT 出现之前，单细胞注释依赖标记基因先验与人工规则，跨数据集迁移能力差；深度学习模型虽多，但都是「从头训练一个专用模型」的旧范式，缺少预训练-微调的迁移框架。",
"2022 年的背景是：NLP 领域 BERT 的成功已经证明「大规模预训练 + 下游微调」的威力，但没人把它系统搬到单细胞数据上。"],
method:[
"scBERT 的核心动作是把细胞表达谱当作「基因序列」：以基因为 token、以细胞为句子，用 BERT 掩码重建目标在海量无标注 scRNA-seq 上预训练，再微调到细胞类型注释任务。",
"针对单细胞数据的特点（高稀疏、高维度、批次混杂），作者在输入编码与注意力上做了适配，并验证了预训练表示对批次的鲁棒性。"],
results:[
"零样本/少样本注释显著优于传统方法与从头训练的深度模型，奠定了「基因=词、细胞=句子」的隐喻——这个隐喻至今仍是整个 scFM 领域的叙事基础。",
"论文发表于 Nature Machine Intelligence，是腾讯 AI Lab 在单细胞 AI 的奠基性布局，也直接启发了国内一批跟进工作。"],
limits:[
"无扰动预测能力（BERT 式理解范式不直接产出干预后果）；预训练数据规模（百万级）远小于后续模型；掩码目标对基因共表达结构的利用不充分。"],
debate:[
"今天回看，scBERT 的模型细节已被更迭数轮（自回归、扩散、知识注入相继登场），但其范式地位没有争议：所有 scFM 的预训练-微调流程都能追溯到这篇。亦有观点认为，把 BERT 直接搬过来的做法忽视了基因调控的方向性（TF→靶基因是不对称的），这一批评后来催生了 RegFormer 等结构感知模型。"],
takeaway:["范式开创者。今天所有 scFM 的预训练目标都能追溯到这篇的思路；腾讯系在单细胞 AI 的布局由此开始。读 AIVC 模型史，这是第一章。"],
further:["p08","p09","p28","p12"]},
{id:"p08",g:"g2",t:"Transfer Learning Enables Predictions in Network Biology（Geneformer）",a:"Theodoris 等；通讯：X. Shirley Liu / Ellinor（Broad / MGH）",v:"Nature",d:"2023-05",doi:"10.1038/s41586-023-06139-9",
summary:"约 3000 万细胞上「基因秩次序列」掩码预训练，自监督编码基因网络层级。",
background:[
"基因网络知识（哪些基因受哪些转录因子调控）分散在数十年文献与数据库中，此前的方法要么手工查库，要么为每个任务单独训练。Broad 研究所的问题更进一步：能否让模型从数据中「自学」出基因调控的层级结构，并迁移到疾病机制预测？",
"这是「迁移学习进入网络生物学」的早期尝试，也是 scFM 路线第一次展示「预训练表示里编码了生物学知识」。"],
method:[
"Geneformer 的关键设计是输入表示：把每个细胞的基因按表达量排序成秩次序列（而非原始计数），使模型对测序深度与批次天然鲁棒；在此序列上做 BERT 式掩码预训练。",
"微调阶段，模型被用于转录因子靶点预测、染色质可及性预测与 in silico 扰动筛选，其中扰动筛选直接对接心肌病候选靶点实验。"],
results:[
"迁移学习在多个网络生物学任务上超越任务专用模型；in silico 筛出的心肌病候选靶点获得实验验证，是「预测→湿实验」闭环的早期范例。",
"被引 800+，与 scGPT 并列「scFM 双雄」，代表自监督迁移路线；开源权重成为后续大量工作的基座。"],
limits:[
"秩次表示丢失表达量绝对值信息——对剂量敏感的任务（药物反应）是硬伤；后续零样本评测（Kedzierska 等）显示其零样本能力被论文高估；模型对基因调控方向的刻画仍是隐式的。"],
debate:[
"Geneformer 与 scGPT 的「双雄之争」贯穿 2023-2024：前者代表掩码/理解路线与 Broad 学术生态，后者代表生成路线与工业开源生态。Kedzierska 的零样本评测给两者都泼了冷水——零样本设定下它们常不如「高变基因选择 + scVI」的简单流程，这促使整个领域重新校准宣传口径。"],
takeaway:["被引 800+ 的奠基作。其「预测靶点→实验验证」流程是 AIVC 药物发现的模板；与 scGPT 一起构成所有后续模型的默认对照系。读它的最好方式是连同 Kedzierska 的评测一起读。"],
further:["p09","p37","p36","p34"]},
{id:"p09",g:"g2",t:"scGPT: Toward Building a Foundation Model for Single-cell Multi-omics Using Generative AI",a:"Haotian Cui 等；通讯：Bo Wang（多伦多大学，现 Xaira）",v:"Nature Methods",d:"2024-02",doi:"10.1038/s41592-024-02201-0",
summary:"3300 万细胞 GPT 式生成预训练，零样本嵌入即可聚类与批次校正，微调后扰动预测领先。",
background:[
"scBERT、Geneformer 证明了掩码预训练的可行性，但 BERT 式掩码本质是「理解」——填空。生成式预训练（GPT）能否带来更强的细胞状态表示，并统一多组学（RNA/ATAC）与多任务（注释/整合/扰动）？这是多伦多大学 Bo Wang 组提出的问题。",
"2024 年初 scFM 赛道已经拥挤，scGPT 靠三件事脱颖而出：生成式架构、多组学统一词表、以及彻底的开源策略。"],
method:[
"scGPT 采用 GPT 式 Transformer，并针对 scRNA-seq 做了关键适配：针对高维稀疏基因的注意力设计、以元数据（物种、组织、技术）做条件化、为 RNA 与 ATAC 设计统一词表使多组学可共训。",
"使用方式上支持三档：零样本嵌入（直接取表示做聚类/整合）、微调（适配下游任务）、迁移学习（跨数据集复用），这套分层使用方式后来成为 scFM 的标配接口。"],
results:[
"在细胞类型注释、批次整合、扰动预测上全面领先同期；被引 1383，是领域引用最高的单篇模型论文。",
"更长远的影响在生态：开源权重与统一接口使其成为事实标准基座，后续大量工作（包括 scGPT-spatial 等变体）以其为出发点，AIVC 社区的「默认对照系」由此确立。"],
limits:[
"被 Kedzierska 等指出零样本能力不及调优基线；自回归架构在数据规模化时遇到效率瓶颈——这直接促使同一团队（Bo Wang 现于 Xaira）后来转向扩散语言模型（X-Cell）。",
"多组学统一词表在 RNA/ATAC 之外（蛋白、代谢组）的扩展性未经验证。"],
debate:[
"scGPT 的历史地位没有争议，但「生成式 vs 掩码式」的路线之争持续至今：掩码派（Geneformer、scFoundation）强调理解与稳定性，生成派（scGPT、TranscriptFormer、X-Cell）强调合成与 extrapolate。2026 年的证据（X-Cell 的 scaling law、AIDO.Cell 的有状态仿真）偏向生成派，但 X-Cell 的数据不可复现又让这场争论无法闭合。"],
takeaway:["领域事实标准基座。无论做研究还是产品，scGPT 都是默认对照系；它的演化史（scGPT → X-Cell）就是 AIVC 主流的换代史。本站模型谱系页把它作为第一代的终点与第二代的起点。"],
further:["p10","p18","p37","p21"]},
{id:"p10",g:"g2",t:"Large-scale Foundation Model on Single-cell Transcriptomics（scFoundation）",a:"郝敏升等；通讯：张学工 / 马剑竹（清华）、宋乐（百图生科）",v:"Nature Methods",d:"2024-06",doi:"10.1038/s41592-024-02305-7",
summary:"1 亿参数、5000 万+细胞，非对称 Transformer + 测序深度感知预训练。",
background:[
"主流 scFM 有两个隐含假设：基因之间对称重要、观测到的表达量就是真实表达量。清华张岂谋/马剑竹团队与百图生科盯上了第二个假设——单细胞数据中「测了多少」与「真实表达多少」被同一个测序深度变量混淆，这会系统性扭曲模型对低深度数据的理解。",
"这一观察来自对真实数据的偏差分析，而非架构直觉，是 scFoundation 的立论根基。"],
method:[
"架构上采用非对称 Transformer：基因侧压缩表达（承认基因间不对称的重要性），并配套测序深度感知的预训练策略——显式建模「测序深度」与「真实表达」的关系，让模型学会区分观测偏差与生物学信号。",
"训练规模达到 1 亿参数、5000 万+细胞，是当时最大的国产 scFM。"],
results:[
"在基因扰动预测与细胞注释上优于同期模型，特别是在低测序深度数据上优势明显（深度感知预训练直接兑现）。",
"产业影响更值得注意：其骨干后来被改造为 xTrimoGene / xTrimoSCPerturb，赢得 2025 虚拟细胞挑战赛冠军——学术模型到产业冠军的直通案例。"],
limits:[
"开源生态与社区活跃度不及 scGPT；批评性评测（Boiarsky 对 scFoundation 的深评）指出其增益部分可被简单基线复现；非对称架构对硬件友好度一般。"],
debate:[
"scFoundation 与 scGPT 之争常被框定为「中国团队 vs 北美团队」，但更有意义的分歧是架构哲学：非对称 + 领域知识（深度感知）vs 对称 + 规模。2026 年 X-Cell 的 scaling law 与 GREmLN 的小模型奇迹从两端同时挤压中间路线，scFoundation 代表的大规模中间态何去何从，是值得跟踪的产业问题。"],
takeaway:["中国团队最强 scFM 之一，也是 VCC 冠军模型的直接前身——清华系与百图生科产学研链条的标志性成果。做选型时注意：它的论文成绩与开源社区成熟度要分开评估。"],
further:["p09","p42","p04","p18"]},
{id:"p11",g:"g2",t:"Universal Cell Embeddings: A Foundation Model for Cell Biology（UCE）",a:"Rosen, Roohani；通讯：Quake / Leskovec（Stanford）",v:"bioRxiv",d:"2023-11",doi:"10.1101/2023.11.28.568918",
summary:"33 层 6.5 亿参数，8 物种 3600 万细胞自监督训练，ESM2 蛋白嵌入 token 化基因。",
background:[
"跨物种通用细胞嵌入需要一个不受基因命名差异影响的「基因表示」。SATURN 证明了蛋白语义空间可行，UCE 则把这个想法推到基础模型的规模：与其修补每个数据集，不如训练一个真正的通用模型。",
"UCE 出自斯坦福 Quake/Leskovec 组，与 Arc Institute 生态深度绑定——它从诞生起就是作为基础设施而非 SOTA 模型设计的。"],
method:[
"基因表示上，UCE 用 ESM2 蛋白语言模型把基因名转为蛋白语义嵌入作为输入 token，天然跨物种；训练上，在 8 个物种约 3600 万细胞上做大规模自监督预训练，33 层 6.5 亿参数。",
"输出上支持零样本嵌入与跨物种迁移，设计目标是一件事：给社区一个可靠的「细胞表示即插即用」组件。"],
results:[
"零样本嵌入在跨物种整合、扰动预测上表现稳健，成为 Arc 生态（scBaseCamp、STATE）的基础设施组件；VCC 官方工具链直接集成 UCE 类表示。",
"其「通用嵌入」思路影响了后续大量「表示层」工作——人们开始接受「细胞表示可以像词向量一样被复用」。"],
limits:[
"预训练算力门槛高（6.5 亿参数 + 3600 万细胞），复现成本限制学术采用；对非编码区、剪接变异、微生物基因覆盖有限；零样本能力同样受 Kedzierska 类评测的约束。"],
debate:[
"UCE 与 CZI 系的 TranscriptFormer 构成「通用细胞嵌入」的两大底座之争，背后是 Arc 与 CZI 两个生态的竞争。对普通用户，这场底座之争的实际影响是工具链站队：选 Arc 系（UCE/STATE）还是 CZI 系（TranscriptFormer/CZ CELLxGENE），往往比选模型本身更重要。"],
takeaway:["「基因 token 化」的标准答案之一，与 SATURN 一脉相承。VCC 官方工具链的核心组件——它未必是论文里最亮的模型，但是生态里最常用的基础设施。"],
further:["p02","p13","p32","p04"]},
{id:"p12",g:"g2",t:"GeneCompass: Deciphering Universal Gene Regulatory Mechanisms with Knowledge-informed Cross-species Foundation Model",a:"中科院动物所李鑫团队等「指南针联盟」",v:"Cell Research（封面）",d:"2024-10",doi:"10.1038/s41422-024-01034-y",
summary:"将启动子序列、共表达、调控网络等先验知识注入 1.26 亿人/鼠细胞预训练，「知识增强」路线代表。",
background:[
"纯数据驱动的 scFM 有一个结构性缺陷：学不到明确的调控知识（哪些基因受同一转录因子调控），因为预训练目标里没有任何「调控」的概念。中科院动物所李鑫团队的问题：把先验知识注入预训练，能否同时提升性能与可解释性？",
"这一路线在欧洲有 GREmLN，在中国有 GeneCompass，共同构成「知识增强派」，与「规模派」分庭抗礼。"],
method:[
"GeneCompass 的知识注入是多源的：启动子序列（让模型知道基因的调控元件）、共表达关系（数据驱动）、先验调控网络（文献与数据库），这些信号作为监督或结构约束进入预训练。",
"训练数据覆盖人与小鼠约 1.26 亿细胞，并做人鼠联合训练实现跨物种迁移——知识在这里同时是性能来源和迁移桥梁。"],
results:[
"在细胞注释、扰动预测上优于通用 scFM，特别是在知识覆盖好的细胞类型上优势明显；被引 145，登上 Cell Research 封面。",
"产业化上孵化百曜科技，成为中国 scFM 从论文到公司的代表案例之一。"],
limits:[
"性能依赖知识库覆盖度：对未被注释的基因、非模式物种、调控关系未知的生物学过程，增益有限；知识错误（数据库噪声）会被模型继承——「知识注入」同时是「偏见注入」。"],
debate:[
"知识增强 vs 规模路线的辩论是 2025-2026 年 AIVC 的主线之一：X-Cell 用 49 亿参数 + 2560 万扰动数据证明 scaling 有效，GREmLN 用 1030 万参数 + 网络结构证明先验有效，GeneCompass 站在两者之间。目前没有裁决性证据，但一个正在形成的共识是：知识在「数据稀疏的下游任务」上价值更高，规模在「数据密集的核心任务」上价值更高。"],
takeaway:["「知识 + 数据」混合路线的中国旗舰。对中国生态板块与百曜科技企业解剖都是核心文献；它的性能曲线也是「知识注入」策略成色的试金石。"],
further:["p14","p26","p18","p07"]},
{id:"p13",g:"g2",t:"A Cross-Species Generative Cell Atlas: The TranscriptFormer Single-cell Model",a:"Pearce 等；通讯：Quake / Karaletsos（CZI）",v:"bioRxiv",d:"2025-04",doi:"10.1101/2025.04.25.650731",
summary:"跨 12 物种 1.12 亿细胞的自回归生成式模型，零样本分类跨 6.85 亿年进化距离仍稳健。",
background:[
"CZI 的虚拟细胞战略需要一个自己的基座模型：通用、跨物种、生成式。TranscriptFormer 就是这个问题的正面回答，也是 CZI 与 Arc（UCE 系）在「通用细胞嵌入」上的底座之争的另一极。",
"此前的跨物种模型（UCE、GeneCompass）物种覆盖在 8-10 个量级，TranscriptFormer 直接把覆盖推到 12 个物种、1.12 亿细胞。"],
method:[
"以基因蛋白嵌入为词表（继承 SATURN/UCE 路线），在 12 物种 1.12 亿细胞上做自回归生成预训练；支持零样本分类与条件生成——给定细胞类型描述，可以生成符合该类型特征的转录因子程序。",
"生成式架构带来一个掩码模型没有的能力：可以作为「细胞状态的采样器」，为下游任务合成训练数据。"],
results:[
"零样本细胞类型分类跨 6.85 亿年进化距离保持稳健——从海绵到人的尺度上，模型学到的「细胞类型」概念是可迁移的，这是对「细胞状态表示存在通用结构」的强证据。",
"条件生成能力被用于数据增强与稀有细胞类型的虚拟样本合成。"],
limits:[
"尚未系统验证扰动预测能力；算力成本高，学术复现困难；预印本状态，尚未经历完整同行评审。"],
debate:[
"与 UCE 的「嵌入 vs 生成」之争延伸到生态层面：CZI 用 TranscriptFormer + CZ CELLxGENE + Virtual Cell 平台搭建全栈，Arc 用 UCE + scBaseCamp + VCC 搭建全栈。研究者选边站的理由往往不是模型性能，而是数据与工具链的锁定效应。"],
takeaway:["CZI 对「通用细胞图谱」的正面回答；与 UCE 构成 Arc/CZI 两大生态的底座之争。12 物种的覆盖度至今仍是公共模型的纪录保持者。"],
further:["p11","p02","p51","p16"]},
{id:"p14",g:"g2",t:"GREmLN: A Cellular Graph Structure Aware Transcriptomics Foundation Model",a:"Mingxuan Zhang 等；通讯：Califano（哥大）/ Karaletsos（CZI）",v:"bioRxiv",d:"2025-07",doi:"10.1101/2025.07.03.663009",
summary:"将基因调控网络图结构经图信号处理注入注意力，仅 1030 万参数即以小博大。",
background:[
"scFM 的默认叙事是「规模解决一切」：更多参数、更多细胞、更强算力。GREmLN 的作者提出一个刺耳的问题：基因调控网络是现成的强结构先验，为什么还要让模型从零学它？如果结构先验足够好，小模型能不能胜过大模型？",
"这个问题在 2026 年 X-Cell 发表 scaling law 的背景下显得格外尖锐——GREmLN 是「结构派」对「规模派」最直接的反驳。"],
method:[
"核心方法是用图信号处理把基因调控网络（GREEN、ARACNe 等推断的网络）编码为注意力偏置：注意力不再是均匀的「每个基因看每个基因」，而是沿着调控网络的边传播信号。",
"参数量因此可以压到 1030 万——比主流 scFM 小一到两个数量级，因为大部分「知识」已经编码在网络结构里，不需要参数去学。"],
results:[
"1030 万参数在细胞分类等任务上超越大一个数量级的模型——结构先验换取参数效率的直接证据，论文迅速引起领域对「scaling law 是否唯一路径」的讨论。",
"与 GeneCompass、RegFormer 一起，「知识/结构增强」从边缘路线进入主流对话。"],
limits:[
"性能依赖输入网络质量：网络推断错误（假阳性边、缺失边）直接传导到预测；任务覆盖面窄于通用 scFM，在缺少网络覆盖的生物学过程上优势消失。"],
debate:[
"GREmLN vs X-Cell 是 2026 年最大的技术路线辩论：一边是「1030 万参数 + 好结构」，一边是「49 亿参数 + 大数据」。公允的解读是两者最优解不同：数据密集、结构未知的任务（如癌细胞系扰动）利于规模，数据稀疏、结构清晰的任务（如特定通路扰动）利于结构。但叙事上，规模派声音更大——这也是 GREmLN 类工作的价值：它让领域不得不解释「为什么不用小模型」。"],
takeaway:["「小模型 + 强结构」路线的代表，与 X-Cell 的「大模型 + scaling」路线形成鲜明对照——这是 AIVC 的路线分岔口。做技术尽调时，用这篇追问规模叙事的边界。"],
further:["p18","p26","p12","p44"]},
{id:"p15",g:"g2",t:"Cell2Sentence: Teaching Large Language Models the Language of Biology",a:"Levine 等；通讯：David van Dijk（耶鲁）",v:"ICML 2024",d:"2024",doi:"10.1101/2023.09.11.557287",
summary:"将细胞写成「基因名句子」使现成 LLM 直接对细胞做自然语言推理，打通单细胞数据与通用语言模型的接口。",
background:[
"单细胞模型与通用 LLM 长期是两个世界：前者操作高维数值向量，后者操作离散符号。耶鲁 van Dijk 组问了一个跨界的傻问题——如果直接把细胞「翻译」成自然语言，通用 LLM 能不能不训练就对细胞做推理？",
"这个问题开启了一条与 scFM 并行的支线：不从零预训练细胞模型，而是把细胞数据「说」给通用 LLM 听。"],
method:[
"Cell2Sentence 的转写规则很直接：把一个细胞的基因按表达量排序，写成一句话（「GENE_A GENE_B GENE_C…」），细胞即句子，基因即词。这个句子可以直接喂给现成 LLM，做注释、比较、总结等自然语言式任务。",
"零样本设定下不改 LLM 任何权重——这与 scFM 的预训练-微调范式完全相反。"],
results:[
"零样本任务上可用，且天然获得自然语言交互界面：你可以用英文问模型「这个细胞是什么类型、和那个细胞有什么区别」，它用英文回答。",
"这个简单想法的影响力远超预期：C2S-Scale、rbio1 以及一批「LLM × 生物学」工作都建立在这条转写规则上。"],
limits:[
"表达量信息损失大（只保留排序不保留数值）；LLM 的幻觉问题原样继承；对精细任务（如低丰度差异基因）力不从心。"],
debate:[
"批评者认为这是「为了用 LLM 而用 LLM」：把细胞降维成句子再让通用 LLM 处理，不如直接用为单细胞设计的模型。支持者的反驳是：通用 LLM 带来了 scFM 没有的东西——自然语言接口、组合泛化、以及与人类知识工作流的无缝衔接。2025 年 C2S-Scale 的湿实验验证让这场辩论的天平明显倾向前者。"],
takeaway:["「细胞即语言」的极简实现，开启了 C2S-Scale 与 rbio1 这条「LLM × 生物学」支线。它的真正遗产可能是交互范式：未来的虚拟细胞，大概率能用自然语言对话。"],
further:["p16","p17","p07","p09"]},
{id:"p16",g:"g2",t:"Cell2Sentence-Scale 27B（C2S-Scale）",a:"Google DeepMind × 耶鲁 van Dijk 实验室",v:"bioRxiv",d:"2025-04",doi:"10.1101/2025.04.14.648850",
summary:"基于 Gemma-2 扩展至 27B，验证生物任务 Scaling Law；AI 假设获湿实验确证的标志性案例。",
background:[
"C2S 的零样本实验留下一个开放问题：规模化是否带来生物学能力的质变？Google DeepMind 与耶鲁的合作就是要回答这个问题——把「细胞即句子」的路线推到 27B 参数，看 scaling law 在生物任务上是否成立。",
"这个问题的赌注很高：如果成立，「LLM × 生物学」就获得了与 scFM 竞争的资格；如果不成立，这条支线将退化为小众技巧。"],
method:[
"以 Gemma-2 27B 为基座，在海量单细胞数据上继续预训练（细胞句子作为语料），系统测试规模-性能曲线；同时建立「模型提出假说 → 湿实验验证」的评估协议。",
"验证环节不是走过场：模型提出 CK2 抑制剂相关的新假说后，由耶鲁实验室做真实的体外实验检验。"],
results:[
"确认了生物任务上的 scaling 趋势——C2S 路线不是技巧，是真路线；更重要的是模型提出的 CK2 抑制剂新假设经湿实验验证（抗原呈递提升约 50%），这是目前「AI 提出可实验检验假说」最硬的完整闭环案例之一。",
"该案例被领域广泛引用，用于回应「AIVC 只会刷基准」的批评。"],
limits:[
"幻觉与可控性仍是通用 LLM 老问题；湿实验验证成本高、周期长，无法作为常规评估手段；27B 的部署成本对多数实验室是门槛。"],
debate:[
"怀疑者指出：一次成功的假说验证不能证明路线的普遍生产力，且 CK2 案例中假说的产生机制并不完全清楚（是模型推理还是训练数据中的模式匹配？）。支持者则强调：在 scFM 整体被 Ahlmann-Eltze 类评测质疑的 2025 年，任何一个「AI 假说→实验确证」的案例都值得高度重视——它至少证明这条通路存在。"],
takeaway:["目前「AI 假说 → 实验确证」最硬的证据之一。做 AIVC 可信度论证时，这是必引案例；也是本站「深度解读」栏目持续跟踪 CK2 后续临床转化的原因。"],
further:["p15","p17","p36","p41"]},
{id:"p17",g:"g2",t:"rbio1 — Training Scientific Reasoning LLMs with Biological World Models as Soft Verifiers",a:"Ana-Maria Istrate 等；通讯：Karaletsos（CZI）",v:"bioRxiv",d:"2025-08",doi:"10.1101/2025.08.18.670981",
summary:"用虚拟细胞模型 / GO 知识库作「软验证器」GRPO 后训练 Qwen2.5-3B，PerturbQA 领先。",
background:[
"C2S-Scale 证明了 LLM 能做生物学推理，但 27B 的成本与幻觉问题都在。CZI 团队换了个方向：不训练更大的模型，而是训练更会推理的小模型——关键是给推理过程一个「验证信号」。",
"这个验证信号来自一个反直觉的来源：虚拟细胞模型本身。它懂生物学（以预测能力的形式），可以充当 LLM 推理步骤的裁判。"],
method:[
"采用 GRPO 强化学习后训练 Qwen2.5-3B：模型生成的每个科学推理步骤，由虚拟细胞模型的预测与 GO 知识库共同打分（soft verifier，软验证器），奖励「推理方向符合生物学」的链条。",
"3B 小模型 + 软验证器的组合，本质是把大模型的知识蒸馏进推理能力，而不是参数规模。"],
results:[
"3B 模型在 PerturbQA 等科学推理基准上领先更大的通用模型，且推理能力可零样本迁移到其他生物任务。",
"论文同时展示了「虚拟细胞作为基础设施」的新用法：不是终端产品，而是训练其他 AI 的验证信号——这是 AIVC 定位的一次反转。"],
limits:[
"软验证器本身的错误会传播进 LLM 的推理习惯（错误奖励比没有奖励更糟）；验证信号覆盖的生物学范围有限，GO 之外的推理缺少裁判；预印本阶段。"],
debate:[
"这项工作揭示了 AIVC 生态的一个深层结构：模型之间可以互相训练（虚拟细胞教 LLM 生物学，LLM 教虚拟细胞自然语言接口），领域因此从「单点模型竞争」转向「互相增强的网络」。乐观者认为这会加速整体能力，谨慎者担心错误信号的级联——如果基座虚拟模型有系统性偏差，整个 LLM 推理层都会被带偏。"],
takeaway:["「虚拟细胞反过来训练 LLM」的反向通路——AIVC 作为基础设施而非终局的绝佳例证。对判断「虚拟细胞公司的商业模式」有直接启示：模型即平台，模型即教员。"],
further:["p15","p16","p01","p05"]},
{id:"p18",g:"g2",t:"X-Cell: Scaling Causal Perturbation Prediction Across Diverse Cellular Contexts via Diffusion Language Models",a:"Chloe Wang 等；资深作者 Bo Wang（Xaira）",v:"bioRxiv",d:"2026-03",doi:"10.64898/2026.03.18.712807",
summary:"基于 X-Atlas/Pisces（2560 万扰动细胞）训练 49 亿参数扩散语言模型，首次展示扰动预测的幂律 scaling。",
background:[
"扰动预测（给定干预，预测细胞响应）是 AIVC 因果能力的核心，但长期受困于数据规模：公开扰动数据停留在百万级，模型看不到 scaling 的拐点。Xaira Therapeutics 的答案是自建数据——X-Atlas/Pisces 图谱规模达 2560 万扰动细胞。",
"架构上，scGPT 验证过的自回归路线在如此规模上遇到效率瓶颈，团队转向扩散语言模型——这也是 Bo Wang 谱系从 scGPT 到 X-Cell 的技术换代。"],
method:[
"数据层：X-Atlas/Pisces 覆盖多细胞系、多扰动类型（基因敲除 + 药物）的 2560 万扰动细胞，是当时最大的私有扰动图谱。",
"模型层：49 亿参数扩散语言模型 + 因果扰动预测目标——不是预测「哪些基因变了」，而是预测扰动的因果效应本身。训练与评测都在统一因果框架下进行。"],
results:[
"Pearson Δ 最高提升约 5 倍；更关键的是首次给出扰动预测的 scaling law 证据——性能随数据与参数幂律提升，且未见拐点。这是 AIVC 的「GPT-3 时刻」论据：如果 scaling 成立，算力与数据的军备赛就有了明确回报预期。",
"论文同时报告跨细胞系、跨扰动类型的泛化结果，支撑「通用扰动模型」的叙事。"],
limits:[
"公司内部数据（Xaira），外部无法复现——这与学术共同体的可复现规范直接冲突；癌细胞系之外的泛化（体内、原代细胞）未充分验证；扩散架构在离散基因空间的设计仍有工程妥协。"],
debate:[
"X-Cell 与 GREmLN 构成 2026 年最大路线辩论：49 亿参数 + 私有大数据 vs 1030 万参数 + 公开网络结构。对 X-Cell 最严厉的批评不是技术而是科学规范：一家商业公司用不可复现的数据宣称 scaling law，与当年 DeepMind AlphaFold 的开放策略形成鲜明对比——领域因此分裂为「信 scaling 的」与「等复现的」两群。",
"此外，Ahlmann-Eltze 类评测的阴影仍在：X-Cell 报告的增益是否经得起统一口径的线性基线比较，尚无独立第三方验证。"],
takeaway:["Xaira 的技术宣言，也是「规模是否解决一切」之争的最新一方。与 GREmLN 的小模型路线构成 2026 年最大路线辩论。本站立场：报告其 scaling 证据，同时明确标注数据不可复现这一硬伤——这是它与其他所有旗舰论文的本质区别。"],
further:["p14","p09","p48","p36"]},
{id:"p19",g:"g2",t:"AIDO.RNA: A Large-scale RNA Foundation Model",a:"Zou, Tao 等（GenBio AI）",v:"bioRxiv",d:"2024-11",doi:"10.1101/2024.11.28.625345",
summary:"16 亿参数 RNA 基础模型，同类规模最大之一，AIDO 多尺度家族的关键一层。",
background:[
"AIDO 框架的野心是「多尺度世界模型」，而多尺度需要每一层都有强基座。RNA 层长期缺少一个规模化的基础模型——RNA 序列/结构建模与细胞级建模之间是断开的。",
"AIDO.RNA 就是补上这一层：它不是为单细胞任务设计的，而是为整个分子-细胞通路打底。"],
method:[
"16 亿参数的 RNA 基础模型，覆盖 RNA 序列与结构任务；作为 AIDO 框架的底层模态模型，其表示空间被设计为可与细胞层模型（GB.Cell）对齐。",
"训练数据涵盖大规模 RNA 序列与功能注释，预训练目标兼顾序列建模与功能预测。"],
results:[
"在 RNA 下游任务上达到同级规模 SOTA；已开源分发，成为 RNA 基座的可选项之一。",
"更重要的是框架验证：AIDO.RNA 与 GB.Cell 的表示对齐实验，是「多尺度模型可协同」的早期证据。"],
limits:[
"单模态模型——与细胞层的衔接（AIDO 框架的核心承诺）尚未充分验证；RNA 层面的性能领先没有直接转化为细胞层面预测能力的提升；开源版与论文版的一致性待检验。"],
debate:[
"「多尺度是不是正确答案」是 AIVC 最大的未决问题之一：AIDO 押注是，怀疑者（Bereket & Leskovec 一系）认为在单细胞尺度都没做好的情况下谈多尺度是叙事透支。AIDO.RNA 的意义在于它让这个争论有了可检验的载体。"],
takeaway:["AIDO 家族的地基。读 GenBio 路线必须连同 GB.Cell 与 AIDO.Cell 三层一起读，单看任何一层都会低估其架构意图，也会高估其当前能力。"],
further:["p03","p20","p21","p06"]},
{id:"p20",g:"g2",t:"GB.Cell: A Single-cell Foundation Model in the AIDO Family（原 AIDO.Cell-100M）",a:"Ho 等（GenBio AI）",v:"bioRxiv",d:"2024-11",doi:"10.1101/2024.11.28.625303",
summary:"AIDO 家族的单细胞基座模型（约 5000 万细胞训练），经 CZI 虚拟细胞平台开源分发。",
background:[
"AIDO 三层架构的中间层需要一个强单细胞模型作为世界模型的表示基础。GB.Cell（原 AIDO.Cell-100M）承担这个角色，也是 GenBio 与 CZI 生态合作的产物。",
"命名从 AIDO.Cell-100M 改为 GB.Cell 本身就是战略信号：把「AIDO.Cell」这个名字让给 2026 年的世界模型旗舰，中间层退居基础设施。"],
method:[
"约 5000 万细胞预训练的单细胞基座，兼容 AIDO 统一表示空间；预训练目标兼顾细胞状态表示与跨数据集迁移。",
"工程上的关键选择是兼容性与分发：经 CZI 虚拟细胞平台开源，接入最大的单细胞数据门户生态。"],
results:[
"经 CZI 虚拟细胞平台开源，成为社区可用的大规模模型之一；在标准下游任务上达到可用水平。",
"作为 AIDO 架构的「承重墙」，GB.Cell 的存在使 AIDO.Cell 世界模型有了经过验证的表示底座。"],
limits:[
"预训练规模小于 scFoundation/X-Cell（5000 万 vs 5000 万+/2560 万扰动）；独立评测有限，多数结论来自团队自评；在通用 scFM 的红海中没有显现出差异化优势。"],
debate:[
"对 GB.Cell 的质疑集中在「中间层陷阱」：既不像 RNA 模型有独特模态能力，又不像世界模型有宏大叙事，它的价值完全依赖上层建筑的成败。如果 AIDO.Cell 世界模型被证伪，GB.Cell 将沦为又一个普通 scFM——这是所有「架构中间层」产品的共同风险。"],
takeaway:["AIDO 三层架构的中间层；其开源策略是 GenBio 生态位的精明之处——用基础设施换生态，用生态养顶层模型。跟踪 GenBio 的读者应把它当作世界模型旗舰的前哨指标。"],
further:["p19","p21","p51","p03"]},
{id:"p21",g:"g2",t:"AIDO Cell: A Stateful World Model of the Whole Cell",a:"Xing, Song 等（GenBio AI）",v:"Cell",d:"2026-08",doi:"10.1016/j.cell.2026.08.042",
summary:"全球首个通用「全细胞世界模型」正式论文：多尺度有状态仿真，可串行运行干预序列。",
background:[
"此前所有 AIVC 模型都是「输入→输出」的静态映射：给一个扰动，返回一个差异表达列表。但真实的生物干预是连续过程——给药后 6 小时、24 小时、72 小时的细胞状态各不相同，且后续干预的效果取决于之前的状态。静态模型在结构上无法表达这种时序依赖。",
"AIDO.Cell 要解决的正是这个结构性问题：把虚拟细胞从「照相机」升级为「仿真器」。"],
method:[
"核心架构创新是「有状态」（stateful）：细胞状态被显式维护并随时间与干预序列演化，模型可以在时间轴上串行运行多次干预并观察累积效应——这是世界模型（world model）范式在细胞生物学中的正式落地。",
"多尺度表示融合分子层（AIDO.RNA 一系）与细胞层（GB.Cell）的信息；训练与评测都围绕「干预序列」而非「单次扰动」设计，这本身就重新定义了任务。"],
results:[
"可串行运行多次干预并观察累积效应；最受关注的验证是复现伊马替尼（imatinib）的机制级联——从靶点抑制到下游表型的完整因果链在仿真中依次展开，与世界模型应有的行为一致。",
"论文登上 Cell，是「虚拟细胞」从概念走向系统架构的标志性事件，引发关于「世界模型叙事是否兑现」的领域级讨论。"],
limits:[
"主要在体外/扰动图谱数据上验证，临床尺度外推未证；「世界模型」概念与实际能力的距离仍有争议——复现已知机制级联与预测未知干预之间还有量级差距；算力成本与部署门槛高。"],
debate:[
"支持者认为这是 AIVC 的范式跃迁：从预测快照到仿真动力学，任务定义都变了；怀疑者（Bereket & Leskovec 一系）认为「有状态」很大程度上是架构包装，其增益需要在统一口径下与简单时序基线比较，而论文缺少这类对照。",
"更深的争议在概念层面：「世界模型」在 RL 领域有明确含义（模型可用于规划），AIVC 借用这个词时，规划能力（反向搜索最优干预方案）尚未被证明——现在的 AIDO.Cell 更像高保真仿真器而非可规划的世界模型。"],
takeaway:["2026 年 AIVC 旗舰论文。无论你是否信「世界模型」叙事，这篇都是必读——它把「虚拟细胞」从快照预测推向动态仿真，也把领域对「什么叫理解细胞」的标准抬高了一档。本站企业解剖栏目对 GenBio 的跟踪以其交付进度为核心指标。"],
further:["p03","p19","p20","p01"]},
{id:"p22",g:"g2",t:"LangCell: Language-Cell Pre-training for Cell Identity Understanding",a:"清华 AIR 聂再清团队",v:"ICML 2024",d:"2024",doi:"10.48550/arXiv.2405.06708",pdf:"https://arxiv.org/pdf/2405.06708",
summary:"单细胞数据与自然语言描述联合预训练，实现文本-细胞跨模态检索与零样本注释。",
background:[
"细胞注释依赖离散标签（「T cell」「B cell」），但自然语言描述（「表达 IL7R 的初始 T 细胞，高表达 CCR7」）蕴含更丰富的语义，且与文献中的表达方式一致。清华 AIR 聂再清团队的问题：能不能直接用自然语言作为监督信号？",
"这与 C2S 路线殊途同归——都把自然语言引入单细胞——但 LangCell 走的是「对齐预训练」而非「转写给 LLM」。"],
method:[
"语言-细胞联合预训练：将细胞嵌入与自然语言描述对齐到同一空间，使「描述」和「它所刻画的细胞」在该空间中靠近；预训练完成后支持文本-细胞跨模态检索与零样本注释。",
"数据构建是关键工程：从文献与数据库中挖掘「细胞类型-描述」配对，质量直接决定上限。"],
results:[
"支持文本-细胞跨模态检索（用一句话搜细胞）与零样本注释（用未见过的文字描述标注细胞）；在 ICML 2024 发表，是中国团队多模态 scFM 的代表作。",
"跨模态检索能力展示了一个 scFM 很少触及的方向：细胞数据的自然语言索引。"],
limits:[
"描述文本的覆盖与质量依赖数据源——文献偏差（研究得多的细胞类型描述多）会被继承；泛化到稀有细胞类型与新的描述方式有限；对齐空间的细粒度区分度不足。"],
debate:[
"与 C2S 的路线比较是这条支线的主线：LangCell 式「对齐」保留了 scFM 的效率与可控性，C2S 式「转写」获得通用 LLM 的组合泛化与交互性。2025 年 C2S-Scale 的湿实验成功让后者声量更大，但 LangCell 式对齐在工程部署上更轻——两条支线可能长期并存，分别服务「生产管线」与「探索界面」。"],
takeaway:["清华系在多模态 scFM 的代表作；与 C2S 共同构成「自然语言 × 细胞」两条支线。对做数据产品（细胞图谱的语义检索）的团队，这篇的方法论可直接复用。"],
further:["p15","p16","p12","p07"]},
{id:"p23",g:"g2",t:"scMulan: A Multitask Generative Pre-trained Language Model for Single-cell Analysis",a:"清华张学工 / 魏磊团队",v:"RECOMB 2024",d:"2024",doi:"10.1101/2024.01.25.577152",
summary:"多任务生成式单细胞语言模型，统一注释、批次校正、供体预测于单一指令框架。",
background:[
"单细胞分析的工具碎片化是老大难：注释用一个工具、整合用另一个、供体识别再换一个，数据在工具间来回搬运。清华张学工/魏磊团队的 scMulan 走「全家桶」路线：一个模型 + 指令框架覆盖全部常见任务。",
"这个思路与通用 LLM 的「一个模型服务所有任务」同构，但在单细胞领域落地更难——任务异质性远高于 NLP。"],
method:[
"生成式预训练 + 指令微调：把不同单细胞任务统一表述为「指令 → 输出」的生成问题，一个模型通过不同指令适配注释、批次校正、供体预测等多任务，数据与流程全程统一。",
"指令化设计的副产品是交互性：用户可以用自然语言指定任务，降低了工具链的使用门槛。"],
results:[
"多任务表现均衡，工程可用性强，在 RECOMB 2024 发表；验证了「单细胞全家桶」在技术上的可行性。",
"其指令框架被后续国产单细胞工具借鉴，成为「一个模型管所有事」路线的早期样本。"],
limits:[
"单模型性能未必每项都超过专用工具——全家桶的代价是每一项都不是最强；预训练规模中等，与头部 scFM 有量级差距。"],
debate:[
"「全家桶 vs 专用工具」是工具链层面的长期争论：全家桶赢在流程统一与维护成本，专用工具赢在单点性能与可解释性。scMulan 的实验部分回答了这个问题（均衡性足够好），但领域最终形态更可能是「全家桶做底座 + 专用工具做精修」的分层结构。"],
takeaway:["清华系「全家桶」思路的代表，工程价值高于科研新意。做平台化单细胞产品的团队值得细读其任务统一化设计——这正是产品化的核心难题。"],
further:["p15","p07","p47","p09"]},
{id:"p24",g:"g2",t:"CellPLM: Pre-training of Cell Language Model Beyond Single Cells",a:"Wen, Tang 等",v:"ICLR 2024",d:"2024",doi:"10.1101/2023.10.03.560734",
summary:"将细胞间关系纳入预训练目标（「超越单细胞」），在空间转录组与扰动任务上验证有效。",
background:[
"主流 scFM 有一个隐含简化：细胞=独立句子，彼此无关。但细胞状态由细胞间互作与微环境共同决定——把细胞当孤立个体，就丢掉了组织生物学的半壁江山。",
"CellPLM 的立论是「超越单细胞」：预训练目标必须显式建模细胞-细胞关系。"],
method:[
"在预训练目标中引入细胞-细胞关系建模：共定位、配体-受体互作等关系作为监督或对比信号，使模型学到的表示包含「这个细胞在什么邻里环境里」的信息。",
"关系信息来源包括空间转录组的邻近性与配体-受体数据库，属「知识 + 数据」混合路线在关系层的应用。"],
results:[
"在空间转录组与扰动任务上验证有效——尤其扰动任务，因为扰动的效应恰恰通过细胞间互作传播（旁分泌、免疫互作）。",
"论文在 ICLR 2024 发表，是「超越单细胞」路线较早的系统性尝试。"],
limits:[
"关系建模的表达力有限（多为浅层配体-受体匹配）；大规模验证不足；对微环境中非细胞成分（基质、可溶性因子）覆盖缺失。"],
debate:[
"CellPLM 预示了后续两条主线：Nicheformer 的「原生空间预训练」与 AIDO.Cell 的「有状态演化」都可以看作「超越单细胞」的深化——从静态邻里关系到动态环境响应。这条支线的共同挑战是数据：带关系标注的单细胞数据（尤其空间数据）规模远小于普通 scRNA-seq，模型的野心受制于数据的贫瘠。"],
takeaway:["「超越单细胞」路线的早期代表，预示了 Nicheformer 等空间感知模型的方向。做组织水平虚拟细胞的团队，这篇是关系建模的起点文献。"],
further:["p56","p25","p21","p06"]},
{id:"p25",g:"g2",t:"scGPT-spatial: Continual Pretraining of Single-cell Foundation Model for Spatial Transcriptomics",a:"Wang, Cui 等",v:"bioRxiv",d:"2025",doi:"10.1101/2025.02.05.636714",
summary:"将预训练 scFM 持续适配到空间转录组，被引 49，「单细胞→空间」迁移的代表路线。",
background:[
"空间转录组数据量远小于普通 scRNA-seq（空间切片贵、平台杂），从头预训练一个空间基础模型在数据上不现实。经济可行的路线是：把已有 scFM 的能力迁移到空间域。",
"scGPT-spatial 是这条「迁移路线」的代表，与 Nicheformer 的「原生空间预训练」构成路线之争的两极。"],
method:[
"持续预训练（continual pretraining）：以预训练好的 scGPT 为初始化，在空间转录组数据上继续训练，并注入空间上下文（坐标、邻域信息）作为额外输入。",
"关键工程问题是灾难性遗忘——继续训练不能让模型丢掉单细胞阶段学到的通用表示，作者通过数据回放与分层学习率缓解。"],
results:[
"被引 49；验证了「先大规模预训练再空间适配」的可行性，在空间任务上达到有竞争力的水平，且训练成本远低于从头预训练。",
"这条路线的性价比对产业界有直接吸引力：大多数团队没有从零训练空间模型的预算。"],
limits:[
"持续预训练的灾难性遗忘风险长期存在；空间关系建模仍较浅（主要是坐标注入而非真正的邻域推理）；预印本状态。"],
debate:[
"「事后适配 vs 原生空间」之争：Nicheformer 一派认为空间信息应该在预训练第一天就进入模型，事后适配是补丁；scGPT-spatial 一派认为数据经济学站在适配路线一边。目前证据是场景依赖的——数据充足时原生占优，数据稀缺时适配占优。对多数团队，现实的选择是适配。"],
takeaway:["空间 AIVC 最经济的工程路径；与 Nicheformer 的「原生空间预训练」形成两种选择。本站建议：预算有限选适配路线，但要盯住原生路线的进展——数据规模一旦上来，天平会倾覆。"],
further:["p56","p24","p09","p06"]},
{id:"p26",g:"g2",t:"RegFormer: A Single-cell Foundation Model Powered by Gene Regulatory Hierarchies",a:"Hu, Qin 等",v:"Nature Communications",d:"2026",doi:"10.1038/s41467-026-72198-x",
summary:"把基因调控层级结构作为归纳偏置注入 Transformer，回应「结构先验 vs 规模」之争。",
background:[
"纯规模路线（X-Cell）成本高昂且数据私有，「结构派」要回答的问题是：调控层级（TF→靶基因的层级组织）是先验知识，能否替代一部分规模？RegFormer 是这个问题在 2026 年的最新答卷。",
"它与 GREmLN（图结构注入注意力）、GeneCompass（知识注入预训练）同属一个家族，但聚焦最硬的先验：调控层级的方向性。"],
method:[
"以基因调控层级（TF→靶基因的有向层级）约束 Transformer 的注意力与表示结构：让「上级基因看下级」的信息流模式与真实调控层级对齐，而不是让模型从数据里猜层级。",
"层级知识来自调控网络数据库与文献挖掘，覆盖度与质量决定方法上限。"],
results:[
"在 Nature Communications 发表，代表结构先验路线的最新进展；在调控关系明确的任务上优于同规模通用模型，参数量与训练成本显著低于规模派旗舰。",
"论文同时给出层级注入的消融实验，量化了「方向性先验」相对「无向共表达」的增益——这是该家族方法中最细致的机理分析之一。"],
limits:[
"依赖层级知识库质量；对知识未覆盖的基因与物种，方法退化为普通模型；任务覆盖面窄于通用 scFM。"],
debate:[
"RegFormer 与 X-Cell 的对比是年度最佳技术辩论：一个用公开知识 + 小模型，一个用私有数据 + 大模型。公允的裁决尚未出现，但一个趋势正在形成——2026 年的新论文越来越多地同时报告「与简单基线的比较」，这正是结构派施压的结果：领域开始要求规模派证明增益不只是数据的函数。"],
takeaway:["2026 年「结构派」的代表作；与 X-Cell 的对比是年度最佳技术辩论。做技术路线图时，把这篇与 X-Cell、GREmLN 放在同一页读——三篇合起来就是 AIVC 架构路线的完整地图。"],
further:["p14","p12","p18","p07"]},
{id:"p27",g:"g2",t:"Nephrobase Cell+: Multimodal Single-cell Foundation Model for Decoding Kidney Biology",a:"Li, Ziyadeh 等",v:"bioRxiv",d:"2025",doi:"10.1101/2025.09.30.679471",
summary:"肾脏多模态专用基座模型，代表「通用大模型 + 器官专用化」的垂直落地路径。",
background:[
"通用 scFM 在专科任务（肾脏病的细胞类型、疾病状态）上不如专用模型——通用模型的容量被整个生命树的多样性稀释。但专科数据量小，从头训练不可行。矛盾怎么解？",
"Nephrobase Cell+ 给出一个可复制的答案：通用-专用协同——用大规模预训练打底，用器官专用数据精调。"],
method:[
"多模态（RNA/ATAC/蛋白）肾脏专用预训练：在肾脏组织的数据上继续训练通用模型，注入肾脏特异的知识（细胞类型体系、疾病标志物）；结合迁移学习处理小样本。",
"专用化的关键不是数据量而是知识密度：肾脏细胞类型学与病理学的标注体系被系统注入。"],
results:[
"在肾脏细胞类型与疾病状态任务上显著优于通用模型；预印本阶段已获领域关注，是「器官专用基座」方向最早的样本之一。",
"其「通用底座 + 器官精调」配方被肾内科 AI 社区迅速跟进。"],
limits:[
"器官特异性强，跨器官迁移未验证；单器官数据规模天花板明显——肾脏数据的多样性无法与全谱系抗衡；预印本，评测口径待独立检验。"],
debate:[
"器官专用化引发一个战略问题：AIVC 的终局是「一个通用虚拟细胞」还是「数百个器官专用模型」？Nephrobase 类工作暗示后者——至少在可预见的临床落地中，专科模型的 ROI 更高。这与 Bunne 纲领的「通用」叙事存在张力，也解释了为什么肾脏、脑、心脏等专科数据联盟在 2025-2026 年密集成立。"],
takeaway:["器官专用化（肾脏 / 脑 / 肝 / 心脏）将是 AIVC 落地的普遍形态——垂直模型是产业机会所在。对企业解剖栏目，这类团队是被收购与合作的首选标的。"],
further:["p05","p28","p01","p34"]},
{id:"p28",g:"g2",t:"Single-cell Foundation Models: Bringing Artificial Intelligence into Cell Biology",a:"Baek & Song",v:"Experimental & Molecular Medicine",d:"2025",doi:"10.1038/s12276-025-01547-5",
summary:"scFM 路线综述：从预训练目标到下游迁移的系统梳理，快速入门首选。",
background:[
"scFM 文献爆炸式增长，新入门者（研究生、转行的工程师、投资分析师）缺少一张结构化的地图：预训练目标有几种？下游迁移怎么做？评测有哪些坑？",
"这篇综述的定位就是「官方入门指南」——不追新，但求全与准。"],
method:[
"系统梳理 scFM 的设计空间：预训练目标（掩码 / 生成 / 对比）、输入表示（计数 / 秩次 / 基因嵌入）、数据策略（规模 / 多样性 / 多组学）、下游迁移方法（零样本 / 微调 / 持续预训练）、评测陷阱（数据泄漏 / 基线调参不足 / 指标选择）。",
"综述的价值一半在分类学，一半在「坑清单」——后者直接决定了读者能否正确解读论文里的 SOTA 声明。"],
results:[
"成为该子方向引用最高的入门综述之一；其分类框架被大量后续论文用作方法定位的坐标系。",
"「评测陷阱」一节被 Kedzierska、Ahlmann-Eltze 类批评性工作频繁引用，形成「指南 + 批评」的互文结构。"],
limits:["综述时效性受限——2025 年后的架构换代（扩散、世界模型）覆盖不足；对争议性话题保持中立，锐度不足。"],
debate:["作为综述它没有自己的立场，但它无意中成了「中立派」的参照系：当模型论文的宣传话术越来越激进时，回归这篇的分类学是去噪的好办法。"],
takeaway:["团队新人培训指定读物。读任何 scFM 论文之前，先花一小时过一遍这篇的评测陷阱一节——能过滤掉一半的误读。"],
further:["p09","p37","p36","p28"]},
{id:"p29",g:"g2",t:"A Transcriptomics-native Foundation Model for Universal Cell Representation and Virtual Cell Synthesis",a:"Jiang & Xie",v:"bioRxiv",d:"2026",doi:"10.64898/2026.04.12.718016",
summary:"最激进路线：不满足于预测差异表达，而是直接合成完整虚拟细胞表达谱。",
background:[
"扰动预测的主流输出是「哪些基因差异表达」——一个差异列表。但 Bunne 纲领的愿景是生成完整细胞状态：虚拟细胞应该能「长」出一个完整的表达谱，而不是只列出哪里不一样。",
"输出格式的选择看似工程细节，实则定义了任务难度：预测差异是判别问题，合成完整状态是生成问题，后者要保证「没被提到的基因也合理」。"],
method:[
"转录组原生的通用表示 + 生成式虚拟细胞合成：模型直接产出完整表达谱而非差异列表；生成过程以转录组的联合分布为约束，保证全基因组一致性。",
"「转录组原生」意味着表示空间就是表达谱空间本身，不经过差异列表等中间抽象。"],
results:[
"bioRxiv 2026，代表「生成完整状态」这一最激进方向的早期尝试；初步结果显示合成表达谱在统计特性上与真实数据接近。",
"该方向与 AIDO.Cell 的有状态仿真形成「生成派」内部的两条支线：一次性合成 vs 时序演化。"],
limits:[
"生成质量与生物学合理性的验证手段尚不成熟——「统计上像」不等于「生物学上对」；对功能一致性（通路层面的协调变化）的检验缺失；预印本早期。"],
debate:[
"怀疑者认为「生成完整表达谱」是伪需求：实验检测的从来都是差异基因，完整的谱没有对应下游用途。支持者反驳：只有生成完整状态，模型才真正学到了细胞状态的分布——差异列表只是这个分布的低维投影，丢失了基因间的协变结构。这场争论的裁决取决于一个尚未出现的评测：生成状态的「功能可用性」检验。"],
takeaway:["值得关注的远期路线；它与 AIDO.Cell 的「有状态仿真」是两种世界观。本站把它列入观察名单——如果「生成完整状态」被证伪，AIVC 的叙事将被迫收缩回「预测工具」定位。"],
further:["p21","p09","p01","p18"]},
{id:"p30",g:"g3",t:"Predicting Cellular Responses to Complex Perturbations in High-throughput Screens（CPA）",a:"Lotfollahi；通讯：Theis（Helmholtz Munich）",v:"Molecular Systems Biology",d:"2023",doi:"10.15252/msb.202211517",
summary:"对抗训练将基底状态、扰动、剂量解耦为可组合潜因子，可预测未见药物组合与剂量-反应曲线。",
background:[
"高通量扰动筛选数据里，一个观测细胞的状态 = 基底状态 + 扰动效应 + 剂量，三者纠缠在一起。直接回归会把「细胞本身脆弱」误判为「药物有效」。",
"CPA 要解决的就是这个纠缠：把三个成分解耦成可组合的潜因子，才能外推到没见过的组合与剂量。"],
method:[
"条件 VAE + 对抗训练：细胞背景与扰动被编码为可组合的潜因子，对抗项保证两个潜空间互不泄露信息（背景信息不能从扰动编码中恢复，反之亦然）；由此支持插值新组合、外推剂量-反应曲线。",
"「可组合」是核心设计承诺：扰动 A + 扰动 B 的效应 = 两个潜因子相加——这既是它的能力来源，也是它的假设。"],
results:[
"在组合扰动与剂量外推上显著优于同期方法；被广泛用作基线，是组合扰动解耦的经典作。",
"剂量-反应曲线的预测能力对药物发现有直接价值——可以把昂贵的筛选变成计算机里的插值。"],
limits:[
"线性可加性假设限制组合效应表达：真实的协同 / 拮抗（1+1>2 或 <2）无法用潜因子相加刻画；对非线性相互作用（如表观遗传重塑）覆盖不足。"],
debate:[
"CPA 的「可加性假设」是后续争论焦点：GEARS 用图神经网络做非可加组合，scGen 用潜空间算术，STATE/X-Cell 用大规模数据硬学——四条路线对「组合效应本质」有不同信念。CPA 的代表性是：它第一次把这个问题形式化为「解耦 + 组合」，后续工作都在这个框架内做变体。"],
takeaway:["组合扰动解耦的经典作；「可组合潜空间」思想影响深远。做药物组合预测的团队，这篇是形式化起点——先理解可加假设的边界，再决定要不要上更复杂的架构。"],
further:["p31","p71","p32","p34"]},
{id:"p31",g:"g3",t:"scGen Predicts Single-cell Perturbation Responses（奠基文献）",a:"Lotfollahi；通讯：Theis",v:"Nature Methods",d:"2019",doi:"10.1038/s41592-019-0494-8",
summary:"VAE 潜空间「扰动向量算术」，首次系统验证深度学习可跨细胞类型外推扰动响应。",
background:[
"扰动实验昂贵且永远无法覆盖所有细胞类型：在 T 细胞里做的敲除，能预测在 B 细胞里同样敲除的后果吗？2019 年之前，这个问题只有统计学的答案（不显著外推）。",
"Theis 组的 scGen 第一次用深度学习给出系统的肯定答案——「扰动向量」在潜空间里是可迁移的。"],
method:[
"在 VAE 潜空间中做「扰动向量」加减：训练模型学习「扰动后的细胞状态 = 原状态 + 扰动向量」，其中扰动向量跨细胞类型共享；预测时把目标细胞类型的表示加上学到的扰动向量，再解码回表达谱。",
"方法极简——这既是它的优雅之处，也是它的假设（潜空间线性性）。"],
results:[
"首次系统验证跨细胞类型外推可行；开创了整个 in silico 扰动预测方向，被引数百次。",
"其「潜空间算术」范式被 CPA（可加组合）、GEARS（图推理）等后续工作继承——scGen 是这个方向的老祖宗。"],
limits:[
"单扰动假设；潜空间线性性假设强——对剂量依赖、组合效应、细胞状态依赖的复杂响应表达不足；验证集规模按今天的标准很小。"],
debate:["今天回看，scGen 的预测精度已被大规模模型远远超过，但它的历史地位没有争议：它定义了「扰动预测」这个任务本身。值得注意的是，2025 年 Ahlmann-Eltze 的评测里，精心设计的线性基线仍能追平深度模型——某种意义上，scGen 的极简精神以「基线」的形式还活着。"],
takeaway:["方向奠基作（2019）。所有现代扰动预测模型的祖先。读 CPA、GEARS、STATE 之前先读这篇——你会看清整个领域在「潜空间算术」这个范式上做了多少变体。"],
further:["p30","p71","p32","p36"]},
{id:"p32",g:"g3",t:"Predicting Cellular Responses to Perturbation Across Diverse Contexts with STATE",a:"Adduri 等；通讯：Roohani / Goodarzi（Arc Institute）",v:"bioRxiv",d:"2025-06",doi:"10.1101/2025.06.26.661135",
summary:"1 亿+扰动细胞训练的状态转移模型 + 1.67 亿观测细胞嵌入模型。",
background:[
"扰动数据高度上下文依赖：同一个基因敲除在不同细胞系、不同状态下效应迥异。要获得稳健泛化，训练数据必须覆盖足够多的上下文——这正是公共数据缺失、必须自建的地方。",
"Arc Institute 的 STATE 模型是这个判断的产物：用自建的亿级扰动数据训练「官方基线」。"],
method:[
"双模型架构：状态转移模型（输入扰动 + 上下文，预测状态改变，1 亿+扰动细胞训练）+ 观测嵌入模型（1.67 亿观测细胞的表示学习，为转移模型提供上下文表示）。",
"两模型的分工是显式的：嵌入模型负责「细胞现在是什么状态」，转移模型负责「干预会把它带到哪里」——这是虚拟细胞「表示 + 动力学」分工的最早工程实践之一。"],
results:[
"扰动效应判别提升 >50%，差异基因识别精度 >2 倍（相对既有方法）；成为 VCC 2025 官方基线——所有参赛队伍的对标对象。",
"STATE 的开源使其成为学术界做扰动预测的默认起点，与 Xaira 的私有 X-Cell 形成「开放 vs 封闭」的对照。"],
limits:[
"预印本状态，独立复现有限；癌细胞系偏差仍在——跨到原代细胞与体内环境的表现未充分验证；与 X-Cell 的差距（数据规模、架构）在 2026 年被拉开。"],
debate:[
"STATE vs X-Cell 是 2026 年扰动预测的「公开答案 vs 私有答案」之争：STATE 以开放数据与可复现性立身，X-Cell 以规模与性能碾压。有趣的是两者同源——都受 Bunne 纲领与 Arc 生态直接影响。领域的实际分裂是：复现导向的团队选 STATE，性能导向的团队（与企业）不得不面对 X-Cell 类私有模型的能力溢价。"],
takeaway:["Arc 生态的旗舰模型，VCC 的「官方答案」。与 X-Cell 的对比是 2026 看点——它同时是「开放科学能否跟上资本密度」这个元问题的试纸。"],
further:["p18","p04","p48","p31"]},
{id:"p33",g:"g3",t:"D-SPIN Constructs Gene Regulatory Network Models from Multiplexed scRNA-seq Data",a:"Jiang, Chen 等",v:"bioRxiv",d:"2023",doi:"10.1101/2023.04.19.537364",
summary:"从多重 scRNA-seq 构建基因调控网络，揭示扰动响应的组织原则。",
background:[
"扰动预测的主流是黑箱：输入扰动，输出响应，中间机制不可见。但生物学家要的不只是预测——他们想知道「为什么」，即扰动效应背后的调控网络。",
"D-SPIN 站「可解释」这一侧：从数据中重建显式网络，让预测有机制依据。"],
method:[
"从多重（multiplexed）扰动 scRNA-seq 数据推断基因调控网络结构：利用「同时扰动多个基因」的实验设计，分离直接效应与间接效应，推断 TF→靶基因的因果边；再用网络约束扰动响应建模。",
"多重扰动数据是方法的关键前提——单扰动数据无法区分「A 直接调控 B」与「A 通过 C 间接影响 B」。"],
results:[
"揭示扰动响应的组织原则（层级性、模块化）；证明显式网络结构对预测有增益——可解释与高性能不是零和。",
"方法被用于多个大规模扰动数据集的网络重建，成为因果网络推断的常用工具。"],
limits:[
"网络推断的可靠性受数据稀疏性限制（单细胞计数噪声大）；规模有限——推断全基因组网络的计算成本随基因数超线性增长；预印本阶段。"],
debate:[
"D-SPIN 代表的「显式网络派」与 scFM 的「隐式表示派」是 AIVC 的古老分歧：前者认为机制必须显式才能被生物学家信任，后者认为表示里已经隐含了机制、提取是工程问题。2026 年 Kendiukhov 的注意力分析（注意力≠调控）给隐式派的可解释性叙事泼了冷水，某种程度上有利于 D-SPIN 这类显式方法的复兴。"],
takeaway:["「可解释扰动预测」路线的代表，与黑箱 scaling 路线互补。做临床转化（医生需要知道为什么）的团队，这条路线不是可选项而是必选项。"],
further:["p39","p36","p34","p30"]},
{id:"p34",g:"g3",t:"Modelling Drug-induced Cellular Perturbation Responses with a Biologically Informed Dual-branch Transformer",a:"Guo, Zhang 等",v:"Nature Machine Intelligence",d:"2026",doi:"10.1038/s42256-025-01165-w",
summary:"生物学信息引导的双分支架构，药物诱导扰动响应建模。",
background:[
"基因扰动（敲除）与药物扰动在数据生成方式上根本不同：敲除是离散的、完全的；药物是连续的、部分的、有脱靶的。把两者混在一个模型里，会损失药物特有的信息。",
"更现实的驱动是产业需求：药企关心的是药物响应预测，而公共数据集以基因敲除为主——药物扰动数据稀缺且昂贵。"],
method:[
"双分支 Transformer：一支建模扰动信号本身，另一支注入生物学先验（通路注释、靶点关系、化合物结构信息）；两支在预测层融合。",
"「生物学信息引导」体现在先验的注入方式——不是简单拼接特征，而是让先验参与注意力结构的构造。"],
results:[
"在药物扰动预测上达到 SOTA；展示了「领域知识 + 架构」的混合设计趋势——2026 年的药物 AIVC 论文普遍采用类似配方。",
"方法对低数据场景友好（先验补偿数据不足），这对只有少量自有筛选数据的药企是关键卖点。"],
limits:[
"先验覆盖决定上限——新机制药物、无注释靶点的场景优势消失；药物化学空间的泛化（ scaffold 迁移）未充分验证。"],
debate:[
"这篇论文是「知识注入派」在药物 AIVC 的据点，与 X-Cell 式「数据硬刚」路线对比鲜明：药企自有数据永远不可能达到 2560 万细胞的规模，所以知识注入对药物场景不是情怀而是必然。这场争论的走向将决定 AIVC 药物发现公司的技术栈构成。"],
takeaway:["药物发现方向的 AIVC 论文，企业界关注度最高的一支。本站企业解剖栏目里所有「AIVC + 制药」公司的技术路线，最终都要与这篇的配方对标。"],
further:["p30","p18","p12","p67"]},
{id:"p35",g:"g3",t:"Transcriptome-wide Analysis of Differential Expression in Perturbation Atlases",a:"Nadig & Replogle 等",v:"Nature Genetics",d:"2025",doi:"10.1038/s41588-025-02169-3",
summary:"被引 68：扰动图谱差异表达分析的方法学，直指「统计口径不统一」这一隐藏变量。",
background:[
"不同扰动预测论文的评测口径（差异表达定义、基线、指标）不一致，横向比较结论不可靠——这是 AIVC 评测危机的根源之一。当每篇论文用自己的口径证明自己 SOTA 时，领域实际上没有公共进度。",
"这篇 Nature Genetics 方法学论文做的正是「口径审计」：差异表达在扰动图谱里到底应该怎么定义、怎么检验。"],
method:[
"系统研究扰动图谱中差异表达的统计方法：效应量估计、多重检验校正、基线选择（用什么做「无效果应对照」）、以及这些选择对结论的敏感性。",
"作者在多个真实扰动图谱上做了口径扰动实验——同一模型、同一数据，只改统计口径，看排名怎么变。"],
results:[
"被引 68；量化了「口径差异」对模型排名的翻转效应——某些口径下 A 模型赢，换个口径 B 模型赢，且翻转幅度大到改变论文结论的量级。",
"这项工作直接推动了 VCC 与独立基准的口径统一进程。"],
limits:["方法学论文，无新模型；对哪些口径「正确」给出的是原则而非唯一答案——实操中仍需领域共识。"],
debate:["这篇论文本身没有争议，它的存在是对整个领域宣传方式的批评。它最有价值的副产品是给读者一把尺子：以后看到「SOTA」，先问「用的什么口径、什么基线、什么校正」——三问之下，一半的 SOTA 会现形。"],
takeaway:["读所有「某模型超越基线」的论文前先读这篇——它告诉你基准成绩有多少是统计口径的产物。本站「数据与基准」栏目的方法论底座。"],
further:["p36","p40","p45","p46"]},
{id:"p36",g:"g4",t:"Deep-learning-based Gene Perturbation Effect Prediction Does Not Yet Outperform Simple Linear Baselines",a:"Ahlmann-Eltze；通讯：Huber / Anders（EMBL / 海德堡大学）",v:"Nature Methods",d:"2025-08",doi:"10.1038/s41592-025-02772-6",
summary:"系统评测表明现有深度模型整体尚不能稳定超越简单线性基线，被引 222。",
background:[
"领域默认「深度模型优于简单基线」，但此前的比较常常对简单基线不公平：基线调参不足、预处理不对齐、甚至数据泄漏。Ahlmann-Eltze 与 Huber/Anders 组要做的事，就是把裁判标准拉平。",
"这不是恶意拆台——海德堡大学组正是单细胞统计学方法的重镇，他们关心的是「领域有没有在真正进步」。"],
method:[
"统一数据、统一调参、统一统计口径，把 GEARS 等主流深度模型与精心设计的线性 / 均值基线对比：基线同样享受充分的超参搜索与预处理，深度模型不许用任何特权。",
"评测覆盖单基因与双基因扰动、未见扰动等核心设定——都是各论文里宣称优势最大的场景。"],
results:[
"被引 222：深度模型在双基因扰动上不优于简单可加模型，在未见扰动上不优于「预测均值」；许多已发表增益可归因于评估设计缺陷而非模型能力。",
"这篇论文的冲击被领域认真对待——引用速度说明它不是孤例，而是共识形成的标志。"],
limits:[
"评测范围限于特定数据集与任务（主要是 Norman 数据集的双基因扰动）；不排除未来架构突破；「线性基线」本身也是精心设计的，换个口径结论可能松动。"],
debate:[
"批评者认为作者选的基线太强（调参充分的可加模型恰好匹配双基因扰动的可加性），公平但片面；支持者认为这正是重点——如果你宣称的优势连一个公平的线性模型都打不过，优势就不存在。",
"这场争论的深层意义在于：它把 AIVC 从「发布会模式」拉回「科学模式」。模型论文的默认动作从「报 SOTA」变成「先报与线性基线的比较」——这个行业习惯的改变，主要归功于这篇。"],
takeaway:["AIVC 最重要的负面结果，被引量说明领域已认真对待。本站立场：呈现争议——这篇与所有模型发布新闻同等重要，且应该放在更前面读。任何采购或立项决策，先过这篇的检验清单。"],
further:["p71","p35","p37","p41"]},
{id:"p37",g:"g4",t:"Zero-shot Evaluation Reveals Limitations of Single-cell Foundation Models",a:"Kedzierska；通讯：Crawford / Amini（Microsoft Research）",v:"Genome Biology",d:"2025-04",doi:"10.1186/s13059-025-03574-x",
summary:"严格零样本评测：Geneformer 与 scGPT 常不如「高变基因选择 + scVI/Harmony」，被引 101。",
background:[
"scFM 论文普遍报告强零样本能力——「开箱即用、无需微调」是基础模型叙事的核心卖点。但这些对比的基线常常是弱基线（随机初始化、无预处理），而不是领域里真正好用的简单流程。",
"微软研究院的 Kedzierska 等人要检验的是：零样本 scFM 真的比「高变基因选择 + scVI/Harmony」这种传统手艺强吗？"],
method:[
"系统零样本评测：把 scFM 嵌入（Geneformer、scGPT 等）与传统流程（HVG 选择 + scVI 或 Harmony 整合）在相同任务、相同数据、相同评测协议下对比；所有方法都不微调，所有方法都享受同等预处理。",
"关键设计是「零样本」的严格定义：嵌入直接取出，不做任何任务特定训练——这才是用户零成本使用基础模型的真实场景。"],
results:[
"被引 101：零样本设定下 scFM 不稳定，常不及简单流程；scFM 的真实价值在微调效率（用少量标注达到专用模型水平）而非开箱通用推理。",
"结论被采购方广泛引用——「别为零样本能力付溢价」成为 2025 年选型会议的常见结论。"],
limits:["零样本并非 scFM 的主要使用方式——结论不否定微调价值，但拆穿了「通用智能」的包装；评测覆盖的模型与任务随领域演进需更新。"],
debate:["微软研究院既是被评测方（scGPT 生态与微软有合作）又是评测方，这个双重身份引发过讨论，但评测方法的严谨性获得了包括被批评方在内的广泛认可。更建设性的后续是：领域开始把「零样本 vs 微调」分开报告，宣传口径显著诚实化。"],
takeaway:["与 Ahlmann-Eltze 并列的两大冷水。对采购/选型决策有直接影响：别为零样本能力付溢价，把预算留给微调数据与评测。本站把它列为所有「基础模型能力」宣传的默认检验器。"],
further:["p36","p08","p09","p53"]},
{id:"p38",g:"g4",t:"A Deep Dive into Single-cell RNA Sequencing Foundation Models",a:"Boiarsky 等；通讯：Getz（Broad）/ Sontag（MIT）",v:"bioRxiv",d:"2023-10",doi:"10.1101/2023.10.19.563100",
summary:"25 个数据集多任务深评：许多改进可归因于简单统计结构而非深层表示。",
background:[
"scFM 论文各自报喜，2023 年时缺少跨模型、跨数据集的系统深评。Broad 与 MIT 的联合团队决定做第一个——他们的资历（Getz 是 scVI 生态的核心人物）让这篇评测有了特殊的权威性：批评者不是外人，是基座方法的原作者一系。",
"这个细节重要：对 scFM 最严厉的批评，往往来自最理解单细胞数据统计结构的人。"],
method:[
"在 25 个数据集上多任务评测，控制预处理与调参变量：比较多个 scFM 与传统方法，并逐层剥离变量（预处理、归一化、批次校正、模型本身），看增益到底来自哪一层。",
"「增益归因」是方法论核心——不是问「谁赢」，而是问「赢在哪里」。"],
results:[
"性能高度依赖任务与预处理；部分增益来自简单统计结构（归一化、批次处理的差异），而非模型学到的深层表示。",
"论文成为批判性评测的开路者，直接启发后续 NMI 2024 正式版与 Kedzierska 的零样本评测。"],
limits:["早期论文，模型覆盖已过时（2023 年的 scFM 已被换代数轮）；部分结论的普适性待后续验证。"],
debate:["这篇与后续批评性工作的方法论一脉相承：控制变量 + 增益归因。它确立的传统是——scFM 论文必须回答「你的增益有多少是预处理送的」，而这个提问本身就是对领域最大的贡献之一。"],
takeaway:["批判性评测的开路者；后续 NMI 2024 正式版与 Kedzierska 都延续其方法。读它主要读方法论——「增益归因」这四个字值得每个做评测的人刻在墙上。"],
further:["p42","p37","p36","p52"]},
{id:"p39",g:"g4",t:"Attention Is Not Regulation: A Systematic Analysis of Interpretability in Single-cell Foundation Models",a:"Kendiukhov",v:"BMC Genomics",d:"2026",doi:"10.1186/s12864-026-12965-8",
summary:"37 项分析、153 个统计检验：注意力权重在扰动靶点预测上不优于基因水平简单特征。",
background:[
"「注意力权重 = 调控重要性」是 scFM 可解释性的流行叙事：把模型的注意力图拿出来，说「看，这个基因关注了那个基因，这就是调控关系」。大量生物学解读建立在这个叙事上。",
"Kendiukhov 的工作是对这个叙事的系统性质检：注意力权重真的编码了调控关系吗？"],
method:[
"大规模统计分析：37 项分析、153 个统计检验，把注意力权重与基因水平简单特征（表达量、变异度）在扰动靶点预测任务上对比。检验设计覆盖多个模型与多个数据集。",
"方法上的关键是「对齐比较」——注意力和简单特征必须用同一套预测任务、同一套交叉验证，否则比较无效。"],
results:[
"注意力不优于简单特征：「注意力 = 调控」的解释在统计上不成立——注意力图里的高亮，很大程度上可以用基因的表达量差异解释，不需要引入「模型学到了调控」这种更强的声明。",
"结论对「用注意力图讲故事」的论文是当头棒喝。"],
limits:["不否定其他可解释性方法（概念激活、探针等仍有价值）；单篇统计证据，模型覆盖有限；注意力可能编码了非调控的其他信息（批次、技术噪声）。"],
debate:["这篇论文的争议不在结论而在杀伤范围：整个「scFM 注意力图 → 调控发现」的支线（包括若干高影响力论文的核心 claim）都受到波及。辩护者认为「不优于简单特征」不等于「没有信息」，但举证责任已经转移——现在需要 attention 派自己证明增益。它与 D-SPIN 的显式网络路线形成合流：可解释性可能要回到显式结构。"],
takeaway:["对「用注意力图讲故事」的当头棒喝。做机制解读时引用需谨慎——引用前先问：这个 claim 过了这篇的检验没有？"],
further:["p33","p36","p09","p39"]},
{id:"p40",g:"g4",t:"Rethinking Perturbation Discrimination Metrics: Lessons from the Virtual Cell Challenge（TransPert 团队复盘）",a:"Du, Wang 等（芝加哥大学 / 达特茅斯 / 港大）",v:"arXiv",d:"2025",pdf:"https://arxiv.org/pdf/2511.16954",doi:"10.48550/arXiv.2511.16954",
summary:"VCC 季军团队对 PDS 等指标的技术复盘，揭示当前评测指标的盲区。",
background:[
"VCC 2025 最富戏剧性的结果不是百图生科夺冠，而是一个纯统计框架（TransPert）拿了季军——一个「不懂生物学」的框架，靠对指标的深刻理解击败了大量生物学动机的模型。",
"季军团队自己出来复盘：这不是模型的胜利，是指标的漏洞。这份复盘因此格外有分量——既得利益者主动拆自己的台。"],
method:[
"对 VCC 核心指标 PDS（Perturbation Discrimination Score）做技术拆解：分析其统计构造、对数据分布敏感的部分、以及可被「合法 exploit」的空间；并用实验复盘自己的季军成绩哪些来自真实能力、哪些来自指标技巧。"],
results:[
"揭示指标盲区：PDS 对某些数据分布特征过度敏感，纯统计框架可以通过匹配这些特征获得高分而不需要任何生物学能力；这解释了「统计框架进前三」的奇观。",
"复盘推动了 VCC 官方对指标的修订讨论。"],
limits:["单团队视角；arXiv 待正式发表；对「怎么改指标」给出的方案有限，主要是诊断。"],
debate:["这篇论文的元意义在于：评测方法自身也是战场。当一个指标能决定数百万美元奖金与公司估值时，对指标的研究就不再是清流而是刚需。它与 Nadig 的口径研究、独立基准（PertEval、scFME）共同构成 AIVC 的「评测制衡三角」。"],
takeaway:["评测方法自身也是战场。跟 VCC 指标演化的读者必读；做模型评测的团队，把这篇当作「如何不被指标骗」的教材。"],
further:["p04","p35","p45","p46"]},
{id:"p41",g:"g4",t:"Are Current AI Virtual Cell Models Useful for Scientific Discovery?",a:"Bereket & Leskovec（Stanford）",v:"bioRxiv",d:"2026",doi:"10.64898/2026.04.23.719015",
summary:"Leskovec 组对 AIVC 实用性的正面追问：基准成绩好 ≠ 能做出科学发现。",
background:[
"整个领域以基准分数定义进步，但基准分数与科学发现（新机制、新靶点）之间的关系从未被检验。斯坦福 Leskovec 组——Bunne 纲领的共同作者一系——决定亲自追问：我们造的东西，到底有用吗？",
"这个提问的分量在于提问者：不是领域外的批评者，是纲领的作者之一。这种自我怀疑在快速扩张的领域里罕见且有价值。"],
method:[
"系统性质疑：从任务定义（模型优化的目标与科学发现的目标是否一致）、数据构造（训练数据的泄漏路径）、到评估（基准分数对下游发现的预测力）三个层面，逐项检验 AIVC 距离「有用的科学工具」有多远。",
"论文同时清点了少数「AI 假说→实验验证」的成功案例（如 C2S-Scale 的 CK2），并分析其可复制性。"],
results:[
"与 Ahlmann-Eltze 构成「批判双子星」；推动领域从刷分转向发现导向的评测——2026 年的多个新基准开始纳入「预测的可实验性」维度。",
"论文成为投资人尽调 AIVC 公司时的常见引用：它提供了一张「技术成熟度」的诚实地图。"],
limits:["预印本；批评性立场，建设性方案有限；对「什么算科学发现」的定义本身有争议。"],
debate:["被批评方（部分公司与实验室）认为这篇「立意否定整个领域」，回应者则认为健康领域需要这种内部批评——尤其在其作者还是纲领共同作者的情况下。公允的定位：这不是悼词，是体检报告。领域对它的反应（从辩护到采纳）本身就是成熟度的标志。"],
takeaway:["2026 年最重要的负面视角。投资人看融资，研究者看这篇。本站「深度解读」栏目以这篇与 Ahlmann-Eltze 为框架，组织整个批评与基准板块。"],
further:["p36","p37","p16","p01"]},
{id:"p42",g:"g4",t:"Deeper Evaluation of a Single-cell Foundation Model",a:"Boiarsky 等；通讯：Getz / Sontag",v:"Nature Machine Intelligence",d:"2024",doi:"10.1038/s42256-024-00949-w",
summary:"被引 24：对 scFoundation 的深度评估，揭示预训练收益随任务变化的真实曲线。",
background:[
"对旗舰 scFM 的独立深评长期缺失——论文作者自评之外，需要第三方用同等严谨度检验。Boiarsky 团队（此前做过 25 数据集深评）这次聚焦单一旗舰模型：scFoundation。",
"选择 scFoundation 有标本意义：它是「中国系最强 scFM + 产业转化冠军前身」，独立评估的结论会影响整个产学研链条的声誉。"],
method:[
"多任务、控制变量的系统评估：在不同下游任务、不同数据条件（标注量、扰动类型）下测试 scFoundation，并与替代方案（含简单方法）对比；重点分离预训练带来的收益。"],
results:[
"被引 24：预训练收益随任务与数据条件显著变化——在某些任务上增益真实存在，在另一些场景被简单方法追平；「预训练=全面提升」的叙事不成立。",
"结论对 scFoundation 的使用者是实用指导：知道在哪些任务上值得为它付成本。"],
limits:["限于 scFoundation 一代；评估时的对照模型已被后续工作（X-Cell 等）超越；部分结论的时效性有限。"],
debate:["独立评测是领域的免疫系统——它防止任何单一模型（或公司）的叙事垄断「什么是好模型」。对独立评测的支持（数据、算力、发表渠道）应该成为领域基础设施的一部分，这也是 VCC 与独立基准并存的理由。"],
takeaway:["独立评测是领域的免疫系统；支持这类研究就是支持领域健康。本站立场：每一篇旗舰模型新闻旁，都应该常备一篇独立深评。"],
further:["p38","p10","p37","p36"]},
{id:"p43",g:"g4",t:"Biology-driven Insights into the Power of Single-cell Foundation Models",a:"Wu, Ye 等",v:"Genome Biology",d:"2025",doi:"10.1186/s13059-025-03781-6",
summary:"被引 22：从生物学角度拆解 scFM 增益来源。",
background:[
"scFM 论文报告增益，但很少回答「增益的生物学含义」——模型变好，是因为它学到了真实的生物学结构，还是学到了数据的统计规律？这个问题决定 scFM 的表示能否被信任用于生物学推断。",
"这篇 Genome Biology 论文用生物学驱动的拆解实验来回答：把增益按来源分解，看哪些与真实生物结构对齐。"],
method:[
"设计对照实验分离不同增益来源：预训练数据规模、微调数据增强、表示空间的生物结构（通路、细胞类型层级）对齐度；逐项测量对下游性能的贡献。",
"「生物学驱动」体现在分析单位不是比特而是生物实体——增益要能对应到具体的生物学结构上才算数。"],
results:[
"被引 22：量化了增益来源，部分收益与数据增强效应重叠——即模型的一部分「聪明」来自等效于数据增强的正则化，而非学到的生物学。",
"对齐度高的任务（细胞类型注释）增益更真实；对齐度低的任务（跨条件预测）增益更可能是统计 artifacts。"],
limits:["实验范围有限；「真实生物结构」的 ground truth 本身依赖知识库（有循环论证风险）。"],
debate:["这篇论文是「scFM 增益归因」系列的一环（与 Boiarsky、DenAdel 互补）：前者看任务维度，这篇看生物学维度，后者看数据维度。三篇合起来给出一个正在形成的共识——scFM 的增益是结构化的、任务依赖的，不存在「预训练=全面提升」的免费午餐。"],
takeaway:["理解 scFM「为什么有效」的关键拼图。对「虚拟细胞的表示能否被生物学家信任」这个问题，这篇给出了目前最细的粒度分析。"],
further:["p38","p44","p42","p09"]},
{id:"p44",g:"g4",t:"Evaluating the Role of Pretraining Data Size and Diversity on Single-cell Foundation Model Performance",a:"DenAdel 等",v:"Nature Methods",d:"2026",doi:"10.1038/s41592-026-03120-y",
summary:"被引 18：系统分离预训练数据规模与多样性的贡献，为「数据军备赛」提供边际效益证据。",
background:[
"数据军备赛的默认假设是「越多越好」：融更多钱、收更多数据、训更大模型。但这个假设的边际效益从未被系统测量——什么时候数据规模不再带来性能提升？多样性在什么阶段比规模更关键？",
"DenAdel 等的实验把这两个变量（规模、多样性）第一次系统地分离开来。"],
method:[
"控制变量实验：固定架构与算力，系统变化预训练数据规模与多样性（物种、组织、技术平台的覆盖），测量下游性能曲线；分离两者的独立贡献与交互效应。"],
results:[
"被引 18：边际效益递减规律明确——规模过了阈值后增益趋平；多样性在特定阶段（模型见过的组织类型不足时）比规模更关键。",
"结论为「数据战略」提供了量化依据：不是无脑堆量，而是在多样性缺口最大的阶段定向补数据。"],
limits:["实验基于特定架构与任务，外推到其他模型需谨慎；「多样性」的操作性定义（按什么计量）本身有主观性。"],
debate:["这篇论文是对数据军备赛叙事最直接的实证约束——它与 X-Cell 的 scaling law 构成微妙的张力：X-Cell 说性能随数据幂律上升（在私有数据范围内），DenAdel 说公共数据范围内会递减。调和解释是：scaling 在数据多样性饱和前有效，之后需要新类型的多样性而非同质的量。这个解释如果成立，数据公司的护城河将来自多样性而非规模。"],
takeaway:["给「再融一亿做数据」的叙事泼冷水的数据点；做数据战略必读。本站对数据资产类公司的评估框架直接采用它的规模-多样性分解。"],
further:["p48","p50","p18","p05"]},
{id:"p45",g:"g4",t:"Single Cell Foundation Models Evaluation (scFME) for In-Silico Perturbation",a:"Boylan, Solovyeva 等",v:"bioRxiv",d:"2025",doi:"10.1101/2025.09.22.677811",
summary:"针对 in silico 扰动预测的统一评测框架。",
background:[
"VCC 是官方裁判，但赛事一年一次、指标持续演化、且有商业公司参与。社区需要持续的、独立的、随时可跑的评测——scFME 就是这类「民间基准」的一员。",
"它的存在本身是一种制衡：当官方评测的指标被质疑时（TransPert 复盘），民间框架提供了第二意见。"],
method:[
"统一数据、指标与流程的评测框架：把多个 scFM 与扰动预测模型放在同一扰动数据集、同一指标族、同一预处理协议下比较，代码与结果公开可复现。",
"框架设计上强调「低门槛复现」——研究者可以用它检验自己的模型，而不必等 VCC 赛季。"],
results:[
"给出可复现的横向比较结论；初步结果显示模型排名对指标选择高度敏感（与 Nadig 的口径研究互证）。",
"成为 PertEval、BioLLM 并列的三大民间评测框架之一。"],
limits:["预印本；社区采用度待观察；数据集覆盖有限，长期维护依赖志愿算力。"],
debate:["民间基准 vs 官方赛事是科学评测的经典结构（如蛋白质领域的 CASP vs CAMEO）：官方提供声望与奖金，民间提供持续与独立。AIVC 正在长出同样的双轨结构，这本身就是领域成熟的信号。"],
takeaway:["民间评测三兄弟（scFME/PertEval/BioLLM）之一，VCC 之外的制衡力量。做模型发布的团队，上线前用这三个框架各跑一遍——比自评有说服力得多。"],
further:["p46","p47","p40","p04"]},
{id:"p46",g:"g4",t:"PertEval-scFM: Benchmarking Single-cell Foundation Models for Perturbation Effect Prediction",a:"Wenteler, Occhetta 等",v:"bioRxiv",d:"2024",doi:"10.1101/2024.10.02.616248",
summary:"被引 37：扰动效应预测的标准化基准。",
background:[
"扰动预测模型雨后春笋，但缺少独立、持续的公开基准——每篇论文自带数据集与指标，比较无从谈起。PertEval 是最早系统回应这个问题的框架之一。",
"它的设计哲学是「持续基准」（living benchmark）：不是一次性论文，而是持续更新排行榜的基础设施。"],
method:[
"标准化基准与排行榜：固定扰动数据集、指标族与协议，任何模型可提交评测；重点覆盖扰动效应预测的核心设定（单基因、组合、跨条件）。",
"与 VCC 的差异在于持续性——不受赛季限制，随时可比。"],
results:[
"被引 37；成为独立评测的重要参照，其排行榜被用作模型进度的公共记录。",
"框架催生了多个后续工作对「排名稳定性」的分析——发现不同数据切片下排名会变，进一步印证口径问题。"],
limits:["数据集覆盖有限（早期以 Norman 等公共数据为主）；预印本；指标设计自身也在演化。"],
debate:["PertEval 与 VCC 的关系是「民间持续基准 vs 官方年度赛事」的分工。它最重要的贡献是提供了「非赛季时间」的公共坐标——领域不再一年只对一次表。对跟踪领域进度的读者，它的排行榜比任何单篇论文都更值得收藏。"],
takeaway:["VCC 之外最重要的民间基准之一。做选型时，把 PertEval 排行榜与 VCC 排名并排看——两者的分歧处，往往就是最有信息量的地方。"],
further:["p45","p47","p35","p04"]},
{id:"p47",g:"g4",t:"BioLLM: A Standardized Framework for Integrating and Benchmarking Single-cell Foundation Models",a:"Qiu, Chen 等",v:"Patterns",d:"2025",doi:"10.1016/j.patter.2025.101326",
summary:"标准化集成与基准框架，降低跨模型比较门槛。",
background:[
"模型碎片化是 AIVC 落地的现实障碍：每个模型有自己的数据格式、预处理流程、输出接口，「把三个模型的结果放一起比」本身就需要写大量胶水代码。",
"BioLLM 做的是胶水工作——听起来不性感，但整个领域的复现性卡在这种地方。"],
method:[
"统一接口与流程的集成框架：把多个 scFM 封装到同一套 API 下，标准化数据进出、评测协议与结果格式；用户用一致的方式调用不同模型并横向比较。",
"「LLM」在这里指框架的自然语言接口野心——用统一接口降低非专家用户的使用门槛。"],
results:[
"降低跨模型比较的实验门槛；被教育与教学场景采用（一个框架跑通所有主流模型，适合培训）。",
"框架的标准化压力反过来推动模型作者提供兼容接口。"],
limits:["框架价值依赖社区采用；封装会损失各模型的特性功能（最低公分母问题）；性能优化受统一接口约束。"],
debate:["胶水框架的经典困境：用得好是基础设施，用不好是维护负担。BioLLM 的赌注是「领域需要标准接口」——这个赌注在 NLP 领域赢了（HuggingFace 生态），在生物领域能否赢，取决于模型迭代速度是否快到让标准失效。"],
takeaway:["工程向的「胶水」工作，看似不性感但能加速整个领域。做平台化产品的团队，这篇的接口设计值得直接参考。"],
further:["p45","p46","p28","p47"]},
{id:"p48",g:"g5",t:"Tahoe-100M: A Giga-Scale Single-Cell Perturbation Atlas for Context-Dependent Gene Function and Cellular Modeling",a:"Jesse Zhang 等；通讯：Yu / Goodarzi（Tahoe Therapeutics）",v:"bioRxiv",d:"2025-02",doi:"10.1101/2025.02.20.639398",
summary:"1 亿细胞 × 1100 种小分子 × 50 种癌细胞系，被引 106，VCC 2025 核心基准资源。",
background:[
"公开扰动数据规模长期停留在百万级（Replogle 的 250 万细胞曾是天花板），无法支撑大规模模型训练。Tahoe Therapeutics 的自建图谱把这个数字推高了两个数量级——1 亿细胞 × 1100 种小分子 × 50 种癌细胞系。",
"这个赌注的前提是 Bunne 纲领的数据判断：没有规模，就没有基础模型。Tahoe 把公司命运押在了这个判断上。"],
method:[
"在 50 种癌细胞系上用 1100 种小分子构建亿级单细胞扰动图谱，并配套发布评测协议——数据以可负担的方式开放给学术社区（部分开放 + 申请制）。",
"数据设计上的关键选择是「上下文多样性」优先：细胞系覆盖广，使模型可以学习「同一药物在不同背景下的效应差异」——这正是 context-dependent gene function 的主题。"],
results:[
"被引 106；成为 STATE、X-Cell 等大模型的训练/评测底座与 VCC 2025 核心数据集——可以说没有 Tahoe-100M，就没有 2025-2026 年的扰动模型军备赛。",
"数据集本身产出了生物学发现：跨癌细胞系的药物响应图谱揭示了新的 context 依赖模式。"],
limits:[
"全部为癌细胞系——体外、永生化、基因背景破碎，体内生理相关性有限；药物扰动谱系偏窄（1100 种已上市/临床分子为主，新化学空间少）；部分开放的数据政策对学术复现仍是门槛。"],
debate:["围绕 Tahoe-100M 的争议是结构性的：它既是领域最大的开放贡献，也是商业公司的核心资产——开放与商业的边界（哪些数据免费、哪些收费）持续引发讨论。更深的批评在数据哲学：整个领域在癌细胞系上砸了亿级数据，但临床转化最需要的原代细胞与体内数据反而最稀缺——数据军备赛的方向与临床需求存在错位。"],
takeaway:["AIVC 数据军备赛的标志性资产。Tahoe 的公司命运与数据开放策略是产业观察重点——如果「规模=性能」成立，它是最接近卖水人的位置；如果 Ahlmann-Eltze 类批评最终成立，亿级癌细胞系数据的价值将被重估。"],
further:["p49","p32","p18","p04"]},
{id:"p49",g:"g5",t:"Mapping Information-rich Genotype-Phenotype Landscapes with Genome-scale Perturb-seq",a:"Replogle 等；通讯：Weissman（MIT / Whitehead / UCSF）",v:"Cell",d:"2022-07",doi:"10.1016/j.cell.2022.05.013",
summary:"首个全基因组 CRISPRi Perturb-seq（>250 万细胞），事实标准评测集。",
background:[
"基因扰动筛选此前停留在少数基因（几十到几百个）——受限于读出技术与成本。Weissman 实验室的问题是：能不能把 Perturb-seq（CRISPR 扰动 + 单细胞读出）推到全基因组尺度？",
"这个问题是后续整个扰动预测领域的奠基：没有全基因组扰动数据，就没有「预测全基因组扰动效应」这个任务。"],
method:[
"全基因组 CRISPRi 库（覆盖约两万个基因的敲低向导）+ 单细胞转录组读出（Perturb-seq 规模化），在 K562 与 RPE1 两种细胞系中产出超过 250 万个细胞的扰动图谱。",
"技术关键在于 sgRNA-细胞的高通量关联与读出成本的压缩——这是工程与生物学的联合突破。"],
results:[
"首个全基因组尺度 Perturb-seq；K562/RPE1 数据成为扰动预测模型的事实标准评测集——今天所有扰动模型论文都要在这套数据上被检验。",
"数据本身揭示了全基因组尺度的基因必需性与响应模式，成为功能基因组学的重要资源。"],
limits:[
"细胞系单一（K562/RPE1，均为癌细胞系）；读出仅转录组（无蛋白/表型层）；CRISPRi 敲低有脱靶与效率波动；数据为单时间点快照。"],
debate:["Replogle 数据集是「公共数据 vs 私有数据」之争的原点：它由公共机构产出、完全开放，成为学术模型的标准考卷；而 2025 年后的规模化竞赛（X-Atlas、Tahoe-100M）由公司主导、部分封闭。领域的隐忧是：如果未来的标准评测集都掌握在公司手里，学术研究的独立性将被削弱——这也是 VCC 选择公共数据 Tahoe 而非私有数据的部分原因。"],
takeaway:["基因组规模扰动数据的开创者；所有扰动模型都在这套数据上被检验。它的局限（癌细胞系、单时间点）也正是下一代数据集要补的缺口——读任何新扰动数据论文，先和它比这三个维度。"],
further:["p48","p32","p55","p31"]},
{id:"p50",g:"g5",t:"scBaseCamp: An AI Agent-curated, Uniformly Processed, and Continually Expanding Single Cell Data Repository",a:"Youngblut 等；通讯：Goodarzi / Roohani（Arc）",v:"bioRxiv",d:"2025-02",doi:"10.1101/2025.02.27.640494",
summary:"AI agent 自动策展 SRA 公开 10x 数据，2.3 亿细胞、21 物种。",
background:[
"公共单细胞数据（SRA）数量巨大但格式与处理流程极不一致——下载下来能直接用是例外，清洗一周是常态。这种「数据混乱税」吞噬了研究者大量时间，也让模型训练充满伪差。",
"Arc Institute 的答案是让 AI 来干这活：用 agent 自动完成检索、质控、统一处理的全流程。"],
method:[
"AI agent 自动策展：agent 自动检索 SRA 上的 10x 数据，执行质控判断（样本质量、批次问题）、统一处理流程（标准化归一化与注释），形成持续更新的统一数据集；全程可复现、可审计。",
"「持续扩展」是设计目标：新数据上传 SRA 后，agent 自动纳入流水线，数据集像活的一样生长。"],
results:[
"2.3 亿细胞、21 物种——当时最大的公开单细胞库；证明了 agent 化数据工程在规模与质量上可行。",
"数据集成为 UCE、STATE 等 Arc 生态模型的重要训练来源。"],
limits:[
"自动策展的质控上限——agent 的判断错误会静默进入数据集；10x 之外平台（Smart-seq、空间平台）覆盖有限；预印本，长期维护依赖 Arc 持续投入。"],
debate:["scBaseCamp 是「AI 编辑部」的镜像：AI 不仅读文献，也开始造数据。这个信号的意义超出数据集本身——当数据工程被 agent 化，数据资产的边际成本大幅下降，「数据护城河」的叙事需要重估。反向的风险是：agent 策展的系统性偏差（如偏好某些物种/平台）会无声地塑造整个领域的训练数据分布。"],
takeaway:["「AI 编辑部」的镜像：AI 不仅读文献，也开始造数据。数据基础设施自动化的信号弹——本站「数据与基准」栏目跟踪 agent 策展质量的核心案例。"],
further:["p51","p48","p11","p05"]},
{id:"p51",g:"g5",t:"CZ CELLxGENE Discover: A Single-cell Data Platform for Scalable Exploration, Analysis and Modeling",a:"CZI Cell Science Program",v:"Nucleic Acids Research",d:"2024",doi:"10.1093/nar/gkae1142",
summary:"被引 387：CZI 单细胞数据门户论文，AIVC 数据基础设施中枢。",
background:[
"单细胞数据分散在无数论文附件与私有服务器里，检索与统一访问困难——这是单细胞领域最基础也最顽固的摩擦。CZI（Chan Zuckerberg Initiative）的 CELLxGENE 项目从 2019 年起就试图解决这个问题。",
"到 2024 年，它已经从「数据浏览器」演化为「数据 + 模型分发的生态平台」，这篇 NAR 论文是其阶段性总结。"],
method:[
"统一门户：定义数据 schema（细胞元数据标准）、提供浏览器与 API、建设与模型生态（CZI Virtual Cell 平台）的衔接；数据由上传者策展，平台保证格式一致与可发现性。",
"工程重点是规模：百万级细胞的可交互浏览与跨数据集的联邦式检索。"],
results:[
"被引 387；成为社区最大的单细胞数据入口，也是 CZI 模型（TranscriptFormer、GB.Cell 等）的分发通道——「数据门户 + 模型平台」的双轮结构。",
"其 schema 事实上成为单细胞元数据的交换标准，被大量工具链采纳。"],
limits:["策展依赖上传者，质量参差；平台长期维护依赖 CZI 战略与资金；与 scBaseCamp 的「agent 自动策展」相比，人工/上传制在覆盖速度上处于劣势。"],
debate:["CZ CELLxGENE 与 scBaseCamp 代表了数据基础设施的两种范式：人类策展的精选超市 vs AI 策展的自动货栈。短期看前者质量更稳，长期看后者规模与更新速度占优——两种范式可能融合（agent 策展 + 人工审核层）。对用户，真正的风险是平台依赖：数据入口掌握在单一基金会手里，其战略转向会波及整个生态。"],
takeaway:["CZI 是 AIVC 的「基金会基础设施」；这个平台的兴衰直接影响生态。做数据发布的团队，先读这篇的 schema 设计——兼容它，就是接入最大的分发渠道。"],
further:["p50","p13","p11","p05"]},
{id:"p52",g:"g6",t:"Deep Generative Modeling for Single-cell Transcriptomics（scVI）",a:"Lopez 等；通讯：Yosef（UC Berkeley / UCSF）",v:"Nature Methods",d:"2018",doi:"10.1038/s41592-018-0229-2",
summary:"基于 VAE 的单细胞概率建模框架，零样本评测中大模型必须击败的经典基线。",
background:[
"单细胞数据的统计特性（稀疏、过离散、批次混杂）长期被标准 NLP 式流水线粗暴处理。scVI 的立论是：为单细胞数据设计一个「对」的概率模型——负二项似然匹配计数过离散、潜空间匹配细胞异质性、批次作为协变量显式建模。",
"2018 年的 scVI 是 scvi-tools 生态的起点，今天它是整个单细胞深度学习的概率框架之祖。"],
method:[
"VAE + 负二项分布似然 + 批次协变量：编码器把细胞映射到潜空间，解码器以负二项分布重建计数；批次效应作为条件变量显式分离，使整合后的表示去批次而不失真。",
"框架设计强调「插件化」——后续 totalVI（多组学）、scArches（迁移）都建在同一框架上。"],
results:[
"成为单细胞分析的基础设施，被引 3000+；至今仍是零样本评测的标准基线——所有 scFM 论文里都必须出现的对照组。",
"其生态（scvi-tools）是学术单细胞工具链的支柱之一。"],
limits:["非基础模型——无跨数据集预训练能力，每个数据集要单独训练；潜空间维度与先验需要人工设定；对超大规模数据的训练效率一般。"],
debate:["scVI 的历史地位有种讽刺性：它作为「基线」被无数大模型论文引用比较，却始终打不死——Kedzierska 评测里它仍是零样本设定的强基线。这引出一个深层问题：scFM 的「预训练」相对「每个数据集训一个 scVI」的真实增量到底有多少？领域至今没有整齐的答案，但「先过 scVI 这关」已成为不成文的评审标准。"],
takeaway:["所有 scFM 论文里都必须出现的对照组。判断新模型成色，先看它能不能过 scVI 这关——过不了的模型，宣传得再响也要打问号。"],
further:["p53","p54","p37","p09"]},
{id:"p53",g:"g6",t:"Fast, Sensitive and Accurate Integration of Single-cell Data with Harmony",a:"Korsunsky 等；通讯：Raychaudhuri（Broad / Harvard）",v:"Nature Methods",d:"2019",doi:"10.1038/s41592-019-0619-0",
summary:"高效数据整合方法，多项评测显示其批次校正仍优于大模型零样本嵌入。",
background:[
"批次效应整合是单细胞分析的老大难，早期深度方法（如 scVI）效果好但计算慢、调参繁。Korsunsky 的问题是：能不能用更简单的机制达到可比的整合质量，且能扩展到百万级细胞？",
"Harmony 的答案出人意料地朴素——不用深度学习，用迭代聚类校正。"],
method:[
"迭代式聚类校正：在低维嵌入空间上迭代执行「聚类→按批次校正簇中心→重新嵌入」，以 O(n) 复杂度逼近批次共享的最大多样性方向；无神经网络、无训练过程、参数极少。",
"无深度学习的定位是卖点也是哲学：把整合当作统计对齐问题，而不是表示学习问题。"],
results:[
"快速且整合质量高，迅速成为单细胞流程的标准组件；在 Kedzierska 等评测中作为「简单基线」多次击败 scFM 的零样本嵌入。",
"「简单方法仍能打」的标志性案例之一。"],
limits:["无迁移/预训练能力——每个数据集独立运行；表示学习能力有限（不做语义压缩）；对复杂多批次结构的校正可能过度（生物学信号被一并抹平）。"],
debate:["Harmony 对 scFM 的讽刺在于：一个 2019 年的无深度方法，在零样本批次整合上多次击败 2023-2024 年的大模型。辩护者说这恰恰说明 scFM 应该专注微调场景；批评者说这暴露了 scFM 预训练目标的错位——如果预训练连批次整合都不解决，它学到了什么？这场争论推动了 scFM 预训练目标的设计反思。"],
takeaway:["「简单方法仍能打」的又一证据。用它做基线是评测严谨性的最低要求——本站对任何「整合能力」宣传的默认检验：先和 Harmony 比。"],
further:["p52","p37","p09","p38"]},
{id:"p54",g:"g6",t:"totalVI: Integrated Analysis of Multi-modal Single-cell Data",a:"Gayoso 等（Yosef 组）",v:"Nature Methods",d:"2021",doi:"10.1038/s41592-020-01050-x",
summary:"RNA + 蛋白联合建模的概率模型，多组学整合的经典参照系。",
background:[
"CITE-seq 等技术让 RNA + 蛋白的联合读出成为常规，但多组学数据的联合建模缺少原则性框架：两个模态的噪声结构不同、稀疏性不同，简单拼接会失真。",
"totalVI 是 scVI 框架向多模态的自然延伸，也成为多组学整合的经典参照。"],
method:[
"在 scVI 的概率框架上扩展联合潜空间：细胞共享一个潜表示，RNA 与蛋白各自有模态特异的解码器与似然（蛋白用负二项/泊松变体）；缺失模态可按后验推断，支持「有 RNA 无蛋白」的数据。",
"概率框架的好处是可处理缺失——这在真实多组学数据（模态 dropout 常见）中是硬需求。"],
results:[
"成为多组学整合标准工具；WNN（加权最近邻，Seurat 的多模态策略）等后续工作以其为比较基准或基础组件。",
"框架被后续多模态 scFM（如 scGPT 的多组学词表设计）频繁引用为方法论前身。"],
limits:["仅两模态（RNA + 蛋白），ATAC/空间模态需另想；无跨数据集预训练；对模态间非线性对齐的表达力有限。"],
debate:["多模态整合的路线之争旷日持久：概率模型派（totalVI）强调缺失处理与不确定性，深度联合派（scFM 统一词表）强调跨模态语义对齐。2026 年的趋势是合流——scFM 吸收概率模型的缺失处理，概率模型吸收大模型的预训练。做多组学产品选型时，两条路线都该测。"],
takeaway:["多组学整合的基线；做模态融合先跟它比。任何宣称多模态能力的模型，如果不在 totalVI 参照系下评估，其多模态声明是不完整的。"],
further:["p52","p55","p09","p27"]},
{id:"p55",g:"g6",t:"Mixscape / ECCITE-seq: Multimodal Analysis of CRISPR Screens with Protein and Transcriptome Readout",a:"Papalexi 等；通讯：Satija（NYGC）",v:"Nature Genetics",d:"2021",doi:"10.1038/s41588-021-00778-2",
summary:"CRISPR 筛选与单细胞多组学读出的统计分析方法，扰动效应定量的常用基线。",
background:[
"CRISPR 筛选实验产生的数据有特殊的统计结构：每个细胞带有一个（或多个）向导 RNA，扰动效应要在「单细胞 + 多组学读出」的框架下定量，而传统 bulk 筛选的统计方法不适用。",
"Mixscape 与 ECCITE-seq 分别是这个问题的方法侧与实验侧答案——两者同篇发表，构成完整的「实验 + 分析」方案。"],
method:[
"Mixscape：混合效应模型处理 CRISPR 筛选的单细胞数据，分离扰动效应、细胞状态与批量噪声；支持多重筛选（每个细胞多个扰动）的分析。",
"ECCITE-seq：实验协议侧，扩展 CITE-seq 到 CRISPR 筛选场景，实现 RNA + 蛋白 + 向导的联合读出。"],
results:[
"成为扰动筛选实验分析的标准流程；被后续所有做 CRISPR 筛选 + 单细胞读出的实验室采用为标准方法。",
"为「扰动效应定量」提供了统计基线——模型预测的效应要与 Mixscape 类方法测量的效应比较才有意义。"],
limits:["非预测模型，只是分析工具；对复杂设计（多向导、时序扰动）的扩展有限；方法假设效应可加。"],
debate:["Mixscape 的价值在「实验-分析」闭环中的位置：它是把湿实验数据变成「效应标签」的机器，而扰动预测模型消费这些标签。这个分工意味着——如果 Mixscape 类方法的效应估计有偏，所有在其上训练的模型都继承偏差。领域对「标签质量 → 模型上限」的传导链重视仍不足，这是比模型架构更根本的问题。"],
takeaway:["扰动实验的方法学底座；做湿实验 AIVC 闭环时的工具箱成员。本站「数据与基准」栏目把标签质量列为扰动模型评估的第一变量。"],
further:["p49","p30","p31","p32"]},
{id:"p56",g:"g7",t:"Nicheformer: A Foundation Model for Single-cell and Spatial Transcriptomics",a:"Theis 团队（Helmholtz Munich）",v:"Nature Methods",d:"2025",doi:"10.1038/s41592-025-02814-z",
summary:"将空间上下文纳入基础模型预训练，弥补单细胞快照缺失的组织空间维度。",
background:[
"单细胞测序把组织打散成细胞悬液，空间邻接信息永久丢失——而细胞状态很大程度上由微环境（niche，生态位）决定。把细胞当孤立个体建模，等于假装组织不存在。",
"Theis 团队（scGen/CPA 一系）的 Nicheformer 把「生态位」直接编码进模型名字与预训练目标。"],
method:[
"原生空间预训练：把空间邻域（每个细胞周围的其他细胞及其表达）作为输入上下文参与预训练，模型学到的每个细胞表示天然包含「我在什么邻里环境里」的信息；同时兼容普通单细胞数据（无空间信息时降级运行）。",
"与 scGPT-spatial 的「事后适配」相对，这是「第一天就把空间放进去」的路线。"],
results:[
"在空间任务上优于「单细胞模型 + 事后适配」路线——尤其在邻域依赖强的任务（ niche 特异性细胞状态、细胞间通讯推断）上优势明显。",
"论文发表于 Nature Methods，使「原生空间」成为空间 AIVC 的主流范式之一。"],
limits:[
"空间数据规模小，预训练数据瓶颈明显——这是整个空间 AIVC 的结构性约束；空间平台（Visium、Xenium 等）的分辨率与基因覆盖差异大，统一表示困难。"],
debate:["「原生空间 vs 事后适配」之争尚未有定论：原生派（Nicheformer）认为空间信息必须进入预训练，适配派（scGPT-spatial）认为数据经济学站在适配一边。2026 年的现实是两条路线并存——预算充足的团队建原生模型，预算有限的团队做适配。但一个共识正在形成：空间是虚拟细胞的必选项，不是可选项。"],
takeaway:["「原生空间 vs 事后适配」的路线之争一方；指向「会呼吸的虚拟细胞」。本站把空间 AIVC 列为 2026-2027 年最值得跟踪的支线——组织尺度的虚拟细胞才是临床转化的真正入口。"],
further:["p25","p24","p57","p06"]},
{id:"p57",g:"g7",t:"Spatial Transcriptomic Clocks Reveal Cell Proximity Effects in Brain Ageing",a:"Sun, Zhou 等",v:"Nature",d:"2025",doi:"10.1038/s41586-024-08334-8",
summary:"证明细胞邻近关系本身携带衰老信息——衰老也是空间组织结构的改变。",
background:[
"衰老研究长期聚焦「细胞内在状态」：端粒、表观遗传、代谢。但这篇 Nature 论文把镜头转向空间——衰老是否也表现为组织空间结构的改变？细胞和谁相邻，本身携带衰老信息吗？",
"这个问题把衰老生物学与空间组学两条线接在了一起，也直接推导出衰老 AIVC 的架构需求。"],
method:[
"空间转录组 + 衰老时钟建模：在空间数据上构建衰老预测模型，并系统分离「细胞内在衰老信号」与「邻域/空间组织贡献」——后者通过比较「细胞自身特征」与「包含邻里信息的特征」的预测力来量化。"],
results:[
"细胞邻近关系显著贡献衰老信号——空间维度是衰老建模的必要组成；空间时钟在多个脑区验证了稳健性。",
"这一发现改变了衰老标志物的搜索范围：不仅要看细胞里有什么，还要看细胞和谁住在一起。"],
limits:["脑组织单一；空间数据分辨率限制（spot 级数据混合多细胞）；横断面设计无法直接推断因果。"],
debate:["「邻域效应」的解释有分歧：一派认为是微环境（旁分泌、代谢互作）驱动了衰老表型，另一派认为是衰老的组织在空间上重排（衰老细胞聚集）。两种解释对干预设计含义不同——前者指向微环境干预，后者指向空间结构干预。论文数据支持两者并存。"],
takeaway:["衰老 × 空间的桥梁论文；直接推导出「衰老 AIVC 必须纳入空间维度」的结论。本站衰老交叉板块把它作为「衰老 AIVC 任务定义」的支柱文献。"],
further:["p56","p58","p68","p06"]},
{id:"p58",g:"g7",t:"SenNet Recommendations for Detecting Senescent Cells in Different Tissues",a:"Suryadevara, Hudgins 等",v:"Nature Reviews Molecular Cell Biology",d:"2024",doi:"10.1038/s41580-024-00738-8",
summary:"被引 391：衰老细胞检测的权威共识，衰老 AIVC 的标注基础。",
background:[
"「衰老细胞」（senescent cell）缺少跨组织统一的可操作定义——它不是一个有清晰边界的细胞类型，而是一种细胞状态，且标志物跨组织差异巨大。没有标注标准，就没有训练数据；没有训练数据，衰老 AIVC 无从谈起。",
"NIH SenNet 联盟的这份共识推荐就是来补这个地基的。"],
method:[
"共识方法：系统评估现有衰老标志物（p16、p21、SA-β-gal、SASP 因子、形态学特征等）在不同组织中的可靠性，给出多标志物组合的检测标准与组织差异的处理规则；重点是「可操作」——标准要能被实验与计算流程执行。"],
results:[
"被引 391；成为衰老单细胞/空间数据标注的行业标准——做衰老 AIVC 的团队都以它作为标签体系的参照。",
"共识同时明确了「不存在单一通用标志物」这一负面结论，直接推动了数据驱动检测方法（如 DeepScence）的发展。"],
limits:["共识随技术演进需更新；体内动态（细胞进入/退出衰老状态的时间过程）仍难捕捉；标准对罕见细胞类型的覆盖有限。"],
debate:["共识的内部张力在于「特异性 vs 敏感性」：保守的标志物组合特异性高但漏检多，宽泛的组合反之。SenNet 选择按组织场景给出不同严格度——这个务实选择被证明是对的，但也意味着「衰老细胞」的标签在不同数据集间不完全可比，模型训练时必须显式处理这个异质性。"],
takeaway:["做衰老 AIVC 前先读这篇——没有标注标准就没有训练数据。本站衰老交叉板块的标注规范直接采用 SenNet 框架。"],
further:["p76","p59","p60","p68"]},
{id:"p59",g:"g7",t:"Single-cell and Spatial Detection of Senescent Cells using DeepScence",a:"Qu, Ji 等",v:"Cell Genomics",d:"2025",doi:"10.1016/j.xgen.2025.101035",
summary:"深度学习实现衰老细胞的单细胞与空间检测；冻结的 scFM 表示已编码衰老信号。",
background:[
"共识标志物组合在单细胞数据上噪声大（基因表达稀疏、标志物共变），检测性能受限。更深的机遇是：通用 scFM 的表示里可能已经「免费」编码了衰老信号——如果成立，衰老检测的门槛将远低于想象。",
"DeepScence 同时验证了这两件事：数据驱动检测是否优于标志物评分？通用表示是否够用？"],
method:[
"深度学习模型（DeepScence）在单细胞与空间数据上检测衰老细胞；同时做了对照实验——用冻结的通用 scFM 表示（不微调）训练简单分类器，检验「通用表示中衰老信号的可及性」。"],
results:[
"检测性能优于标志物评分；更关键的发现是冻结的 scFM 表示已包含可用的衰老信号——通用模型的表示空间里，「衰老」是一个现成的方向。",
"这被领域解读为衰老 AIVC 的「ImageNet 时刻」预演：预训练表示降低垂直任务的启动成本。"],
limits:["训练数据偏向特定组织（小鼠与人的部分组织），跨物种与跨组织泛化未充分验证；检测的是「衰老样状态」而非因果意义上的衰老驱动因素。"],
debate:["「冻结表示可用」的发现有个推论争议：如果衰老信号在通用表示里现成，那衰老 AIVC 还需要专门的数据与模型吗？谨慎的回答是：检测（识别衰老细胞）可以用通用表示，但干预（什么能逆转衰老）需要因果数据——后者恰恰是当前最缺的。DeepScence 降低了入场费，但没改变游戏规则。"],
takeaway:["衰老 AIVC 的「ImageNet 时刻」预演：现成表示里已有可用信号，垂直任务门槛比想象低。对做衰老赛道的团队，这篇是成本结构分析——先验证通用表示，再决定自建模型。"],
further:["p58","p60","p68","p09"]},
{id:"p60",g:"g7",t:"Charting Human Cellular Senescence in Aging and Disease",a:"Suryadevara, Farzad 等",v:"Cell",d:"2026",doi:"10.1016/j.cell.2026.05.028",
summary:"绘制衰老与疾病中的人类细胞衰老全景图谱。",
background:[
"人类衰老细胞在组织里到底分布在哪、和哪些疾病相关？此前的证据零散（单组织、小鼠为主），缺少系统的人类全景图。",
"这篇 Cell 论文是 SenNet 联盟框架下的人类数据旗舰——把共识标准应用到多组织人类样本，产出领域最重要的衰老参考数据集。"],
method:[
"多组织人类样本的单细胞/空间图谱绘制：覆盖衰老相关组织与疾病状态，按 SenNet 共识标准标注衰老细胞，并做跨组织、跨疾病的比较分析。"],
results:[
"衰老 AIVC 最重要的参考数据集之一；揭示了衰老细胞的组织分布规律与疾病关联模式（哪些组织中衰老细胞积累与病理高度相关）。",
"数据与标注体系开源，成为衰老模型的默认训练/评测资源。"],
limits:["图谱静态（横断面），纵向动态缺失；样本量与组织覆盖受供体资源限制；疾病的因果关系仍需干预实验验证。"],
debate:["「图谱 vs 干预」是衰老研究的永恒张力：图谱告诉我们衰老细胞在哪，不告诉我们清除它们是否安全有效（SenNet 数据里衰老细胞也出现在组织修复等有益场景）。这篇论文的数据正在被用来设计靶向清除策略——但领域共识是：先有因果数据（谁驱动、谁旁观），再有干预。这与 AIVC 的因果化议程（VCWM 方向）完全同构。"],
takeaway:["衰老 AIVC 的数据基石；与 SenNet 共识配套使用。本站衰老交叉板块把它列为「入门三件套」（共识 + 图谱 + 检测）的中枢。"],
further:["p78","p58","p59","p69"]},
{id:"p61",g:"g8",t:"DNA Methylation Aging Clocks: Challenges and Recommendations",a:"Bell, Lowe 等",v:"Genome Biology",d:"2019",doi:"10.1186/s13059-019-1824-y",
summary:"被引 1026：DNAm 衰老时钟的权威综述，确立该分支方法学框架。",
background:[
"2013 年 Horvath 时钟之后，DNAm 衰老时钟论文爆发，但方法学混乱：CpG 位点选择、回归方法、验证标准各不相同，许多「新时钟」与旧时钟的差异说不清是方法改进还是过拟合。",
"这篇综述的使命是立规矩：把时钟构建从炼金术变成工程学。"],
method:[
"系统综述 + 方法学建议：训练集选择（组织、年龄跨度）、正则化、验证协议（独立队列、跨组织）、可重复性标准；并讨论「时钟测的是什么」这一概念问题——表观年龄是因果过程的读数还是统计相关的代理？"],
results:[
"被引 1026；成为时钟构建的标准参考——后续几乎所有组学时钟论文都引用它作为方法学依据。",
"综述同时确立了「时钟验证」的最低标准，过滤掉了大量不可复现的时钟声明。"],
limits:["时钟的因果解释仍是开放问题（被引 1026 也不解决这个）；组织特异性时钟与泛化时钟的张力持续存在。"],
debate:["这篇综述无意中记录了一个领域的成年礼：当方法学论文成为引用最高的文献，说明领域从「发现兴奋期」进入「规范建设期」。对 AIVC 的启示是直接的方法论——任何预测性生物标志物（包括虚拟细胞的输出）都需要同等的验证纪律。"],
takeaway:["衰老时钟分支的宪法；做任何组学时钟前先读。本站衰老交叉板块用它作为「预测 vs 因果」框架的源头文献。"],
further:["p62","p73","p75","p79"]},
{id:"p62",g:"g8",t:"An Inflammatory Aging Clock (iAge) Based on Deep Learning Tracks Multimorbidity, Immunosenescence, Frailty and Cardiovascular Aging",a:"Sayed, Huang 等",v:"Nature Aging",d:"2021",doi:"10.1038/s43587-021-00082-y",
summary:"被引 571：深度学习炎症衰老时钟，追踪多病共存与免疫衰老。",
background:[
"DNAm 时钟之外，蛋白组信号（尤其炎症相关蛋白）能否定义更贴近健康的衰老度量？斯坦福团队的判断：炎症是衰老的核心轴，值得一个专属时钟。",
"这个判断的深层动机是「健康寿命 vs 寿命」——DNAm 时钟预测死亡，而炎症时钟可能预测「带病生存的年数」。"],
method:[
"深度学习在血浆蛋白组上构建 iAge 时钟：从大量血浆蛋白中学习与衰老相关的组合模式；随后在独立队列中验证其与多病共存（multimorbidity）、免疫衰老、衰弱（frailty）、心血管衰老的关联。"],
results:[
"被引 571；iAge 预测健康寿命优于 DNAm 时钟的多个场景——蛋白模态的「健康相关性」优势首次被系统量化。",
"该工作直接推动了「多模态时钟比较」这一子领域的发展。"],
limits:["人群队列偏差（发现队列以欧洲裔为主）；因果性未证——炎症是衰老的驱动还是结果？；蛋白面板覆盖有限。"],
debate:["iAge 与 DNAm 时钟之争的实质是「测什么」：DNAm 是相对稳定的发育/衰老程序读数，蛋白是动态的系统状态读数。两者的分歧推动了衰老监测从「一次测量」走向「多时间点、多模态」——这对 AIVC 的启示是：虚拟细胞的输出也应该有多模态的衰老读数，而非单一指标。"],
takeaway:["「AI 预测生物学年龄」的里程碑；也是 AIVC 表示学习思想在衰老领域的先声。本站把它作为「多模态 > 单模态」在衰老场景的关键证据。"],
further:["p63","p80","p75","p61"]},
{id:"p63",g:"g8",t:"Proteomic Aging Clock Predicts Mortality and Risk of Common Age-related Diseases in Diverse Populations",a:"Argentieri, Xiao 等",v:"Nature Medicine",d:"2024",doi:"10.1038/s41591-024-03164-7",
summary:"被引 350：蛋白质组衰老时钟预测死亡与老年病风险，多模态时钟中预测力最强的一支。",
background:[
"哪种组学模态的时钟预测力最强、最可及？转录组噪声大且组织依赖，DNAm 稳定但因果含义模糊，蛋白组居中——动态、可及（血浆）、覆盖功能分子。这篇 Nature Medicine 论文要回答的正是模态选择问题。",
"队列规模是关键：结论要跨多人群成立，需要大队列支撑。"],
method:[
"大队列血浆蛋白质组（数千人规模、多种蛋白平台）+ 机器学习时钟构建；在多人群、多祖先背景中验证时钟对死亡与常见老年病（心血管、痴呆、癌症等）风险的预测力，并与其他模态时钟头对头比较。"],
results:[
"被引 350；蛋白时钟在死亡与老年病风险预测上优于既有模态——多模态时钟竞争中蛋白组胜出的系统证据。",
"同时量化了「增量价值」：在临床风险因素之上，蛋白时钟仍提供额外预测力——不是替代现有工具，而是增强。"],
limits:["蛋白面板覆盖与成本（质谱平台的普及度）；因果解释有限（时钟不告诉你干预什么）；发现队列的多样性仍有提升空间。"],
debate:["蛋白时钟的胜利对 AIVC 是明确信号：多模态表示 > 单模态。但更深的分歧在于「时钟的用途」——预测派（临床风险分层）与干预派（寻找可作用靶点）对同一时钟有完全不同的期待。虚拟细胞的衰老模块必须同时服务两种用途，这对架构设计是硬约束。"],
takeaway:["蛋白模态的胜利对 AIVC 是明确信号：多模态表示 > 单模态。本站企业解剖栏目里所有「衰老生物标志物」公司的技术路线，都以这篇为模态选择基准。"],
further:["p62","p80","p75","p79"]},
{id:"p64",g:"g8",t:"BiT Age: A Transcriptome-based Aging Clock Near the Theoretical Limit of Accuracy",a:"Meyer & Schumacher",v:"Aging Cell",d:"2021",doi:"10.1111/acel.13320",
summary:"被引 165：转录组衰老时钟逼近理论精度上限，证明转录组足以承载年龄信号。",
background:[
"转录组噪声大（技术变异 + 细胞组成混杂），能否构建高精度衰老时钟一直是问号。Meyer & Schumacher 的立论：如果转录组的精度上限本身就很高，之前的失败是方法问题而非模态问题。",
"「逼近理论上限」是这篇论文的卖点也是检验标准——他们真的算了理论上限，而不是修辞。"],
method:[
"大规模转录组数据 + 系统特征选择/集成方法；关键是「理论上限」的估计——用统计方法计算该模态可达到的最大预测精度，再对比实际时钟的表现，量化「还有多少空间」。"],
results:[
"被引 165；精度接近理论上限，且可解析细胞组成贡献——时钟信号里有多少来自「细胞类型比例变化」（免疫衰老）被定量分离。",
"结论对 scFM 做衰老任务是直接背书：转录组足以承载年龄信号，缺的是好的表示学习。"],
limits:["组织特异性强，跨组织迁移差——一个组织训的时钟不能直接用到另一个组织；理论上限的估计依赖噪声模型假设。"],
debate:["BiT Age 的「逼近上限」结论有一个刺耳的推论：转录组模态的预测空间已接近封顶，未来的增益必须来自新模态（蛋白、空间）或因果建模（不只是预测年龄，而是预测「什么干预改变年龄」）。这个推论预示了 2023-2026 年的模态迁移浪潮。"],
takeaway:["转录组模态可行性的关键证据——对 scFM 做衰老任务是直接背书。本站衰老交叉板块把它与蛋白时钟并列，作为「模态竞争」框架的两极。"],
further:["p63","p62","p59","p68"]},
{id:"p65",g:"g8",t:"Causality-enriched Epigenetic Age Uncouples Damage and Adaptation",a:"Ying, Liu 等",v:"Nature Aging",d:"2024",doi:"10.1038/s43587-023-00557-0",
summary:"把衰老时钟从关联推向因果：解耦「损伤」与「适应」两种成分。",
background:[
"表观年龄的变化混杂两种完全不同的过程：损伤（细胞受损，表观标记随之改变）与适应（细胞对损伤的补偿性反应）。混在一起时，干预的含义完全不清——「逆转适应」不等于「修复损伤」。",
"这篇 Nature Aging 论文用因果推断框架把两者解耦，是衰老时钟从「预测」走向「因果」的关键一步。"],
method:[
"因果推断框架：在表观时钟信号中分离损伤成分与适应成分——利用干预数据（部分时钟位点已知对应适应性响应）与因果图约束，估计两类成分各自的贡献与干预响应。"],
results:[
"两类成分的干预含义完全不同：降低「适应成分」可能让细胞重新暴露于损伤（净效应为负），而降低「损伤成分」才是真修复。这解释了此前部分「时钟逆转」研究的矛盾结果。",
"框架被应用于多个干预数据集，揭示了「表观年龄下降」这一表象下的成分结构。"],
limits:["框架依赖因果假设（哪些位点是适应性的，本身有不确定性）；验证成本高（需要干预数据）；成分解耦的粒度有限。"],
debate:["这篇论文是「AIVC 因果化议程」在衰老领域的先声——与 VCWM（虚拟细胞世界模型）的因果推理目标直接呼应。它的更大意义在于问题定义：整个衰老干预领域都在用「时钟变化」做终点指标，但如果时钟混合了损伤与适应，大量已发表的干预效果可能是假象。这迫使领域重新设计干预研究的读出体系。"],
takeaway:["与 AIVC 的因果化议程（VCWM）直接呼应——衰老是 AIVC 因果推理的最佳试验场。本站深度解读栏目把它作为「预测够不够、因果才止步」框架的标杆案例。"],
further:["p75","p61","p66","p70"]},
{id:"p66",g:"g8",t:"Metformin Decelerates Aging Clock in Male Monkeys",a:"Yang, Lu 等",v:"Cell",d:"2024",doi:"10.1016/j.cell.2024.08.021",
summary:"被引 219：二甲双胍减缓灵长类衰老时钟，干预有效性的关键体内证据。",
background:[
"二甲双胍的抗衰老效应在人类观察性研究中反复出现（服用者寿命与健康指标更好），但观察性研究无法排除混杂（健康的人更可能规律服药）。领域需要的严格动物证据。",
"这项研究选择非人灵长类——进化上最接近人类的模型，且用多组学衰老时钟做客观终点。"],
method:[
"雄性猴长期二甲双胍干预 + 多组学衰老时钟评估：以 DNAm 时钟、转录组等多模态指标量化干预对衰老速度的影响，覆盖多个组织；严格的对照组设计。"],
results:[
"被引 219：衰老时钟显著减缓，且多组织一致——二甲双胍抗衰老效应获得灵长类级别的严格证据，是该药物进入 TAME 临床试验（Targeting Aging with Metformin）的关键支撑。",
"多模态时钟的一致性也验证了「时钟作为干预终点」的可用性。"],
limits:[
"仅雄性——性别差异未解；剂量-效应与人群外推未定；灵长类样本量有限；时钟作为终点的因果含义（测的是衰老速度还是代谢效应）仍有歧义。"],
debate:["怀疑者提醒：时钟减缓 ≠ 寿命延长，二甲双胍的抗衰老叙事需要 TAME 临床试验的硬终点（发病与死亡）才能定论。但这篇论文的方法论价值已经兑现——它示范了「干预 + 多模态时钟」的严格评估范式，这正是 AIVC 干预模拟的湿实验对标：未来虚拟细胞预测的干预效果，要用这套协议检验。"],
takeaway:["「计算机预筛→湿实验验证」范式的经典案例；AIVC 干预模拟的终极对标。本站衰老交叉板块把它列为「干预证据分级」中的灵长类级证据。"],
further:["p65","p67","p70","p69"]},
{id:"p67",g:"g8",t:"Inhibition of IL-11 Signalling Extends Mammalian Healthspan and Lifespan",a:"Widjaja, Lim 等",v:"Nature",d:"2024",doi:"10.1038/s41586-024-07701-9",
summary:"抑制 IL-11 信号延长哺乳动物健康寿命，「靶点发现→验证」的标志性案例。",
background:[
"衰老相关分泌表型（SASP）——衰老细胞分泌的大量因子——中哪些是可成药靶点？SASP 因子数量庞大、功能混杂，逐一实验验证不可行。",
"这项研究的策略正是 AIVC 药物发现想要自动化的流程：系统筛选 → 锁定靶点 → 抗体干预 → 表型验证。"],
method:[
"大规模 SASP 因子筛选（在小鼠模型中测试多个因子的干预效果）锁定 IL-11；随后用 IL-11 抗体抑制在衰老小鼠中做长期干预实验，评估健康寿命与总寿命。"],
results:[
"延长健康寿命与总寿命；已进入临床转化（相关抗体药物管线）。这是「从分泌组筛选到靶点确认」的标志性案例，被抗衰老领域广泛引用为「靶点发现范式」的样板。"],
limits:["小鼠到人类的距离（IL-11 的人类相关性仍在验证）；长期安全性未知；「多靶点组合 vs 单靶点」的策略问题未解。"],
debate:["IL-11 案例对 AIVC 的启示是双面的：一方面它证明了「系统筛选 → 靶点 → 干预 → 表型」流程的产出效率——虚拟细胞要做的就是把这个流程搬进计算机；另一方面它也暴露了当前流程的成本结构（多年湿实验），这正是 AIVC 声称能压缩的部分。虚拟细胞公司能否复现这类发现，是检验其价值的黄金标准。"],
takeaway:["AIVC 药物发现叙事的黄金案例：系统筛选→靶点→干预→表型。虚拟细胞要做的事，就是把这个流程搬进计算机——本站用它作为所有 AIVC 制药公司技术路线的对标基线。"],
further:["p77","p69","p66","p34"]},
{id:"p68",g:"g8",t:"Single-cell Senescence Identification Reveals Senescence Heterogeneity, Trajectory, and Modulators",a:"Tao, Yu 等",v:"Cell Metabolism",d:"2024",doi:"10.1016/j.cmet.2024.03.009",
summary:"单细胞层面揭示衰老异质性与轨迹——衰老是可建模的状态转变而非二元标签。",
background:[
"衰老细胞异质性极大：同一组织里的衰老细胞状态各异，二元标签（衰老/非衰老）丢失了关键信息。更准确的描述是「衰老是一个连续的状态转变过程」。",
"这个认知转换对 AIVC 是任务定义级别的：如果衰老是轨迹，那么建模工具应该是轨迹/动力学模型（世界模型架构），而不是分类器。"],
method:[
"单细胞数据 + 状态轨迹与调控因子推断：在单细胞分辨率上刻画衰老状态的连续谱，推断转变轨迹与关键调控节点（哪些 TF/通路驱动状态转变）。"],
results:[
"衰老是连续轨迹而非开关——不同组织、不同应激下的衰老轨迹既有共性（SASP 核心程序）又有特异性；给出可干预的调控节点。",
"「轨迹」框架被后续衰老 AIVC 工作广泛采用为任务定义。"],
limits:["体外体系为主，体内验证有限；轨迹推断依赖快照数据（单细胞测序是破坏性的），时间轴是重建的而非直接观测的。"],
debate:["轨迹视角与 SenNet 共识的「状态检测」视角存在方法论张力：前者把衰老当连续过程，后者需要可操作的二元标准。两者的调和正在发生——共识标准用于标注锚点，轨迹模型用于插值。对 AIVC，这个调和意味着：训练数据需要「共识标注的锚点 + 连续状态的轨迹数据」双层结构。"],
takeaway:["为衰老 AIVC 提供「状态转变」的任务定义——这正是世界模型架构的用武之地。本站把这篇与 AIDO.Cell 并列：一个定义问题，一个提供架构。"],
further:["p78","p58","p59","p21"]},
{id:"p69",g:"g8",t:"Cellular Senescence: A Key Therapeutic Target in Aging and Diseases",a:"Zhang, Pitcher 等",v:"Journal of Clinical Investigation",d:"2022",doi:"10.1172/jci158450",
summary:"被引 628：衰老细胞作为治疗靶点的权威综述，senolytics 路线立论基础。",
background:[
"衰老细胞的积累与多种年龄相关疾病（纤维化、动脉粥样硬化、神经退行）相关，但「作为靶点」的证据需要系统评估：清除衰老细胞真的治病吗？风险是什么？",
"这篇 JCI 综述是 senolytics（衰老细胞清除药物）路线的立论基础，也是临床医生进入这个领域的入口。"],
method:[
"跨疾病证据综述 + 治疗策略评估：系统整理各疾病中衰老细胞的因果证据（遗传学清除模型、药理学清除实验），评估「清除 vs 调节」两类策略的证据强度与风险。"],
results:[
"被引 628；确立 senolytics 的临床转化框架——哪些疾病证据最强、哪些清除策略（BCL-2 抑制剂、免疫清除）更有前景、长期风险（伤口修复受损、旁效应）如何管理。",
"综述直接影响了第一波 senolytics 临床试验的设计。"],
limits:["临床证据仍早期（多为概念验证试验）；清除策略的长期风险未明；「衰老细胞也有有益功能」的悖论（胚胎发育、伤口修复、肿瘤抑制）没有完全解。"],
debate:["领域内的核心争论是「清除的精准度」：全身清除 senolytics 可能误伤有益衰老细胞（如伤口处的），组织特异性清除（抗体靶向、前药策略）是解法但工程复杂。AIVC 在这里的角色清晰了：预测哪些衰老细胞亚群可安全清除、预测清除的系统性后果——这正是虚拟细胞干预模拟的直接应用场景。"],
takeaway:["senolytics 路线的圣经；AIVC 干预模拟（计算机筛 senolytics）的直接依据。本站衰老交叉板块把它作为「临床证据金字塔」的基座文献。"],
further:["p76","p77","p58","p67"]},
{id:"p70",g:"g8",t:"From Geroscience to Precision Geromedicine: Understanding and Managing Aging",a:"Kroemer, Maier 等",v:"Cell",d:"2025",doi:"10.1016/j.cell.2025.03.011",
summary:"被引 372：从老年科学到精准老年医学的框架文章，AIVC 临床转化的坐标系。",
background:[
"老年科学（geroscience）搞清了衰老的机制（hallmarks of aging），但「怎么转化为精准的临床干预」缺少框架：衰老干预不是单一药物的故事，而是分层、标志物指导、组合干预的工程。",
"Kroemer/Maier 等的这篇 Cell 文章就是这个转化框架的蓝图。"],
method:[
"提出「精准老年医学」框架：患者分层（按衰老机制/生物标志物分型）、生物标志物指导的治疗选择、组合干预策略（多靶点协同）；并讨论监管路径（以衰老为适应症的试验设计）。"],
results:[
"被引 372；成为该方向的框架性文献，被监管机构与产业界引用为路线图。",
"框架同时定义了「老年医学的数字孪生」需求——分层与治疗选择都需要个体化的衰老模型，这正是虚拟细胞的临床入口。"],
limits:["框架性工作，实证依赖具体管线；分层标准仍在演化；监管路径因地而异。"],
debate:["这篇文章的争议在「衰老是不是可干预的医学适应症」这个根本问题上：FDA 等监管机构尚未正式承认「衰老」为适应症，精准老年医学的部分主张（如基于时钟的治疗决策）在临床合法性上仍是灰色地带。虚拟细胞公司做衰老管线，必须先解这个监管问题——技术再强，适应症不成立就没有市场。"],
takeaway:["衰老 AIVC 的临床出口地图——所有技术最终要落到这个框架里。本站把它放在衰老板块的收尾位置：从机制（hallmarks）到框架（这篇）到监管（待解），三步走完才是产品。"],
further:["p74","p80","p61","p66"]},
{id:"p71",g:"g3",t:"GEARS: Predicting Transcriptional Outcomes of Novel Multigene Perturbations",a:"Roohani；通讯：Leskovec / Altman（Stanford）",v:"Nature Biotechnology",d:"2023-12",doi:"10.1038/s41587-023-01905-6",
summary:"在基因知识图谱上做 GNN 推理，可预测从未单独扰动过的基因及其组合的转录组结局。",
background:[
"组合扰动空间巨大（n 个基因的双基因组合就有 n²/2），实验不可穷尽；且真正有用的预测是「没见过的组合」——GEARS 的名字就是基因效应关系推理。",
"斯坦福 Leskovec/Altman 组的核心思路：把组合扰动预测转化为图上的推理问题——基因知识图谱（STRING 等）提供「谁和谁有关」的先验。"],
method:[
"基因知识图谱 + 图神经网络：把每个组合扰动表示为图上的子集（被扰动的基因集合），GNN 在图上传播信息，推断该子集的联合效应；训练目标是转录组响应。",
"「知识图谱 + 推理」的设计承诺是泛化：即使某对组合从未被实验，只要两个基因各自的效应与它们的关系已知，就能推理联合效应。"],
results:[
"能预测未见单基因与双基因组合的转录组响应；成为组合扰动预测的标准基线。有趣的是，它同时是「基准增益幻觉」的经典案例——Ahlmann-Eltze 2025 指出其增益可被简单可加基线复现。"],
limits:["Ahlmann-Eltze 2025 指出其增益可被简单可加基线复现；知识图谱覆盖偏差会传导进预测（STRING 对研究充分的基因覆盖好）；图结构对非加性效应（协同/拮抗）表达力有限。"],
debate:["GEARS 的命运是整个领域的缩影：发表时是突破（Nature Biotechnology），两年后是「被公平基线追平」的警示。这暴露了领域论文周期与评测周期的时间差——论文发表时的 SOTA，可能只是评估设计的产物。Rouhani 后来参与创立 VCC，某种程度上是对这个教训的回应：让第三方、盲测、统一口径来定义进步。"],
takeaway:["组合扰动预测的代表作；也是「基准增益幻觉」的经典案例——同一篇论文既是里程碑也是警示。本站立场：GEARS 的方法论价值（图推理）与它的评测教训（增益幻觉）同等重要，都要呈现。"],
further:["p31","p30","p36","p32"]},
{id:"p72",g:"g4",t:"A Systematic Comparison of Single-cell Perturbation Response Prediction Models",a:"Lanxiang Li 等；通讯：Yue You / Xiaodong Liu / Luyi Tian（中国团队）",v:"Science Advances",d:"2026-09",doi:"10.1126/sciadv.aed3414",
summary:"13 种方法 + 基线、25 个数据集、24 项指标、3 项任务的同行评审系统比较：无单一模型全面占优，泛化与「保守坍缩」是共性难题。",
background:[
"扰动预测模型雨后春笋，但「哪个模型真的更好」缺少统一口径的系统比较——每篇论文自带考场。中国团队的这项工作把 13 种代表性方法与基线拉进同一考场（25 个数据集、24 项指标）。",
"它的价值不在结论而在失败模式分析：输在哪里比赢在哪里更能推动领域。"],
method:[
"13 种代表性方法与基线在统一数据与指标下系统比较，三项任务覆盖未见单基因扰动、组合相互作用与跨细胞类型迁移；重点剖析失败模式而非仅仅排名。",
"本刊 2026-10-25 更正：此前标注的「2025 年、10 种模型」有误，据 Science Advances 期刊页面应为 2026-09-09、第 12 卷第 37 期 eaed3414、13 种方法加基线、25 个数据集（23 公开 + 2 自建）、24 项指标。"],
results:[
"无单一模型全面占优——每个模型有自己的适用域；发现共性失败模式：跨条件泛化差、「预测均值」式的保守坍缩（模型倾向于输出接近平均的响应以避免犯错，导致对强扰动效应的预测不足）。",
"「保守坍缩」一词从此进入领域词汇表，成为描述模型失败的标准术语。"],
limits:["模型覆盖随领域演进需更新；比较基于公共数据（癌细胞系为主），体内场景未覆盖；失败模式的归因（是数据问题还是架构问题）仍有歧义。"],
debate:["这篇论文与 Ahlmann-Eltze、Kedzierska 共同构成 2025-2026 年的「评测三剑客」，但分工不同：Ahlmann-Eltze 打「深度 vs 线性」，Kedzierska 打「零样本幻觉」，这篇打「全面占优幻觉」。三者合力把领域从「发布会模式」拉回「科学模式」。中国团队在这轮评测建设中的角色值得注意——评测基础设施不再是北美机构的专属领地。"],
takeaway:["中国团队在基准评测上的重要贡献；「保守坍缩」一词从此进入领域词汇表。本站「批评与基准」板块把它与三篇海外评测并列，作为选型与尽调的必读清单。"],
further:["p36","p37","p35","p45"]},
{id:"p73",g:"g8",t:"DNA Methylation Age of Human Tissues and Cell Types",a:"Horvath（UCLA）",v:"Genome Biology",d:"2013",doi:"10.1186/gb-2013-14-10-r115",
summary:"353 个 CpG 位点构建跨组织通用的表观遗传时钟，首次让「生物学年龄」成为可操作的通用指标。",
background:[
"2013 年之前，「衰老能不能被测出来」是个模糊问题：端粒长度、生化指标各自为战，没有一个度量能跨组织通用。同年的 Hannum 时钟局限于血液，Horvath 这篇则立下更大的目标——一个在任何组织都成立的时钟。",
"这个野心有数据底气：8000+ 甲基化谱样本、覆盖 51 种组织与细胞类型，是当时规模最大的整合分析。"],
method:[
"弹性网络回归 + 跨组织 CpG 筛选：从 21,369 个 CpG 中筛出 353 个与年龄高度相关的位点，训练多组织通用模型；模型不依赖组织标签，同一套系数适用于所有组织。",
"「去组织化」是关键设计决策：时钟必须在没见过的组织上也成立，倒逼模型抓住衰老的共性信号而非组织特异性变异。"],
results:[
"353 位点时钟跨 51 种组织成立（中位绝对误差约 3.6 年）——「生物学年龄」第一次成为可操作的通用指标。癌症组织中时钟普遍加速（平均约 36 年），与肿瘤的表观遗传紊乱一致。",
"影响无法高估：此后十年几乎所有衰老干预研究都以它做终点指标，并直接催生了 GrimAge、PhenoAge、DunedinPACE 一整个时钟家族。"],
limits:[
"只测相关、不测因果——时钟加速可能是衰老的结果而非原因；对发育阶段敏感（0-20 岁走速与成年后不同）；组织覆盖偏向易采样组织（血液、皮肤、肌肉），内脏覆盖少。"],
debate:[
"Horvath 与 Hannum 的「通用 vs 特异」之争是领域起源的佳话，两条路线各有后世。更深的追问是「时钟测的是什么」——衰老本身、细胞组成变化，还是累积损伤的统计影子？这个问题至今没有共识答案，也是所有「逆转衰老」新闻的软肋。",
"另一个争议是可解释性：353 个位点里没有任何单个 CpG 能解释时钟行为——时钟是生物实体还是统计构造，追问至今有效。"],
takeaway:["衰老时钟领域的开山之作，被引 3000+。读衰老 AIVC 必须从这里开始——它是所有「生物学年龄」指标的祖先。提醒：连同 Bell & Lowe 的方法学综述（p61）一起读，才能分辨哪些时钟声明是靠谱的。"],
further:["p61","p75","p79","p74"]},
{id:"p74",g:"g8",t:"Hallmarks of Aging: An Expanding Universe",a:"López-Otín, Blasco, Partridge, Serrano, Kroemer",v:"Cell",d:"2023",doi:"10.1016/j.cell.2022.11.001",
summary:"衰老标志物权威框架的 2023 修订版：从 9 项扩展到 12 项，新增慢性炎症、菌群失调、心理社会隔离。",
background:[
"2013 年「Hallmarks of Aging」是衰老生物学被引最高的框架论文，但十年间领域剧变：衰老细胞学说成熟、SASP 机制明晰、干预证据积累。原作者团队在 2023 年做了系统性修订。",
"修订本身是个信号：框架从「描述衰老是什么」转向「指导干预设计」。"],
method:[
"框架论文，无实验数据。将衰老标志物扩为 12 项：基因组不稳定、端粒磨损、表观遗传改变、蛋白质稳态丧失、巨自噬失能、营养感应失调、线粒体功能障碍、细胞衰老、干细胞耗竭、细胞间通讯改变（含慢性炎症）、菌群失调、心理社会隔离——新增四项全部指向系统性与环境维度。"],
results:[
"被引数千次，成为 2023 年后衰老研究与干预设计的标准参照；「慢性炎症」与「菌群失调」升格为正式标志物，直接改变了 senolytics 与免疫调节策略的叙事权重。",
"框架同时明确「标志物之间互相因果纠缠」——单一标志物干预的系统效应不可线性外推，这是对简化还原论的系统性纠偏。"],
limits:[
"框架性工作，无新数据；「心理社会隔离」入列虽有勇气，但与分子机制的衔接薄弱；12 项标志物的操作化定义（怎么测）仍留给子领域自行解决。"],
debate:["框架扩张引发两种反应：欢迎者认为炎症与菌群终于进入主流；批评者担心「标志物通胀」——当什么都算标志物时，框架的解释力反而下降。更深的分歧在学科边界：把心理社会因素写进分子衰老框架，是范式创新还是范畴混淆？"],
takeaway:["衰老研究的坐标系 2.0。做衰老 AIVC 的任务清单可以直接从这 12 项展开——每一项都对应一类可建模的细胞状态转变。本站把它与 p70（精准老年医学）配对成「生物学框架 → 临床框架」。"],
further:["p70","p73","p76","p69"]},
{id:"p75",g:"g8",t:"DunedinPACE, a DNA Methylation Biomarker of the Pace of Aging",a:"Belsky, Caspi, Corcoran … Moffitt（Duke / Columbia / KCL）",v:"eLife",d:"2022",doi:"10.7554/eLife.73420",
summary:"从 20 年纵向队列蒸馏出的单时点甲基化「衰老速度」指标——从「你几岁」到「你老得多快」。",
background:[
"第一代时钟回答「你现在生物学几岁」，但干预研究需要的是另一个量：「你衰老得多快」。静态年龄相同的两个人，衰老速率可以差一倍——而速率才是可干预、可归因的对象。",
"Dunedin 队列的特殊资产是 20 年纵向追踪：同一个体的 19 项生理指标跨 20 年重复测量，这是计算「衰老速度」的金标准数据。"],
method:[
"两步法：先用 Dunedin 队列 20 年数据建模每个个体的「衰老速度」（19 项器官系统完整性指标的衰退斜率）；再用弹性网络把这个纵向速度蒸馏成单时点血液甲基化检验——一次抽血读出衰老速度。",
"与第一代时钟的关键区别：训练目标是「速率」而非「年龄」，且刻意剔除测试-重测可靠性低的探针。"],
results:[
"与 20 年实测衰老速度相关 r=0.78；测试-重测可靠性高；与死亡、失能、功能衰退相关；在 GrimAge 之外提供增量预测。干预试验从此有了真正的「速率终点」——比「年龄变化」灵敏得多。",
"被 CALERIE 等干预研究采用为标准读出。"],
limits:[
"基于单一出生队列（Dunedin），人群外推需验证；血液甲基化受免疫细胞组成影响；「速率」的因果解释（快=损伤累积还是慢=修复好）仍未定。"],
debate:["DunedinPACE 与 GrimAge 的关系被反复讨论：后者是「年龄+风险」复合指标，前者是纯速率——两者信息量不同但常被混用。更深的争议在「速率是否可干预」：如果速率主要由早年暴露决定（童年逆境显著加速），成年干预的天花板在哪？这是所有抗衰老干预声明的共同软肋。"],
takeaway:["第二代时钟代表：从「你几岁」到「你老得多快」——后者才是干预研究的正确终点。本站把它列为衰老干预评测的方法学标杆：任何宣称「延缓衰老」的产品，应该拿速率指标而不是年龄指标说话。"],
further:["p61","p73","p65","p63"]},
{id:"p76",g:"g8",t:"Naturally occurring p16Ink4a-positive Cells Shorten Healthy Lifespan",a:"Baker, Childs, Durik … van Deursen（Mayo Clinic）",v:"Nature",d:"2016",doi:"10.1038/nature16932",
summary:"INK-ATTAC 小鼠证明清除 p16+ 衰老细胞可延长健康寿命——衰老细胞积累导致衰老表型的因果证据。",
background:[
"衰老细胞与衰老的相关性早已确立，但「因果性」缺关键一环：如果人为清除衰老细胞，衰老会变慢吗？2011 年 INK-ATTAC 转基因小鼠（p16 启动子驱动的可诱导凋亡系统）提供了工具，但从没人在自然衰老场景下做过长期清除实验。",
"这个实验的哲学是「最小干预」：不改基因、不换环境，只清除一个特定细胞群体，看会发生什么。"],
method:[
"INK-ATTAC 小鼠：p16(Ink4a) 启动子驱动 FKBP-Caspase8 融合蛋白，注射 AP20187 选择性诱导 p16+ 细胞凋亡；从 1 岁起每周两次给药持续终身，两个遗传背景、两种性别、严格对照。"],
results:[
"清除 p16+ 细胞延长了两个遗传背景下的中位寿命；延迟肿瘤发生；减轻肾、心、脂肪组织的年龄相关退化，且未见明显副作用。",
"这是「衰老细胞积累导致衰老表型」的因果证据，直接催生了 senolytics 整个产业方向，也是「靶点 → 干预 → 表型」湿实验范式的黄金标准。"],
limits:[
"小鼠证据；INK-ATTAC 的 p16 启动子覆盖不完全；清除的长期后果（伤口修复、肿瘤抑制功能受损）只观察了有限窗口。"],
debate:["「清除衰老细胞是否安全」是后续争论焦点：后续研究显示衰老细胞在伤口修复与胚胎发育中有益功能，全身清除可能误伤。Baker 的「无副作用」结论被部分后续研究修正——这推动了组织特异性清除策略（而非全身 senolytics）成为主流方向。"],
takeaway:["衰老细胞因果证据的奠基实验。对 AIVC 的意义：虚拟细胞要预测的正是这类干预的系统后果——包括误伤。本站把它列为衰老干预证据分级中的「遗传学清除级」。"],
further:["p69","p77","p58","p70"]},
{id:"p77",g:"g8",t:"Discovery of Potent Senolytics through the Senolytic Drug Discovery Pipeline",a:"Smer-Barreto, Quintanilla, Elliott … de Keizer / Campisi 等",v:"Nature Communications",d:"2023",doi:"10.1038/s41467-023-39120-1",
summary:"机器学习从公开筛选数据训练 senolytics 预测器，发现并验证银杏素、periplocin、夹竹桃苷三个新 senolytics——AI 药物发现在衰老领域的样板。",
background:[
"已知 senolytics 不到十几种（D+Q、navitoclax、fisetin），且靶点不清、细胞类型特异；传统高通量筛选成本高、化学空间覆盖窄。作者的判断：公开文献里的筛选数据是座金矿，机器学习能把它变成预测器。",
"这是「AI × 衰老」最纯粹的对接点——问题定义、数据形态、验证闭环都适合计算优先策略。"],
method:[
"从公开文献整理已知 senolytics 与非 senolytics 的化合物-反应数据（异质、小规模、多 assay 设计）；训练分子指纹特征 + 随机森林/SVM 分类器；对商业化合物库虚拟筛选排序；头部候选做体外验证。",
"关键设计是「数据不求大、验证必须实」——训练集故意小而杂，但每个命中必须过多种衰老模型（复制性、癌基因诱导、治疗诱导）的细胞实验。"],
results:[
"发现银杏素（ginkgetin）、periplocin、夹竹桃苷（oleandrin）三个新 senolytics，在多种人源细胞模型中验证选择性清除衰老细胞；筛选成本较传统 panel 降低数百倍。",
"方法学意义大于分子意义：小规模、异质的公开数据经 ML 重组后足以产出可验证的候选——这正是 AIVC 药物发现的标准叙事。"],
limits:[
"体外验证为主，体内有效性与安全性未证；训练数据的发表偏倚（阳性结果更易发表）会扭曲模型；三个化合物的靶点与选择性机制仍不清楚。"],
debate:["怀疑者认为这仍是「老药新用」式筛选，ML 只加速优先级排序而非产生新靶点知识；支持者强调在 senolytics 极度稀缺的阶段，产出三个经过验证的化合物本身就是实打实的贡献。它与 C2S-Scale 的 CK2 案例并列，构成「AI 假说 → 湿实验验证」在衰老领域的两大证据。"],
takeaway:["AI 药物发现的标准叙事模板：小数据 + 好验证 = 可发表、可转化的候选。本站企业解剖栏目里所有「AI + senolytics」初创的技术范式都源于这篇；与 p67（IL-11）对照读，能看清「计算预筛」与「系统筛选」两条路线的成本结构差异。"],
further:["p67","p69","p16","p34"]},
{id:"p78",g:"g8",t:"Single-cell Transcriptomic Profiling of the Aging Mouse Brain",a:"Ximerakis, Lipnick, Innes … Regev, Bader, Levin, Rubin（Harvard / Broad）",v:"Nature Neuroscience",d:"2019",doi:"10.1038/s41593-019-0491-3",
summary:"衰老小鼠脑近全细胞类型单细胞图谱：衰老不是统一程序，而是每个细胞类型各走各的路。",
background:[
"脑衰老的分子研究长期用 bulk 组织——把不同细胞类型的变化平均成一个信号，丢失了细胞类型特异性。哈佛 Rubin 实验室用单细胞测序回答：衰老在脑内到底怎么发生？",
"这项工作的方法论影响甚至大于生物学发现：它示范了「衰老图谱」这种数据形态如何成为领域基础设施。"],
method:[
"年轻与老年小鼠全脑单细胞 RNA 测序，覆盖近全部脑细胞类型（神经元各亚型、胶质、血管、免疫细胞）；对每个细胞类型分别做衰老差异分析，并构建配体-受体互作网络预测细胞间通讯的衰老变化。"],
results:[
"核心发现是「非统一性」：部分基因在所有细胞类型同向变化（真正共性的衰老程序），大量基因只在特定细胞类型变化，还有些基因在不同细胞类型中方向相反——衰老不是一把尺子量所有细胞。核糖体生物发生被凸显为共性过程。",
"数据与互作网络完全开放，成为神经衰老研究的标准参照数据集。"],
limits:[
"小鼠模型；快照数据（无纵向轨迹）；脑区覆盖虽全但时间维度缺失——衰老是过程，快照只能给终点差异。"],
debate:["「衰老的非统一性」对 AIVC 是任务定义级别的发现：如果衰老因细胞类型而异，任何全局性的「衰老标志物」都会稀释——必须在细胞类型分辨率上建模。这与单细胞衰老异质性研究（p68）互为印证，共同构成衰老 AIVC 的立论基础：衰老建模必须是 cell-type-aware 的。"],
takeaway:["「衰老非统一性」的奠基图谱；与 SenNet 共识（p58）共同构成衰老 AIVC 的数据与标注双基。做神经退行 AIVC 的团队，这是入门数据集；本站把它列为衰老图谱系列（小鼠脑 → 人 SenNet）的第一环。"],
further:["p58","p68","p57","p60"]},
{id:"p79",g:"g8",t:"Universal DNA Methylation Age Across Mammalian Tissues",a:"Lu, Fei, Haghani, … Horvath 等",v:"Nature Aging",d:"2023",doi:"10.1038/s43587-023-00462-6",
summary:"覆盖 127 种哺乳动物的通用 DNAm 衰老时钟——把跨物种思想引入衰老度量。",
background:[
"Horvath 时钟跨组织但不跨物种：小鼠时钟在人身上不工作。而比较衰老研究（为什么裸鼹鼠不得癌、弓头鲸活 200 年）迫切需要一把跨物种的尺子。",
"Lu 等（Horvath 组）的雄心：训练一个在所有哺乳动物都成立的甲基化时钟。"],
method:[
"整合 127 种哺乳动物（128 个物种、59 个组织）的甲基化数据训练通用时钟；关键在于处理物种间甲基化组的巨大差异——用跨物种保守的 CpG 与统一表示，而非物种特定位点。"],
results:[
"通用时钟跨物种、跨组织成立；在多种哺乳动物中预测寿命与衰老速度。这把尺子立刻改变了比较衰老研究的实验设计——短寿命物种的数据可用来校准长寿命物种的衰老轨迹。",
"对 AIVC 的直接意义：衰老度量第一次像 scFM 一样可以「零样本迁移」。"],
limits:[
"预测精度低于物种特异时钟（通用性的代价）；对极端长寿物种的外推仍是问题；甲基化数据的物种覆盖偏向模式生物。"],
debate:["「通用 vs 特异」在衰老度量上的翻版——与 SATURN/UCE 在单细胞嵌入上的争论同构。支持者认为跨物种统一是规模效应的又一次胜利；怀疑者指出通用时钟的精度损失在干预研究中可能是致命的（效应量小于物种间差异时测不出来）。这与本站对 X-Cell scaling 叙事的保留态度形成有趣的平行。"],
takeaway:["跨物种衰老度量——与跨物种 scFM（SATURN/UCE）构成同构的技术路线。做比较衰老研究的团队必读；它也预告了「衰老 AIVC」的终局形态：一个跨物种的统一衰老模型。"],
further:["p73","p61","p11","p02"]},
{id:"p80",g:"g8",t:"Organ Aging Signatures in the Plasma Proteome Track Health and Disease",a:"Oh, Rutledge, Nachun … Wyss-Coray, Lehallier（Stanford）",v:"Nature",d:"2023",doi:"10.1038/s41586-023-06802-1",
summary:"血浆蛋白质组解析器官特异性衰老：每个器官按自己的节奏衰老，器官年龄加速预测相应器官的疾病。",
background:[
"bulk 衰老指标把人体当一个整体，但现实是「心脏 60 岁、肾 70 岁」式的器官差异衰老。斯坦福团队的判断：衰老必须在器官分辨率上度量。",
"数据来源很特别：英国生物样本库近 5000 人的血浆蛋白质组（约 3000 蛋白），是当时最大的衰老蛋白质组资源之一。"],
method:[
"器官特异性蛋白面板（已知主要在单一器官表达的蛋白）构建各器官的「年龄」估计；与全因死亡、器官特异性疾病做关联分析。"],
results:[
"约 20% 的血浆蛋白可追溯到单一器官来源；不同器官以不同节奏衰老；「器官年龄」加速预测相应器官疾病（如心脏年龄加速预测心衰风险），且强于整体衰老指标。",
"对精准老年医学是直接的路线图：先测器官年龄分布，再决定干预哪个器官。"],
limits:[
"器官归属基于蛋白的组织表达注释（有噪声）；横断面为主；血浆反映分泌谱而非器官本身状态。"],
debate:["「器官衰老」框架的争议在测量学：血浆蛋白是器官功能的间接读出，器官「年龄」是统计推断而非直接测量。但它与 DunedinPACE 的组合（器官构成 + 整体速率）正在成为老年评估的标准配置——这预示 AIVC 的衰老模块必须是多器官、多尺度的联合模型，而非单一指标。"],
takeaway:["器官分辨率衰老度量的代表作——衰老不是一个数，而是一个器官年龄向量。本站把这篇与 p70（精准老年医学）对接：器官年龄画像正是精准分型的输入。做衰老产品的团队，这是产品指标设计的直接参照。"],
further:["p63","p70","p75","p61"]},
{id:"p81",g:"g2",t:"Predicting cell-state-specific gene regulation from DNA across species（Bolero）",a:"Liu, H.; Mao, S.; … Buenrostro, J. D.; Zhou, J.; Greenberg, M. E.（Arc Institute / Harvard Medical School）",v:"bioRxiv",d:"2026-10-20",doi:"10.64898/2026.10.19.760026",
summary:"Bolero 让 Transformer 的每一层权重都由细胞状态生成，第一次把「序列到功能」与「单细胞基础模型」两条路线真正合流：只给 DNA 序列，就能问它在任意细胞状态——包括训练中没见过的状态——里的调控表现。",
background:[
"「同一段 DNA，在不同细胞里读出不同结果」是调控基因组学的核心难题，也长期被两股技术路线割裂：一边是序列到功能模型（Enformer、Borzoi 一类），读 DNA 读得很细，却把细胞状态当作一个固定的分类标签；另一边是单细胞基础模型，能把细胞状态表达得很丰富，却完全不看序列。",
"结果是两张半图：你能预测这段序列在某个已测细胞类型里是否开放，却无法回答它在另一个未被测量的细胞状态里会怎样；反过来，你知道细胞状态，却无法反推某个非编码变异在其中起什么作用。Arc Institute 的周镜天团队与哈佛医学院 Greenberg 实验室、Buenrostro 实验室合作，试图把这两半拼起来。"],
method:[
"Bolero 的名字取自拉威尔的《波莱罗舞曲》——同一个主题在不同乐器间传递，每次奏响都不同。它的核心设计是「条件化权重」而非「条件化拼接」：接收两个输入，原始 DNA 序列，以及一个由图谱级细胞状态嵌入（cell-state embedding）构成的向量。",
"关键区别在于注入方式。多数做法是把细胞身份作为标签拼在模型末端，Bolero 则让细胞状态嵌入生成一组自定义权重，逐层加到 Transformer 主干的每一层里——每一个细胞状态实际上拥有自己的一份网络参数。这正是它能对训练中从未出现过的细胞状态做外推的原因。",
"训练数据为 Bolero-10M：来自 6 种哺乳动物、33 个数据集的 1070 万个细胞，覆盖人脑与身体组织、发育与衰老过程。此外还引入 AP-1 活性分数作为一条连续的条件化轴，使模型可以在没有真实刺激数据的情况下模拟转录因子活性变化。"],
results:[
"在染色质可及性与转录丰度的预测上，Bolero 达到或超过了针对特定任务训练的专用模型，并能分辨高度相近细胞状态之间的调控差异，包括皮层区域梯度与发育梯度。",
"在 Greenberg 实验室的用例中，把 AP-1 活性当作可连续调节的旋钮，Bolero 准确预测了同一种刺激下两类海马神经元各自不同的染色质响应。进一步让模型解释自己的预测，发现不同转录因子与 AP-1 的协作方式依细胞类别而异，且协同因子与 AP-1 基序的物理间距是关键——计算插入实验显示，把协同因子放在距 AP-1 恰好 4 个碱基对的位置会稳定增强调控响应。这等于从「读 DNA」推进到了「重建物理语法」。",
"跨物种方面，Bolero 预测了训练中被排除物种的细胞类型特异性可及性与 AP-1 响应。在 84 种哺乳动物上，预测得到的 AP-1 响应比顺式调控元件上的染色质可及性更不保守，差异主要由人类特异的 AP-1 及其协同基序序列变异驱动。"],
limits:[
"这是未经同行评议的预印本，全部结论目前为作者自述，尚无独立复现。条件化权重机制显著增加了参数生成开销与训练复杂度，其规模上限未被探索。",
"训练仍以人类数据为主，跨物种外推虽被验证，但对非哺乳类、远端物种的泛化能力未知。AP-1 之外的连续条件化轴是否有效，论文只给了单一案例。"],
debate:[
"最大的争点是「外推」的可信度：把细胞状态嵌入外推到训练中未见的状态，本质上是在做一个连续插值假设。当目标状态落在训练流形之外时，这种假设可能静默失效——模型会给出一个自信但无依据的预测，而用户无从察觉。",
"另一个值得警惕的点是叙事强度。从「预测可及性」到「发现 4 bp 间距语法规则」是一次很大的跳跃，后者依赖模型自身的解释（in silico 插入实验），尚需湿实验验证。与本站记录的批评性文献一致，模型导出的「机制」在被实验证实前仍应视为假设。"],
takeaway:[
"Bolero 是「序列模型 × 单细胞基础模型」第一次像样的合流，方向与 Bunne 纲领文的「统一表征」支柱一致。对做非编码变异解读、调控语法、跨物种功能注释的团队，这是目前最值得跟踪的架构。",
"情报视角：Arc Institute 在 STATE 之后再次出手，且这次拉上了哈佛的 Greenberg 与 Buenrostro 实验室——「图谱 + 序列」的组合拳正在成为 Arc 的技术标识。建议连同 p82（同期发布的基准批评）一起读，两者对模型能力给出了方向相反的证据。"],
further:["p82","p09","p21","p01"]},
{id:"p82",g:"g4",t:"Averaging in gene perturbation benchmarks hides perturbation-strength variation: Consequences for model evaluation",a:"Sharma, Y. S.; Subramaniyam, M.; Passariello, P.; Jay, D.; Render, D.; Szegedy, M.",v:"bioRxiv",d:"2026-10-23",doi:"10.64898/2026.10.20.760537",
summary:"基准默认把同一扰动标签下的细胞取平均，这篇问了一个此前没人问的问题：这种平均化丢掉了什么？答案直白而难堪——STATE 与 Cell2Sentence 的预测连扰动身份都恢复不了。",
background:[
"扰动预测基准的默认做法是：把带有同一个扰动标签的所有细胞取平均，用这个平均表达谱代表该扰动。这个做法几乎从不被人质疑，因为它是 CMap 时代遗留下来的标准操作。",
"但它隐含一个强假设：同一扰动下的所有细胞响应强度一致。实际上 CRISPRi 的敲低效率、慢病毒拷贝数、guide 丰度都会让同一名义扰动下的细胞产生强弱不同的响应。Rutgers 团队追问的是：这种平均化到底丢掉了什么，以及当前模型的预测里是否还保留着足够的信息，让我们能评估它。"],
method:[
"研究者用 X-Atlas/Orion 的 CRISPRi 筛选数据，把经过深度校正的 guide 丰度作为细胞层面的扰动强度代理变量，检查在单一名义扰动内部转录响应如何随强度变化。",
"随后做检索测试：给定真实的或模型预测的表达谱，能否把它正确匹配回它所属的扰动身份。这是对「扰动特异性信息是否保留」的直接检验。被评估的两个模型是 Arc Institute 的 STATE 与 Cell2Sentence。"],
results:[
"扰动强度越高，转录响应的可重复性越高。这一效应在 HCT116 与 HEK293T 两种人源细胞系中都存在，但在 HCT116 中更为明显。",
"在模型评估环节，结果是一次直接的否定：在 HCT116 的检索测试中，观测到的真实响应保留了扰动身份信息，而被评估的 STATE 与 Cell2Sentence 的预测都不能可靠地恢复它。作者因此指出，由于模型预测连扰动身份都保不住，「扰动内部强度信息」这个问题根本无法被有意义地评估。"],
limits:[
"guide 丰度只是扰动强度的代理变量，深度校正后的读数与真实敲低效率之间的关系未经独立验证。研究只在两种细胞系、一个数据平台（X-Atlas/Orion）上完成。",
"「预测无法恢复扰动身份」是一个强结论，但它高度依赖检索测试的设定（候选集大小、度量方式）；论文未报告模型在其他设定下的表现。"],
debate:[
"这篇与本站已记录的基准批评（p36 Nature Methods、p40 VCC 复盘）属于同一谱系，但切点更新颖：它不再问「模型预测得准不准」，而是问「预测的向量里到底还剩下什么」。这是一次从误差评估到信息评估的转向。",
"可以预期的反驳是：检索扰动身份并不是扰动预测模型的设计目标，模型本来就是为预测平均响应而训练的——用它不能恢复身份来否定它，可能是在考核一个它从未被要求通过的考试。这个反驳成立与否，取决于社区是否认为「保留扰动身份」应当是虚拟细胞模型的必要条件。"],
takeaway:[
"对做评测的人：这篇给出了一个便宜且可复用的诊断——先测扰动身份检索，再谈强度与剂量。如果身份都丢了，下游任何精细评估都是空谈。",
"对做模型的人：一个明确的信号是，用平均表达谱作为训练目标可能正在系统性地抹掉扰动特异性信息。这是当前主流训练范式的结构性问题，值得认真对待。"],
further:["p36","p40","p81","p04"]},
{id:"p83",g:"g3",t:"Foundation Models Improve Perturbation Response Prediction",a:"Cole, E.; Huizing, G.-J.; … Lundberg, E.; Song, L.; Bar-Joseph, Z.; Xing, E. P.（GenBio AI）",v:"bioRxiv",d:"2026-10-22",doi:"10.64898/2026.02.18.706454",
summary:"对「基础模型不优于简单基线」这一流行共识的最大规模反驳：覆盖 600+ 嵌入-任务配对，结论不是「基础模型行」或「不行」，而是「多数基础模型没学到有用的因果结构」。",
background:[
"「基础模型在扰动预测上不优于简单线性基线」——这句话在 2025 年被反复引用，几乎成了领域共识（本站 p36、p45、p46 均记录了同类结论）。但它有一个方法论漏洞：多数对比只测了少数几个模型、少数几个数据集，且「基础模型」被当作一个整体来评判。",
"GenBio AI 联合卡内基梅隆大学（Xing、Bar-Joseph、Song）与 KTH（Lundberg）做了一次规模大得多的清扫：不是问「基础模型行不行」，而是问「哪些预训练嵌入、在哪些任务上、相对于什么基线行」。"],
method:[
"研究系统评估了预训练嵌入（不限于生物学基础模型，也包括其他来源的先验知识嵌入）在扰动响应预测上的效用，覆盖超过 600 个「嵌入 × 任务」配对。",
"同时提出了整合多个预训练嵌入以改进预测的方法——不再依赖单一嵌入，而是做嵌入层面的组合。"],
results:[
"结论是分裂的：部分基础模型确实无法超越简单基线，但另一些带来了一致的改进。也就是说，「基础模型不优于基线」这个全称判断是错的，正确的问题是哪个基础模型、在哪个任务上。",
"一个更耐人寻味的发现：表现最强的预训练嵌入并非来自大规模生物学语料的自监督预训练，而是来自先验知识（prior knowledge）派生的嵌入。这暗示当前生物学基础模型的瓶颈可能不在规模，而在其所学表示是否真正编码了因果结构。",
"多嵌入整合方法进一步提升了预测精度，作者据此认为预训练嵌入确实能够支持更准确的细胞行为模拟。"],
limits:[
"这是 2026 年 2 月首发、10 月 22 日更新至 v2 的预印本，尚未同行评议。600 个配对虽多，但仍受限于公开数据集的覆盖范围，绝大多数是细胞系层面的扰动。",
"「最强的是先验知识嵌入」这一结论对实践是双刃剑：它意味着当前的自监督预训练路线可能需要重新定位，但论文没有给出为什么先验知识嵌入更强的机制解释。"],
debate:[
"这篇实际上是 GenBio AI 对「基础模型无用论」的一次系统性反击，而 GenBio 正是 AIDO 系列模型的开发方——利益相关需要被明确标注。不过其结论并非一边倒地支持自家模型（它承认部分基础模型确实失败），这在方法上比单纯的自证更有说服力。",
"真正的争点在于：如果最强的嵌入来自先验知识，那么「规模定律适用于虚拟细胞」这一支撑整个赛道融资叙事的假设就进一步被削弱。这与 p82 的结论、以及本站记录的 X-Cell 规模扫描结果方向一致。"],
takeaway:[
"这是目前对「基础模型 vs 简单基线」之争规模最大的一次实证清扫，结论值得取代此前的全称判断：不是基础模型不行，是多数基础模型没有学到有用的因果结构。",
"情报视角：GenBio AI 在 AIDO.Cell 世界模型之后持续在扰动预测上投入，通讯作者 Elijah Cole 与共同作者 Eric Xing、Ziv Bar-Joseph、Le Song、Emma Lundberg 的组合意味着这份结果的方法论分量不低。建议与 p36、p82 对照阅读——三方证据合起来指向：问题不在模型大小，而在表示里有没有因果。"],
further:["p36","p82","p21","p03"]},
{id:"p84",g:"g7",t:"Virtual lineages: in silico lineage tracing from single-cell and spatial transcriptomes（isCORAL）",a:"Lin, Y.; Lin, Y.（北京大学）",v:"bioRxiv",d:"2026-10-20",doi:"10.64898/2026.10.19.760045",
summary:"只从一张转录组快照反推细胞亲缘关系：isCORAL 先找「记忆基因」，再建克隆导向的嵌入与命运图谱，并把它明确定义为未来虚拟细胞模型的一个输入模态。",
background:[
"实验谱系追踪能告诉我们一个细胞的来处与归宿，但它昂贵、侵入，而且在人原代组织里几乎不可行。于是领域一直在找替代品：能不能只从一张普通的单细胞转录组快照，反推出细胞之间的亲缘关系？",
"生物学依据是可遗传的表达差异：某些基因的表达水平会在细胞分裂后被「记住」并传递下去，构成一种谱系记忆。难点在于这种记忆信号极弱，且淹没在细胞状态的噪声里。北京大学的 Yihan Lin 团队给出了 isCORAL。"],
method:[
"isCORAL 先识别「记忆基因」——那些表达差异具有可遗传性的基因；再基于这些基因推断概率性的克隆关系；最后用这些关系构建面向克隆的嵌入（clone-oriented embedding）与动态的细胞命运图谱。",
"与直接对细胞做聚类不同，isCORAL 的表示空间是围绕克隆关系组织的，因此同一个克隆内部的动态轨迹可以被连续地追踪。"],
results:[
"在多个谱系追踪数据集上，isCORAL 在记忆基因识别与谱系重建两项任务上均明显优于被测的同类方法。",
"生物学应用上，它解析了转录上高度相似的造血干细胞之间的早期命运偏向，并预测了通向同一结局的不同发育路径。拓展到空间转录组后，它在小鼠肿瘤中用实验记录的谱系树验证了推断出的克隆关系，并在人类胚胎中推断了早期上胚层与羊膜的动态。"],
limits:[
"预印本，未经同行评议。记忆基因的识别依赖特定数据集的统计特性，在细胞周期活跃或高度可塑的组织中，可遗传表达差异可能被状态变化掩盖。",
"空间转录组上的验证目前是单一案例（小鼠肿瘤），人类胚胎部分的结论缺少实验谱系树的直接对照。"],
debate:[
"谱系推断长期存在「循环论证」风险：用表达相似性推断亲缘，又用亲缘解释表达相似性。isCORAL 通过显式分离记忆基因与状态基因来缓解这一点，但分离是否彻底仍有争议。",
"对虚拟细胞而言，作者自己的定位值得注意：isCORAL 提供的是「谱系记忆的显式表示」，作为未来虚拟细胞模型的一个输入模态。这等于主张虚拟细胞应当是有历史的时间性模型，而非无记忆的状态映射——与本站 p21（AIDO.Cell 有状态仿真）的主张相互呼应。"],
takeaway:[
"将谱系记忆做成可计算的显式表示，是对「静态快照建模」范式的一次补完。做发育、肿瘤演化、组织修复的团队值得直接试用。",
"更重要的信号是方向性的：2026 年下半年，无论是 Bolero 的细胞状态条件化、AIDO.Cell 的有状态仿真，还是 isCORAL 的谱系记忆，都在往同一个方向走——虚拟细胞需要记忆与时间。这与 Cell 纲领文中偏静态的「输入→输出」图景已经有了明显分歧。"],
further:["p21","p81","p01"]},
{id:"p85",g:"g3",t:"Distributed AI agents enable comprehensive discovery of biological insights at scale",a:"Sun, A.; Park, J. J.; DeTomaso, D.; … Zheng, G. X.; Jiao, Y. J.; Jin, X.（PerturbAI / OpenAI / Scripps / HHMI / UCSD）",v:"bioRxiv",d:"2026-10-16",doi:"10.64898/2026.10.15.759436",
summary:"OpenAI × PerturbAI 用近 2000 个并行智能体在 32 分钟内读完小鼠全脑 CRISPR 图谱，并开放推理图谱与代码。但 32 分钟是「读完」的速度，不是「发现」的速度。",
background:[
"大规模扰动实验已经跑得比人读得懂快得多：一次 Perturb-seq 可以敲掉上千个基因、测上百万个细胞，产生的数据量远超一个课题组能逐条解读的上限。瓶颈从「能不能测」移到了「测完之后读不读得完」。",
"OpenAI 与 PerturbAI、Scripps Research 的合作针对的正是这个新瓶颈：不是造一个更好的预测模型，而是造一支会自动读文献、自动写假设的解读队伍。成果以预印本形式发布于 bioRxiv（2026-10-16），OpenAI 于 10 月 21 日在官方博客宣布。"],
method:[
"系统把全脑 CRISPR 图谱（Whole Brain CRISPR Atlas，PerturbAI 于 2026 年初发布的小鼠全脑在体扰动图谱）拆开，交给数千个并行运行的 AI 智能体（基于生命科学推理模型 GPT-Rosalind）。每个智能体只负责一个基因扰动：检索该扰动下的细胞响应、定向搜索相关科学文献、提出机制解释。",
"所有局部报告最终被聚合为一张结构化「推理图谱」（Reasoning Atlas），建立「基因扰动 → 细胞响应 → 相关文献 → 潜在机制」的关联。论文报告在最大规模测试中运行了近 2000 个并行智能体。"],
results:[
"整个分析在 32 分钟内完成；团队估计同等工作由人工逐一完成需要数月到一年。在不接触原始论文的条件下，分布式智能体恢复了源论文的结论，并预测了被留出的扰动效应（held-out perturbation effects）。",
"文献覆盖是分布式方案的决定性优势：受上下文窗口限制，单智能体模式平均仅引用约 11 篇文献，而分布式集群总计引用超过 700 篇。盲法专家评审中，专家在 60 次比较里有 45 次（75%）更偏好分布式智能体的报告，单智能体报告被偏好 10 次（16.7%），5 次持平。",
"生物学线索方面，系统发现 Tsc1 与 Tsc2 在小脑中存在明显差异：操控 Tsc2 改变了数十个突触传递相关基因的活性，而 Tsc1 几乎无变化——TSC2 异常与结节性硬化症相关，且已知累及小脑。另一条线索指向 DCTN1（Perry 综合征相关基因）：其扰动使胆固醇合成相关基因上调，智能体据此提出「神经元内胆固醇运输障碍导致代偿性合成、进而驱动神经退行」的可检验假设。"],
limits:[
"预印本，未经同行评议；全部数据来自小鼠，非人类。转录层面的模式不等于临床结局，文献支撑的解释不等于因果机制，智能体的置信度不能替代一个设计用来证伪它的实验。",
"最大的结构性问题在评估本身：75% 的专家偏好是相对于单智能体报告的，而不是相对于人类专家自己写的报告，也没有与简单统计基线对比。因此它证明的是「分布式优于单智能体」，而非「优于人类」。"],
debate:[
"炒作与实质之间的距离需要被明确划定：32 分钟这个数字描述的是「对已有数据做第一遍解读」的速度，不是做出发现的速度。系统生成并排序的是研究线索（leads），不是结论。",
"更深层的治理问题随之而来：一个能一次生成数千条貌似合理线索的系统，会让「排序标准」变成一种权力——决定哪些基因拿到经费、哪些机制被看见。论文没有讨论排序偏差，但有理由怀疑系统会偏爱文献丰富的高关注度基因，而冷门通路可能因引用少而被系统性低估。这需要独立的评测。"],
takeaway:[
"这是 AI 智能体第一次在真实的大规模扰动图谱上跑出可核查的完整闭环，而且开放了推理图谱、代码与提示词，外部可复现——比一次发布会视频有价值得多。",
"情报视角：PerturbAI 与 OpenAI 已宣布将合作扩展到基于 PerturbAI 自有在体因果数据的药物靶点发现。这条线值得单列跟踪：它把「AI 读数据」直接接到「AI 找靶点」，是 2026 年 AI 制药链条上游化最具体的案例。对国内做同类平台的团队，这是明确的对标对象。"],
further:["p81","p82","p04"]},
{
    id: "p86",
    g: "g3",
    t: "PIE: Generalizing perturbation effects across unseen perturbations, contexts and datasets",
    a: "Verma, R.; Adduri, A.; Bevilacqua, B.; Eraslan, B.; Burke, D. P.; Goodarzi, H.; Roohani, Y. H.（Arc Institute）",
    v: "bioRxiv",
    d: "2026-10-05",
    doi: "10.64898/2026.10.02.756297",
    summary: "Arc 虚拟细胞系列的第三块拼图：State 从大规模扰动数据里学，Stack 让细胞本身充当提示，PIE 则把人类整理百年的生物学知识直接变成模型输入——而且它预测的不是单个细胞，而是筛选实验真正读取的群体水平读数。",
    background: [
      "Arc Institute 的虚拟细胞模型序列在过去一年半里依次给出了三种答案：State（大规模扰动预训练）解决「数据不足的细胞情境」，Stack（以细胞为提示）把观测数据里的已知响应搬进新情境，PIE 则换了一个方向——它不问「再多喂点数据能不能行」，而问「人类已经写进数据库的知识为什么没有进模型」。",
      "PIE 瞄准的错位在于：现有扰动预测模型大多在细胞水平上预测扰动后的表达，而评估它们用的却是群体水平的读数（差异表达基因集合、方向与幅度）。用单细胞技术今天根本测不准「真实扰动效应」的细胞级分布，训练目标与评价对象从一开始就错位。",
      "另一个未被开采的矿藏是系统表征：一个细胞系的 Cellosaurus 记录、一个基因的 NCBI 条目与 Gene Ontology 注释、DepMap 的依赖性谱、一个小分子的 PubChem 条目——这些人工整理了几十年的知识，此前从未被系统性地用作扰动预测的输入。",
    ],
    method: [
      "PIE 把学习任务重新表述为群体水平：输入一个（细胞情境，扰动）对，直接输出条件级结局——哪些基因差异表达、朝哪个方向、平均表达变化落在哪个量级区间。这大幅压缩了模型必须预测的结果空间，换取向新条件的迁移能力。",
      "架构基于 Perceiver IO，核心设计是容纳「可变特征集合」的输入：知识源被 token 化（Cellosaurus、NCBI Gene、Gene Ontology、DepMap、PubChem 等），叠加查询情境的平均对照表达与训练集中观测到的扰动响应统计。知识稀疏是常态，因此模型必须在训练和推理时都能处理来源不全。",
      "每个基因以其自然语言描述来表示。这一招让 PIE 能适配不同研究的基因词表，甚至对训练中从未出现的基因做出预测——知识库与词表都不再是硬边界。",
    ],
    results: [
      "在 Replogle–Nadig Perturb-seq 数据集（四条人类细胞系）上，PIE 在全部测试泛化设置中的多数指标达到 SOTA，包括最难的「细胞系与扰动双双未见」设置——这个设置下没有任何专用基线可以尝试。",
      "差异表达基因分类上，PIE 在每种设置下取得最强基线 1.2–3.2 倍的 AUPRC；跨训练时完全未见的数据集做零样本迁移时，多数指标仍胜过现有方法。",
      "作者诚实地划定了边界：PIE 在「情境或扰动单新」时表现最好，两者皆新时准确率明显下降——差距会随扰动数据集的规模与多样性增长而缩小，但今天它真实存在。",
    ],
    limits: [
      "预印本，未经同行评审，且全部结果为作者自评测，尚无第三方复现——在这个刚刚经历「基准审计」洗礼的领域，这一点必须前置声明。",
      "模型上限被知识库的覆盖度锁死：知识来源里没有的细胞系、没有注释的基因、没有 DepMap 谱的扰动，PIE 就退回「知识稀疏」模式。它不是学会了生物学，而是学会了读人类写下的生物学。",
      "双新场景的衰减幅度、知识源的边际贡献分解（作者自己也承认不同任务的主导来源不同），都还需要独立基准来检验。",
    ],
    debate: [
      "PIE 是「知识派」对「规模派」的一次实证反击。本站此前记录的两条独立证据（X-Cell 规模清扫显示测试损失在约 16 亿参数后几乎不再下降；Context, Not Just Scale 显示泛化随情境数而非细胞数上升）都指向同一个结论：堆细胞不如堆多样性。PIE 把「多样性」的边界又往外推了一层——细胞之外，还有文献与数据库。",
      "值得玩味的是 Arc 的产品节奏：PIE 的关键元素正在被并入开发中的下一代 State。也就是说，PIE 既是独立模型，也是 State 的试验田——「知识接地」路线已经从论文走进主力产品线。",
    ],
    takeaway: [
      "对研究者：PIE 给出了一个可直接复用的配方——把 GO/DepMap/Cellosaurus 这类「沉睡资产」token 化喂给模型，成本远低于再跑一轮 Perturb-seq。代码与权重已在 GitHub 与 Hugging Face 开放。",
      "对产业界：这条新闻的真正信号是「数据库质量=模型上限」。谁的生物知识基础设施更完整，谁的知识派模型就更强——这是一条此前被低估的护城河。",
    ],
    further:["p18","p04","p83"]
  },
{
    id: "p87",
    g: "g3",
    t: "UniPert-G2CP bridges genetic and chemical screens from molecular representation to phenotype modeling",
    a: "Li, Y.; Li, M.（中南大学）; Yao, J.; Yang, F.（腾讯生命科学实验室）; Zeng, M.; Zhu, J.; Liu, L.; Wang, F.; Huang, L. 等",
    v: "Cell",
    d: "2026-08-06",
    doi: "10.1016/j.cell.2026.06.005",
    summary: "中国团队第一次在 Cell 层面打通遗传筛选与化学筛选：蛋白质序列与小分子 SMILES 在对齐的共享语义空间里握手，「基因预训练+化学微调」让 20% 的化学数据发挥 375.4% 的性能——虚拟药物筛选的成本逻辑被改写。",
    background: [
      "实验药物筛选受困于化学空间的庞大、成本的高昂与通量的天花板；相比之下，遗传筛选（CRISPR）已经能大规模、系统地揭示基因扰动与细胞表型的关系。但两类扰动跨越不同分子尺度：基因与蛋白质是大分子，小分子药物是另一套化学语言，表征方式与数据来源都存在鸿沟。",
      "虚拟细胞研究因此面临一个具体难题：怎么把遗传筛选里学到的细胞响应规律，「迁移」给化学扰动？2026 年 8 月，中南大学李敏教授团队联合腾讯生命科学实验室在 Cell 发表的 UniPert-G2CP，给出了目前最系统的答案。",
    ],
    method: [
      "框架分两阶段。UniPert 是多模态分子统一编码器：融合蛋白质氨基酸序列（蛋白质语言模型）、小分子结构（SMILES + 图神经网络）、序列比对与化合物—靶标相互作用信息，用对比学习把遗传扰动因子与化学扰动因子映射到同一个具有生物学解释性的表征空间——无需人工标注即可捕获药物作用机制（MoA）与蛋白质药理学类别等高层功能信息。",
      "G2CP 是跨域迁移策略：先在大规模基因扰动数据上预训练，学习细胞背景与响应规律，再用有限的化学扰动数据微调，把「遗传筛选的知识」翻译成「化学扰动的表型预测」。",
    ],
    results: [
      "在多个大规模遗传—化学双域筛选数据集上，UniPert-G2CP 实现了两类扰动的有效知识迁移：在未见小分子条件下准确预测细胞表型响应，并保持对不同细胞背景异质性响应模式的刻画能力。",
      "最醒目的数字：仅使用 20% 的化学训练数据即实现 375.4% 的性能提升——化学扰动建模对大规模实验数据的需求被大幅降低。对高通量药物筛选而言，这是直接的 ROI 重构。",
      "框架学到的统一扰动因果空间还支持下游分析：药物作用机制解析、潜在靶点关联发现，以及不同细胞背景下耐药形成机制的研究。",
    ],
    limits: [
      "目前框架主要覆盖蛋白编码基因与小分子药物；非编码 RNA、多组学表型与更多细胞环境仍是明确留白的扩展方向（作者自述）。",
      "化学域数据虽经迁移增强，绝对规模仍受限；375.4% 的提升建立在特定基准上，跨数据集稳定性有待独立评测。",
      "作为 Cell 正式论文它通过了同行评审，但「未见小分子」的设定离真实的先导化合物优化场景仍有距离——后者的分子往往与训练集高度相似。",
    ],
    debate: [
      "这是中美路线差异的一个清晰切片：美国阵营的主线是大规模 Perturb-seq 数据军备赛（Replogle、X-Cell、VCC），用数据规模换泛化；中国团队则示范了另一条路——用迁移学习把已有的遗传筛选数据「复用」到化学域，用算法换数据。哪条路更接近通用虚拟细胞，现在下结论为时过早，但 UniPert-G2CP 至少证明：数据劣势未必是死局。",
      "另一个值得注意的事实：通讯作者里的腾讯生命科学实验室，是国内大厂在 AIVC 基础模型层最实体的存在之一——从模型到平台（上一代的 scBERT 谱系）到这次的 Cell 论文，腾讯的布局比外界感知的深。",
    ],
    takeaway: [
      "对制药业：虚拟筛选的评估口径应该改了——不再是「能预测多准」，而是「能省多少实验」。20% 数据达到 375.4% 提升，意味着筛选管线的设计可以围绕数据杠杆重新算账。",
      "对国内团队：这是「学术源头+产业接力」模式的又一例证（中南大学一作、腾讯深度参与），也是中国力量第一次在 AIVC 建模框架层（而非应用层）进入 Cell 正刊。",
    ],
    further:["p77","p83","p16"]
  },
{
    id: "p88",
    g: "g1",
    t: "A world model of the virtual cell",
    a: "Xing, E. P.（GenBio AI / MBZUAI / CMU）; Song, L.（GenBio AI / MBZUAI）",
    v: "Cell",
    d: "2026-09-17",
    doi: "10.1016/j.cell.2026.08.042",
    summary: "GenBio 创始人执笔的纲领文章：虚拟细胞不该只是「预测扰动后表达谱」的专用工具，而该是一个可干预、可回放、可设计的细胞世界模型。如果说 Bunne 2024 是 AIVC 的宪法，这篇文章就是第一份修正案——它把领域的北极星从「预测」改成了「仿真」。",
    background: [
      "Bunne 等人 2024 年的 How to Build the Virtual Cell 确立了三大支柱（表示学习、扰动预测、生成模拟），此后两年领域爆发：单细胞基础模型、扰动预测基准、大规模 Perturb-seq 数据集大量涌现。但这些工作绝大多数仍在「给定输入、预测终点」的单任务范式里——输入扰动，输出某一类读数，一步预测。",
      "同期 AI 领域正在发生范式迁移：世界模型（world model）成为通用智能的热门路线——维护一个持续演化的隐状态，让「动作」作用于状态、推演未来。Xing 与 Song 把这套范式正式引进细胞生物学。",
      "作者阵容本身也是情报：Eric P. Xing 是 GenBio AI 创始人兼首席科学家，Le Song 是 GenBio 首席技术官——这篇文章因此带有强烈的「路线图」色彩，它与 GenBio 的 AIDO.Cell 世界模型产品线互为表里。",
    ],
    method: [
      "文章给出虚拟细胞世界模型（VCWM）的定义：一个多模态、多尺度、动态、有状态的计算系统。多模态=同时处理基因组、表观、转录组、蛋白、结构、互作与形态；动态=输出状态轨迹而非孤立终点；有状态=前一次干预的结果成为下一次干预的初始条件。",
      "架构三组件：结构化编码器把异质观测嵌入统一的细胞隐状态流形；动作条件转移核心接收突变、药物、编辑等干预并更新隐状态；结构化解码器把隐状态还原为可观测读数，并强制跨模态输出的一致性——转录、蛋白、结构、形态必须来自同一套状态的演化。",
      "文章同时讨论了数据框架、训练策略与评测原则，并示范了一个典型场景：设计干预时序（小分子、基因编辑、蛋白）让衰老细胞恢复分化能力同时规避不良状态——这种组合干预的搜索空间大到湿实验无法遍历，正是硅内推演的价值所在。",
    ],
    results: [
      "作为观点/综述文章，VCWM 一文不报告新数据，它的「结果」是一份完整的愿景论证：从预测单个端点，走向可干预、可回放的模拟；从穷举实验搜索，走向在学到的细胞世界里结构化导航。",
      "文章提出两条扩展轴：纵向上建设「虚拟细胞银行」（virtual cell bank），收录不同细胞类型、发育阶段、遗传背景、疾病与环境条件下的细胞状态，支持调取、复制、扰动仿真；横向上把虚拟细胞向上组装成虚拟组织、器官直至生物体（AIDO），类比 EDA 之于半导体、仿真之于气象预报。",
      "时机上的佐证：这篇文章所在的 Cell 189 卷 19 期是「Focus on AI in biology」专题——VCC 2026 基准论文、State 正式研究论文、scBaseCount、Tahoe-100M 同期刊发。虚拟细胞在 2026 年秋天已经是一个「有专刊」的领域。",
    ],
    limits: [
      "观点文章无实证：架构的每一层都依赖尚不存在的技术条件。作者自己列出三道坎——配对多模态数据稀缺（同一细胞测多组学极难）、规模压力（全细胞尺度可能需千亿参数）、时序数据稀疏（很多轨迹靠快照推断，单细胞噪声大，速度估计不可靠）。",
      "评测范式完全缺失：作者明确反对把虚拟细胞压成单一分数，主张跨模态自洽性、多步组合泛化、实验指导能力三类标准，并呼吁社区共建「虚拟细胞竞技场」——但这套标准本身还没有被任何人实现。",
      "数据偏差的系统性风险：现有大规模扰动与多组学数据大多来自癌细胞系，带着癌特异基因组改变、超生理氧与营养、人工培养基底——模型可能高精度学到培养特异反应，却未必对应体内生理。个体化虚拟细胞还带来隐私、知情同意与治理问题。",
    ],
    debate: [
      "「预测派」与「仿真派」的范式之争因这篇文章浮出水面。本站此前跟踪的领域主线（更大模型、更多细胞、更高基准分）基本是预测派议程；VCWM 的宣言是：终点预测只是中间产物，可干预的模拟才是目的。这场争论不会很快结束——但它决定了未来五年什么工作算「重要」。",
      "需要保持的清醒：创始人发文即产品路线图。VCWM 的叙事与 GenBio 的 AIDO.Cell 商业利益同向，读者应把文章当作「愿景陈述+招聘广告+标准制定尝试」的复合体来读——其中最有价值的部分，是它对评测原则的呼吁，那恰好与本站「可证伪」的编辑方针同构。",
    ],
    takeaway: [
      "本刊社论《虚拟细胞不是新工具，是生物技术的新「操作系统」》的核心判断——模型从仪器变成假说生成器与实验调度器——在这篇文章里获得了学术表达：VCWM 把「实验调度」写进了架构（干预作为动作、状态作为记忆、轨迹作为输出）。",
      "对投资者：Cell 专刊 + 创始人纲领文 + 产品线三线合一，GenBio 已经占据了「定义赛道」的身位。当一家公司开始写赛道的教科书，它的竞争维度就不再是模型分数。",
    ],
    further:["p01","p21","p04"]
  },
{
    id: "p89",
    g: "g2",
    t: "Speciesformer learns conserved cellular states for cross-species generative virtual cell modeling",
    a: "Wang, J.; Dong, J.; Li, G.; Fang, C.; Liu, L.; Gao, X.（KAUST）× 联川生物（LC-Bio Technologies, 杭州）",
    v: "bioRxiv",
    d: "2026-09-22",
    doi: "10.64898/2026.09.22.752128",
    summary: "1.31 亿细胞、11 个物种、154 种组织——用「宏基因」策略把物种特异性基因映射到进化感知的共享空间，跨物种虚拟细胞第一次从口号变成架构；零样本扰动 AUPRC 0.588。这是中文世界本周热度最高的基础模型新闻。",
    background: [
      "现有单细胞基础模型绝大多数聚焦单一物种：人类图谱训出的模型，拿到小鼠数据上就「失语」。但虚拟细胞的抱负是预测任意细胞情境的响应——物种壁垒因此成为核心挑战。",
      "更深一层的动机是虚拟细胞的方法论本身：要区分「可迁移的生物学程序」与「情境特异性变异」，跨物种比较是天然框架——进化在长时间尺度上保留了一部分细胞程序、重写了另一部分，恰好提供了区分二者的实验场。",
      "2026 年 9 月，KAUST 高欣团队联合联川生物在 bioRxiv 发布 Speciesformer，直接把这个框架做成了模型。",
    ],
    method: [
      "预训练语料 SpeciesCorpus：1.31 亿个细胞、11 个物种、154 种组织、超过 923 种细胞类型——目前规模最大的跨物种单细胞语料之一。",
      "核心创新是「宏基因」（macrogene）策略：突破传统的同源基因映射（ortholog mapping）局限，把物种特异性基因映射到一个共享的、基于进化信息的基因空间，使进化距离遥远的生物体之间也能比较和整合表达程序，同时保留物种特异的转录信息。",
      "在共享表示之上，统一生成架构同时做两件事：编码器学习可迁移的细胞与基因表示（支持表示探查与跨物种知识迁移）；生成器在语义与干预条件下建模细胞状态及其转换——实现转录组状态与生物文本描述的双向生成，以及从初始细胞状态+干预描述预测扰动后转录组，包括既往未观测的细胞情境。",
    ],
    results: [
      "零样本泛化能力可与微调后的基线模型相媲美——在基准任务上不靠任务特定微调即达到专用模型水平，这是基础模型叙事的核心检验。",
      "扰动区分度方面取得最高 AUPRC 0.588（梅斯医学解读援引）；跨情境预测扰动效应的表现优于现有基线。",
      "作者同时展示了保守性细胞状态与情境依赖性响应可以在一套表示里被同时刻画——这正是虚拟细胞建模追求的结构。",
    ],
    limits: [
      "预印本，未经同行评审，无第三方复现；中文通稿的传播热度（联川生物官方发布+多家行业媒体解读）与证据等级之间存在落差，读者应回到原文核对数字。",
      "物种覆盖虽达 11 种，仍偏向有图谱积累的物种；生产端联川生物是参与方之一，其测序数据偏好是否影响语料构成，文章未充分讨论。",
      "「文本描述条件下的生成」部分的评估主观性强；0.588 的 AUPRC 绝对值仍不高，作者自己也呼吁在更广的扰动模式、数据集与生物情境中持续评估。",
    ],
    debate: [
      "Speciesformer 给「scaling」叙事增加了第三个维度：此前是细胞数（规模）与情境数（多样性），现在是物种数（进化跨度）。它与本站记录的 Context, Not Just Scale 证据链方向一致——决定泛化的从来不是单一规模指标。",
      "模式上值得记录：KAUST（学术源头）+ 联川生物（产业接力）的组合，与清华×百图、中科院×百曜、中南×腾讯一起，构成中国 AIVC 力量的第二种存在方式——不追求全栈闭环，而是在基础模型层做架构创新，由产业方负责数据与传播。",
    ],
    takeaway: [
      "对研究者：跨物种迁移有了可直接用的开源参照（预印本含方法细节），做动物模型—人类转化研究的团队应关注其基因空间映射方法。",
      "对观察者：中文世界正在形成自己的 AIVC 叙事节奏——从通稿热度看，基础模型层的「中国声音」比一年前响亮得多，但证据纪律（预印本标注、第三方复现）仍需本站这样的校准者。",
    ],
    further:["p04","p83","p79"]
  },
{id:"p90",g:"g3",t:"Single-cell–level digital twins for preterm birth prevention strategies（SIMCO）",a:"Einhaus, Neidlinger, Fondeur, Sato … Aghaeepour, Gaudillière（Stanford Medicine / UCSF）",v:"Science Advances",d:"2026-10-21",doi:"10.1126/sciadv.aed2741",
summary:"数字孪生在虚拟细胞叙事里常被当成 PPT 词汇。SIMCO 是本刊收录的案例中，第一个把「预测某个人给药后细胞状态怎么变」一路推到 FDA 批准临床试验的项目：斯坦福团队在妊娠免疫组的质量流式图谱上训练单细胞数字孪生，筛出阿司匹林 + 兰索拉唑联合方案，模拟延迟分娩的效果约为阿司匹林单药的 15 倍。",
background:[
"过去三年，「虚拟细胞到底能不能参与决策」是本刊追踪的主线之一，而批评性证据相当充分：p36 显示深度学习扰动预测整体上不优于线性基线，p82 显示 STATE 与 Cell2Sentence 的预测连扰动身份都恢复不了，p41 直接追问 AIVC 对科学发现是否有用。",
"这些批评有一个共同边界——它们几乎都只在「能否比基线更准地重建平均表达谱」这一个层面上展开。但临床和药企真正买账的问题是另一个：某个具体病人、在某种具体干预下，一个可测量的临床终点会不会改变。SIMCO 换的就是这个考场。",
"它也不走主流单细胞基础模型的路：既不是转录组测序，也不是动辄上亿细胞的预训练，而是用质量流式细胞术（mass cytometry / CyTOF）在蛋白信号层面读数，直接测量免疫细胞对外源药物的响应。"],
method:[
"SIMCO（Simulated Immunome Modeling of Clinical Outcomes）的结构分三步。第一步造数据：取受试孕妇的免疫细胞，在体外分别暴露于九种预先筛选为「妊娠期安全」的候选药物，用质谱流式测量各细胞类型的信号响应。团队称从约两亿五千万个细胞中测量了响应。",
"第二步把这张图谱作为训练与验证对象，使模型能对某个具体个体生成「给药前 / 给药后」两种单细胞状态的预测——这一步可理解为单细胞分辨率的虚拟扰动。候选药物清单来自 Sirota 团队（UCSF）搭建的老药新用管线，预先限定在孕期已知安全的范围内，这是整套设计能在孕妇身上做验证的前提。",
"第三步接上临床：整合 63 例妊娠的纵向数据，把细胞层面的信号位移与真实的孕龄长度锚定。因此模型的输出不是表达谱相似度，而是「分娩时间会推迟多少」。"],
results:[
"筛选结果：四氢叶酸（THF）以及阿司匹林 + 兰索拉唑联合方案成为预防早产的首选候选。2025 年 10 月的预印本版本还列出了第三种候选——四环类抗抑郁药马普替林（maprotiline），正式发表版的报道口径则只强调 THF 与联合方案。",
"最被反复引用的一条量化结果：在数字孪生系统中，阿司匹林与兰索拉唑联合延迟分娩的效果，约为阿司匹林单药的 15 倍，两者表现为协同而非相加。",
"机制层面，模型给出的解释集中在两条通路——增强先天免疫细胞中的 mTOR 信号，以及减弱初始 CD4+ T 细胞中的 JAK/STAT 信号。这正是 Bunne 纲领文所说的「虚拟仪器」价值：不只给答案，也给可以被实验检验的机制假设。",
"转化层面最硬的一条：团队表示该联合方案已在动物模型中验证，并获 FDA 批准进入临床试验。若人体读出为阳性，这将是数字孪生 / 虚拟细胞范式第一次在适应症拓展上跑通完整闭环。"],
limits:[
"必须先说清楚：15 倍是数字孪生模拟条件下的预测值，不是临床测得的效应量。它距离「联合用药确实更好」还隔着整整一个临床试验。",
"读数模态是质量流式，通道数量级远低于转录组。它能刻画信号蛋白层面的变化，但对转录层面的机制只能推测——mTOR 与 JAK/STAT 的解释来自模型推断，不是独立验证的因果链。",
"纵向队列只有 63 例妊娠。个体间差异被显式建模是设计优点，但这么小的队列对泛化性的支撑十分有限。",
"利益冲突需记录：三位作者为 SurgeCare 顾问，其中一位兼任该公司 CEO；另有五位作者为相关临时专利的发明人。"],
debate:[
"预印本与正式版之间有一处值得记录的差异：2025-10-01 的 bioRxiv 预印本摘要明确列出三个候选——THF、马普替林与阿司匹林+兰索拉唑；而 2026 年正式发表版的报道口径只强调 THF 与联合方案。马普替林在孕期的安全性轮廓远不如阿司匹林清晰，这个变化可以解释为作者在转译阶段趋于审慎，也可能只是报道取舍，本刊标注为待核实。",
"第二个争点更根本：SIMCO 到底算不算「虚拟细胞」。它不做跨细胞类型的基础模型，也不学通用细胞表征，本质是针对一个明确临床终点、在一个狭窄但定义良好的生物系统上做的单细胞仿真。按 Bunne 纲领文的定义，它更接近「虚拟仪器」而非「虚拟细胞」；但如果换成 p41 的实用性判据——「能否带来科学发现」——它反而是目前最接近合格的答案。",
"本刊立场：把 SIMCO 当作「虚拟细胞已经证明有效」的证据是过度解读；但它确实说明，当任务被收窄到「扰动 → 一个可测量的临床终点」，且数据是为回答这个问题专门造的，单细胞模型是能够产出值得下注的假设的。行业在参数量与层数上争执已久，也许真正稀缺的其实是收窄问题的能力。"],
takeaway:[
"对本刊记录的「AIVC 究竟有没有用」之争，SIMCO 是目前最好的一个反例：它不用最大的模型，也不用最多的细胞，靠的是「为特定临床终点专门造数据 + 单细胞分辨率 + 接上真实纵向队列」这一组合。",
"情报视角：注意成立仅半年、同样主打虚拟细胞的国内公司元示科技，其公开叙事与 SIMCO 高度同构——自建超高通量扰动数据产线、跨环境零样本泛化、湿实验验证闭环。这条路线在中美两地被同时下注，不再是孤例。",
"建议连同 p83（GenBio 的 600+ 配对清扫）一起读：前者说明「专数据专用」能赢，后者说明预训练嵌入的价值来源另有讲究。两者合起来，指向的建议是——别在「要不要上基础模型」上做判断题，要在「这份数据是不是为这个终点造的」上做判断题。"],
further:["p41","p83","p36","p82"]},
{id:"p91",g:"g4",t:"An autoencoder outperforms two transformers on prediction of gene expression from chromatin accessibility",a:"Jesse G. Meyer（Cedars-Sinai Medical Center, Department of Computational Biomedicine，单一作者）",v:"arXiv",d:"2026-10-20",doi:"10.48550/arXiv.2610.28853",pdf:"https://arxiv.org/pdf/2610.28853",
summary:"一篇单人作者的 arXiv 预印本，做了这个子领域很少有人做的事：在统一的特征、统一的划分、统一的指标下，横向比较七条「染色质可及性 → 基因表达」翻译管线。结果逆潮流——双变分自编码器 scButterfly-B 在全部 60 组配对 fold 比较中胜过所有受测 Transformer，训练时间还短 3.8 倍。",
background:[
"「给模型一张 scATAC 谱，预测它的 RNA 谱」是虚拟细胞叙事里最基础的一块砖：若这一步可靠，就能用便宜的表观测量推断昂贵的转录测量。过去三年提出的方案不下十种——BABEL、scButterfly、Polarbear、CMOT、MultiVI、GLUE，以及近两年的 Cisformer 与在大规模 ATAC 汇编上预训练的基础模型。",
"但这些论文几乎不在同一套条件下比较：特征空间不同、数据集不同、划分不同、指标也不同。于是某个提升究竟来自架构，还是来自评价设定，外界无从判断。作者引用了本刊已收录的同类证据——在其他单细胞深度学习场景中，简单基线常常能与大模型打平甚至超过它（参见 p36、p38）。",
"第二层问题更尖锐：部分论文在推理时喂给了模型部署时拿不到的信息。Cisformer 的做法是只向解码器询问那些「从目标 RNA 谱已知表达」的基因的丰度——这是一个合理但明显更容易的任务。"],
method:[
"基准本身：来自 19 项人类研究的 126,604 个配对单核 profile，共享 50,000 个 peak 与 3,185 个基因的词汇表；10 组 5×2 交叉验证 fold，共 70 次完整训练运行。",
"公平性处理刻意保守：每条管线保留自己的输入归一化与原生训练目标。作者没有强行统一一切，而是把「保持各自原生设定」作为比较条件的一部分——这是可以理解的选择，但也留下了讨论空间。",
"受测对象为七条已实现管线加两个参考预测器。Transformer 一侧的代表是自回归 Perceiver 架构的 Omic Translator，以及一个去掉 oracle 支持的 Cisformer 重配方版本。",
"最关键的设计是刻意加入两组「贫瘠对照」：一个完全不看输入、直接生成训练集均值 profile 的预测器，以及在真实表达基因位置上填常数的 oracle 支持协议。"],
results:[
"scButterfly-B（基于双对齐变分自编码器）在 per-gene 与 within-cell 两种 Spearman 相关上，于全部 60 组配对 fold 比较中胜过每一条 Transformer 管线，训练时间缩短 3.8 倍。",
"差距分布并不均匀：Transformer 在 within-cell profile 形状上只落后 0.02–0.04，但在 per-gene 相关上落后 0.10–0.24。也就是说它们大致能复现每个细胞的整体轮廓，却搞不清基因与基因之间的对应关系。",
"在留出的两种细胞类型上，per-gene 相关都偏低。对照实验显示足细胞（podocyte）的取值与同等规模已见细胞类型的典型水平相当；而潘氏细胞（Paneth）的取值，在 Omic Translator 的每一个分支上都等价于一次与细胞无关的随机打乱。",
"Transformer 内部的预注册消融给出两个反直觉结果：Perceiver 编码器相比全自注意力值 +0.0439 的 within-donor per-gene 相关；而一个「染色体感知」的基因组注意力先验反而使该指标下降 0.0096（donor 级符号翻转检验，Holm 校正后 p = 1.2×10⁻⁴）。",
"两个贫瘠对照的数值极具杀伤力：无输入的训练均值 profile 达到 0.314 的 within-cell 相关；在真实表达基因位置填常数则达到 0.996 的 per-gene 相关。作者因此把 oracle 支持协议降级为诊断工具，不再当作性能证据。"],
limits:[
"这是未经同行评议的单作者预印本，全部结论为作者自述，尚无独立复现。七条管线中有若干由作者本人实现，实现质量差异无法排除。",
"基准的调和方式本身是取舍：允许每条管线保留原生归一化与训练目标，提升了可比性的现实性，却也留出了调参自由度，严格性不及彻底统一设定。",
"留出的细胞类型只有两种，跨细胞类型泛化的证据极为薄弱。共享词汇表只覆盖 3,185 个基因，这是为了对齐 19 项研究做的取舍，代价是无法评估全转录组层面的表现。",
"只覆盖「ATAC → RNA」单向翻译，外推到其他跨模态填补任务需要谨慎。"],
debate:[
"这篇与本刊 g4 组的其余条目共享同一主题——架构叙事必须被同口径复现检验。但它的结论方向不太一样：不是「深度模型不优于线性基线」，而是「近两年的 Transformer 不优于 2024 年的双 VAE」。后者对「注意力天然更优」的默认假设伤害更大。",
"最值得防守的一点在实验设计层：作者允许每条管线保留自己的归一化与原生训练目标。这可以被赞扬为不强人所难的现实主义，也可以被批评为不够严格。读者应当据此调整对结论强度的预期。",
"还有一个错位需要澄清：scButterfly-B 的原方法论文发表于 Nature Communications 2024（10.1038/s41467-024-47418-x，本刊尚未收录），本次是把它作为基线之一放进统一基准。所以真正的新信息不是「自编码器很强」，而是「在同口径下，它比近两年的 Transformer 强」。"],
takeaway:[
"对本刊一直在追的「生物学先验是否有用」这条主线，这里给出的证据是分裂的：Perceiver 编码器有正贡献，但染色体感知的基因组注意力先验是负贡献。结合 p83（GenBio 发现最强的预训练嵌入来自先验知识）来看，先验不是「加上就一定好」，而取决于加在哪里、怎么加。",
"情报视角：做 ATAC→RNA 翻译、跨模态填补或虚拟测量（virtual measurement）的团队，这篇是目前唯一提供统一口径横向比较的信源，值得纳入选型参考。代码与一份经过审计的发布均已随文提供。",
"另外一个更值得警惕的信号：在最基础的模态翻译任务上，2024 年的成熟架构尚未被超越。这提示这条子线的实际进步可能远慢于叙事速度——与本刊在 g4 组其他条目上观察到的一致。"],
further:["p83","p36","p38","p24"]},
{id:"p92",g:"g7",t:"Probabilistic uncertainty in virtual spatial transcriptomics from histology is largely redundant with the predicted mean",a:"Batique, Nonchev, Koelzer, Rätsch（Ratsch Lab，ETH Zurich / 苏黎世大学医院）",v:"bioRxiv",d:"2026-10-23",doi:"10.64898/2026.10.23.760875",
summary:"「从 H&E 切片虚拟预测空间转录组」是近两年最热的分子病理方向之一，但几乎没人系统检验过它的不确定性估计到底有没有用。Ratsch 实验室在三个癌症队列上给出答案：不确定性确实与误差相关，但这个关联基本被预测均值解释掉了；扣除均值之后，不确定性对「哪里会错得离谱」几乎不提供额外信息。",
background:[
"虚拟空间转录组（virtual spatial transcriptomics, VST）的吸引力很直接：一张常规存档的 H&E 切片就能换算成空间分子图谱，不必真正做分子检测。近两年随着病理基础模型成熟，这条路线的工程完成度上升很快。",
"但几乎所有论文都以点估计的方式交付成果——给一张预测均值图，不提供可靠的不确定性。而如果要把它用于下游的分型、预后或治疗决策，「这张图哪里不能信」是一个必须先回答的问题。",
"不确定性量化本身已有方法储备：概率似然给出的偶然不确定性、近似贝叶斯给出的认知不确定性。真正被长期含混的问题是——满足了校准（calibration）的不确定性，是否真的具备信息性（informativeness）。"],
method:[
"作者在三个癌症队列上做系统基准，覆盖黑色素瘤、肺癌与肾癌肿瘤。",
"方法侧并行评估两类：由概率似然产生的偶然不确定性（aleatoric），以及由近似贝叶斯方法产生的认知不确定性（epistemic）；同时设置两个刻意贫瘠的对照——不依赖组织图像的方法，与无需额外训练的方法。",
"评价指标被刻意拆成两件事：校准性（不确定性与实际误差的统计一致性）与信息性（不确定性能否提供超出预测均值的误差信息）。这是全文最关键的一处分离设计。"],
results:[
"在全部队列与方法上，不确定性确实与预测误差相关——表面看，这是不确定性量化有效的证据。",
"但这个关联基本上被预测均值解释掉了。扣除均值之后，不确定性对较大的误差只提供很弱的信息。",
"更值得注意的是反向发现：良好的校准并不意味着信息丰富的不确定性。完全不用组织图像、直接拟合简单分布，即可达到可比的校准水平。",
"作者的结论因此是一次概念上的切割：应当把「校准良好的不确定性」与「有信息量的不确定性」区分开来，并主张不确定性必须提供超出预测均值的误差信息。",
"代码已在 GitHub 公开（ratschlab/uncertainty-vst-2026），外部可核验。"],
limits:[
"这是未经同行评议的预印本，结论为作者自述。三个队列全部为肿瘤组织，正常组织与非肿瘤场景未评估。",
"仅在回顾性存档切片上验证，未检验前瞻性采集、跨中心或跨扫描仪场景的稳健性。",
"摘要未说明「扣除均值」所用统计控制的细节，其口径强弱目前无法评估。",
"作者机构信息本刊依据 Ratsch 实验室惯例标注，以预印本正式署名页为准。"],
debate:[
"这篇的核心贡献不是又一次小规模对照，而是把一个长期被混为一谈的概念切开：「校准好的不确定性」与「有信息的不确定性」不是一回事，而领域里很多工作停在前者。",
"对本刊关心的虚拟细胞议题，它的含义更宽：如果一个模型的输出在点位置上不可靠，那么基于它所做的任何虚拟干预与反事实推断都会失去可信度基础。空间维度让这个问题更突出——空间模型本来就被寄望去承接「组织微环境 × 虚拟扰动」的下一段叙事（参见 p56 Nicheformer）。",
"可以与 p82 并读：p82 主张把评估从「误差」转向「信息」，本文则主张把评估从「校准」转向「信息」。两次转向指向同一个不满——领域习惯了用容易满足的替代品，冒充真正想要的性质。"],
takeaway:[
"情报视角：做虚拟染色、虚拟空间转录组或病理基础模型的团队，这篇应当被当作产品化前必须过的门槛——在向生物学用户交付「不确定性地图」之前，先问它是否携带了超出均值的误差信息。",
"对本刊而言，这也是第一篇明确以「不确定性是否有信息」而非「预测是否准确」为主题的收录条目。它与假装客观的均值图商品化叙事形成有用的对冲，建议在 p56 与 p57 的上下文里连同阅读。"],
further:["p56","p82","p29"]},
{id:"p93",g:"g3",t:"CauTrigger: deciphering biological system state transitions by hierarchical causal decomposition",a:"Zhang, C.; Cai, D.; Aihara, K.; Chen, L.（东京大学 / 上海交通大学 / 上海科技大学 / Sycamore Life Sciences）",v:"Nature Methods",d:"2026-10-22",doi:"10.1038/s41592-026-03274-9",
summary:"把「层级结构」本身写进因果模型：从观测组学数据里逐层剥离伪相关，定位驱动细胞状态转变的因果触发因子，并在模型内做虚拟扰动预测下游响应。",
background:[
"生物系统的状态转变——干细胞分化、重编程、疾病进展——总是伴随海量分子变化，但「表达变了」不等于「它在驱动」。更难的是，生物调控天然分层：转录因子作用于顺式调控元件，元件再作用于靶基因，上游因子往往只通过中间环节间接影响终点表型。用一张平网去做因果推断，混杂因素会造出大量看起来像因果的关联。",
"现有方法大多专注于推断基因调控网络，既缺少对通用层级调控的建模弹性，又只依赖观测数据、不支持干预式推理，因而无法估计反事实结果——而这恰恰是「找到可干预靶点」和「预测系统级反应」的关键。CauTrigger 的切口由此确定：不只识别触发状态转换的因果因子，还要还原连接各层的因果路径，并把「改变它会怎样」变成可计算的量。论文 2024-12-20 收稿、2026-09-22 接收、2026-10-22 在线发表，是一次历时近两年的评审。"],
method:[
"框架做「层级因果分解」：在第 i 层，候选上游触发因子被拆成两部分——对下游状态有贡献的因果成分，与当前层无法解释的残差成分；残差作为下一层的输入继续分解。如此逐层推进，最终重建出跨分子层级的因果图。它既支持预先定义的调控层级（如「转录因子 → 顺式调控元件 → 靶基因」），也允许在没有层级注释时自行推断。",
"底层解耦模型是双流变分自编码器（DFVAE）：输入先经特征选择层，把因果触发因子与虚假成分分开，再编码进由「因果」与「虚假」两支构成的潜空间；潜空间一方面解码出下游「传导因子」，另一方面预测最终细胞状态。训练目标是最大化从因果潜变量到结果状态的信息流，并引入基于 do-演算与后门调整的干预性因果目标，在模型结构假设下压低混杂影响。",
"三类应用被明确划出：层级因果分解（把多层调控拆成可解释路径）、遗传交互预测（两个扰动同时施加会怎样）、状态转换模拟（用 in silico 扰动推演系统如何移动）。"],
results:[
"模拟数据（两层与三层调控结构，因果强度 0.3 / 0.4 / 0.5，表达稀疏度 30% / 50% / 70%，每次十次独立重复，AUROC 与 AUPR 打分）上，CauTrigger 稳定领先 GENIE3、Scribe、DCI、Peter-Clark 算法、VAE、互信息、随机森林与 SVM。更有说服力的是分数的形状：离表型最近的第一层精度最高，越往深层按单调、可解释的方式递减——符合上游只能通过中间层间接作用的模拟设计，而多数基线拿不出清晰的层间区分。",
"最关键的鲁棒性测试是「不给层注释」：把所有层的因果变量混在一起喂给模型，只看全局重要性排序，CauTrigger 仍领先所有基线；用模型自己推断的层标签替代真实层标签，性能基本不掉。这说明它不只会在有答案时背答案。",
"真实单细胞数据上：hESC 分化与成纤维细胞重编程的 top-k 精度曲线整体高于对照（k 从 1 到 20，十次重复）；把 Yamanaka 因子（POU5F1/OCT4、SOX2、KLF4、MYC）与 Thomson 因子（POU5F1、SOX2、NANOG、LIN28）作为真值集，CauTrigger 把它们排得更靠前——不做任何监督标注，模型就把真正驱动重编程的因子推到了前列。",
"2 型糖尿病：781 个胰岛 β 细胞 metacell 的配对 scRNA + scATAC，纳入「转录因子 → 调控元件 → 靶基因 → 状态」三层框架。把三类特征简单拼接后做 PCA，对照、糖尿病前期与 T2D 三组样本分不开；换成三层 CauTrigger 学到的因果潜表示，三组被清楚分开——换一种表示，疾病阶段信号才浮出来。归因给出 46 个去重候选转录因子，FOS 与 JUN 在三种状态中都被稳定识别；in silico 激活后 T2D metacell 呈现向更健康状态转变的倾向。下游共有靶基因含 SLC30A8、RYR2、GPM6A：RYR2 在糖尿病前期 vs T2D 的 P 值为 2.00×10⁻¹³、对照 vs T2D 为 2.83×10⁻⁸¹；SLC30A8 对照 vs T2D 为 8.08×10⁻²⁸、糖尿病前期 vs T2D 为 0.397（不显著）。顺式窗口系统比较 ±50 kb 至 ±500 kb，±250 kb 最平衡（置换检验经验 P = 5.0×10⁻⁵）。",
"跨组学外延：30 名 ASD 儿童与 30 名年龄匹配对照的配对粪便菌群（74 个菌属）与宿主蛋白组（191 个特征），按「菌群 → 宿主蛋白 → 状态」两层建模。Faecalibacterium 偏离零分布最强，虚拟提高其丰度后，73% 的 ASD 样本局部流向对照样状态、83% 的对照样本保持在对照样状态；前十优先菌属连到的宿主蛋白中，IGHA1、IGHA2、IGLC2、IGKC 等参与免疫功能。"],
limits:[
"实验验证缺位：所有真实数据结论，包括 FOS/JUN 与 Faecalibacterium 的优先度，都还是计算推断与假设生成，作者自己强调因果关系与干预效果仍需针对性实验确认。",
"当前实现不考虑循环或反馈关系——既不含同层内的递归调控，也不含从下游到上游的反馈，而这在生物调控中很常见。",
"真实数据分析主要在相对同质的细胞语境下完成（T2D 分析聚焦 β 细胞以减少细胞类型构成混淆），跨细胞类型的调控交互没有被显式建模。",
"主要聚焦转录与染色质层；激酶、磷酸酶等上游信号调控因子因活性多受转录后调控，仅靠基因表达数据难以捕捉。",
"扰动效应预测的样本量偏小：受 TRRUST 先验收录转录因子的限制，CauTrigger 在 single / two-seen / one-seen / zero-seen 四类场景的样本量分别为 8、3、3、3，而适用对照方法的样本量为 36、9、43、19。作者坦率承认，在 two-seen 这类基准里简单的加性基线依然很强。",
"特征过滤机制是人工配置的，本质是在精度与召回之间做权衡，推断出的因果触发因子仍可能混入虚假生物信号。"],
debate:[
"这篇不在「模型够不够好」那条批判线上（那是 p36 与 p82 的活），而是补另一件事：即便观测数据充足，「关联」也不是「因果」，而虚拟扰动要站得住，必须先处理混杂。它把层级结构本身作为归纳偏置引入因果发现，并显式地把「虚假关联」建模成一个可分离的成分——这比多几个点的 AUROC 更实在。",
"对本刊关心的虚拟细胞议题，它代表一条与 scFM 并行而非竞争的路线：不做「先预训练大模型、再预测扰动」，而是从观测数据直接学一个可干预的层级因果模型。两条路线谁更能泛化，目前没有正面比较。可与 p71 GEARS（知识图谱上的组合扰动外推）、p32 STATE（大规模扰动数据驱动的状态转移）并读，三者对「扰动响应从哪来」给出的是三种不同答案。",
"作者的自制值得称道：他们没有把模型学到的因果路径说成已证实的机制，局限清单开得相当直接。"],
takeaway:[
"情报视角：这是「层级因果 + in silico 干预」这一支在 Nature Methods 拿到的方法学通行证，通讯组合为陈洛南（上海交大）与合原一幸（东京大学），中日联合、国内基金资助——对跟踪中国在该分支的位置有坐标意义。",
"读者需要抵挡的误读是「AI 找到了糖尿病靶点」。FOS/JUN 与 Faecalibacterium 都是待验证假设，模型给出的向量场应理解为降维状态空间里的方向性偏移，而非精确定量预测。本刊把它归入扰动预测组，正是因为它的产出形态是「虚拟扰动后的预测响应」，而非已确证的机制。"],
further:["p71","p32","p36"]},
{id:"p94",g:"g4",t:"Benchmarking segmentation methods for spatial transcriptomics",a:"Martínez-de-Morentin, X.; Khan, S. A.; Maillo, A.; Lehmann, R.; Kiani, N. A.; Lagani, V.; Gomez-Cabrero, D.; Tegner, J.（KAUST / SDAIA-KAUST 卓越中心 / 卡罗林斯卡学院）",v:"Nature Methods",d:"2026-10-23",doi:"10.1038/s41592-026-03272-x",
summary:"11 种分割方法 × 15 个数据集 × 5 个空间平台 × 12 种组织的大规模基准：分割算法的选择，能像下游分析方法一样强力改写生物学结论。",
background:[
"空间转录组的分析链路里，细胞分割是最容易出错、也最缺乏标准的一步——它直接决定细胞身份指派、空间组织表征与下游解释的质量。可长期以来，分割主要被当作「预处理」而不是「研究设计决策」。",
"既有基准的缺口有三：多数只用图像数据评测、忽略转录组上下文；缺乏统一的计算流程，用户面对异构格式与大数据集只能手工分块；缺乏带生物学意义的评价指标。结果是用户在为特定组织、平台或生物学问题挑选分割策略时高度不确定。这篇工作就是冲着这三个缺口去的。"],
method:[
"评测覆盖 11 种方法，横跨经典图像处理（Watershed）、纯图像深度学习（Cellpose）、Segment Anything 家族（SAM、SAM2、显微镜调优的 mSAM）、Transformer 路线（CelloType、Swin Transformer）、实例分割框架（Cascade Mask R-CNN），以及融合转录信息与成像的方法（BIDCell、SCS、Baysor）。",
"数据侧为 5 种空间转录组技术（Stereo-seq、Xenium、CosMx、STARmap PLUS、MERFISH）生成的 15 个数据集、12 种人与小鼠组织类型；单数据集规模从约 700 个细胞（卵巢癌）到 80 万以上（前列腺癌）。",
"为保证公平，团队搭了统一的 Nextflow 流程：标准化质控与预处理、图像转灰度、转录坐标映射到统一像素空间、patch 化并行处理、显存受限时把转录感知工具的输入限制在 top 1000 高变基因；分割结果按转录数与基因数阈值过滤，再把 patch 结果重对齐回原始坐标空间后统一打分。",
"评分采用 CellSPA 指标套件，共 15 项、归一化到 0–1，归为 8 个高层类别：分割完整性、转录本恢复、每细胞转录/基因丰度、基因水平一致性、形态保真、细胞类型组成相似度、基于已知 marker 的表达纯度、空间表达多样性，以及低维嵌入的轮廓系数。作者刻意不定义「最优指标子集」，因为最相关的判据取决于数据集与生物学问题。"],
results:[
"等权总分下 SAM 以 0.58 居首，SAM2 0.53、BIDCell 0.52、SCS 0.48 紧随，Baysor 与 mSAM 并列 0.45，Cellpose 0.42，CelloType 0.37，Watershed 稳定垫底 0.27。",
"但换成覆盖度调整（分割细胞数 / 参考细胞数）的总分，排序几乎翻转：SCS 以 0.34 居首，BIDCell 与 Baysor 均为 0.33；按「数据集夺冠次数」计，BIDCell 6 次、Baysor 5 次，显示同时考虑质量与产出时这两者更均衡。",
"指标层面的拆解暴露出根本性权衡：SAM 与 SAM2 转录丰富度最高（SAM 每细胞转录 0.71、每细胞基因 0.73），但 SAM 只分割到参考细胞的 0.28，SAM2 更低至 0.12；BIDCell 则以 0.62 的覆盖度配 0.89 的表达相关性；SCS 在形态与空间多样性上占优，并取得最高轮廓系数 0.75。",
"表达纯度是一个异类：它与任何其他指标类别都不相关，构成独立的评价维度；而它自身的两个分项彼此负相关——即便在一个概念类别内部也存在权衡。",
"两个方法被排除出定量比较：Swin Transformer 与 Cascade Mask R-CNN 产生了生物学上不可信的网格状伪影，边界由 patch 划分而非细胞结构主导。",
"跨技术分析（小鼠脑的 Stereo-seq、STARmap PLUS 与 MERFISH 可比数据集，并做配体-受体推断）显示：分割策略的选择会实质影响细胞类型特异性、转录本污染与配体-受体推断——也就是说，它会改写下游的生物学结论。"],
limits:[
"全部基于公开数据集，参考标注本身的质量构成评测天花板；「参考」不完全等于真值。",
"作者未提供最优指标子集，15 项指标的等权聚合本身是一种选择，不同加权可能改变排序。",
"Swin Transformer 与 Cascade Mask R-CNN 被剔除，意味着方法池在定量环节已被筛选，读者应把这理解为「在不产生网格伪影的前提下」的比较。",
"覆盖的平台与组织虽广，但并未穷尽新兴空间技术；结论向非肿瘤、非人鼠组织的直接外推需谨慎。"],
debate:[
"这篇与 p92（虚拟空间转录组的不确定性基本被预测均值解释掉）构成同一天出现的批判双子星，指向同一个不满：领域习惯把上游的工程选择当预处理，然后花大力气审视下游方法。分割质量与不确定性质量，是同一类被默认放过的变量。",
"对本刊的读者，最值得记住的不是「哪个方法第一」——因为按是否调整覆盖度，第一名就换人——而是：在你为模型差异争几个百分点之前，先确认你的分割没有把结论写歪。空间组学正在从「追求更高分辨率」转向「追问结果可靠性」。",
"也可与 p56（Nicheformer 把空间上下文纳入预训练）并读：当基础模型开始吃空间数据时，分割误差会以什么样的方式进入模型的表示，目前完全没有人测。"],
takeaway:[
"情报视角：这是空间转录组领域迄今规模最大的分割基准，且由 KAUST 与卡罗林斯卡的跨国团队完成并附带统一的 Nextflow 流程——它很可能成为后续方法论文的标准对照口径，值得跟踪其被引与方法池扩容。",
"对本刊的评测批判线，这篇补齐了「图像 → 细胞」这一层：既有的批评集中在「细胞 → 预测」（p36、p82、p91）与「预测 → 可信度」（p92），现在连「像素 → 细胞」这一最前端也已被证明会传导偏差。"],
further:["p92","p56","p57"]},
{id:"p95",g:"g7",t:"Overcoming segmentation bottlenecks in brain tissue for spatial proteomic inference at population scale（SPInfer）",a:"You, L.; Durbin, J. L.; Meng, G.; Stallaert, W.; Li, G.; Uttam, S.; Feng, H.; Glausier, J. R.; Wang, J.（匹兹堡大学 / 得克萨斯大学）",v:"bioRxiv",d:"2026-10-24",doi:"10.64898/2026.10.22.761199",
summary:"人脑组织的细胞分割是空间蛋白质组的瓶颈：微调 Cellpose-SAM 把 F1 从 0.37 抬到 0.84，而用零样本 mask 跑同一套阿尔茨海默病模型，FDR 校正后一个显著关联都找不到。",
background:[
"在人群尺度的空间蛋白质组研究里，数万张图像的下游估计全系于细胞分割的准确度。可预训练分割模型在人脑组织形态复杂的胞体上表现糟糕——这不只是「指标难看」，更关键的问题是：领域适配到底会不会改变下游的科学发现，此前没人量过。",
"这篇给出了一个罕见的直接对照：同一套模型、同一批数据，只换分割 mask 的来源（零样本 vs 微调），看结论是否还在。"],
method:[
"团队先用 120 张人前额叶皮层免疫荧光图像中的 5,832 个手工标注胞体建立基准，横向比较 8 种分割方法（覆盖经典、卷积与基础模型三类）。",
"随后对 Cellpose-SAM 做领域适配（微调），并把得到的 mask 与配对的单核 RNA 测序、空间转录组对照，检验恢复出的细胞组成是否可信。",
"下游验证规模为 69 名死后供体的 14,765 张图像，用同一套阿尔茨海默病病理模型分别在零样本 mask 与微调 mask 上运行并比较。"],
results:[
"微调后细胞分割 F1 从 0.37 提升至 0.84——零样本基础模型在这一组织上的基线低得出人意料。",
"微调 mask 恢复出的细胞组成与配对的 snRNA-seq 和空间转录组结果一致，说明提升不只是指标好看。",
"最硬的结果是下游对照：69 名供体、14,765 张图像上，同一套 AD 病理模型在零样本 mask 下经 FDR 校正后未发现任何显著关联；改用微调 mask 后找到 4 个，其中 3 个把更高的 OLIG2 阳性细胞比例与更重的神经原纤维缠结及斑块负荷联系起来。换句话说，分割质量直接决定了「有没有发现」。",
"在微调 mask 之上，图注意力网络在细胞核邻域上不依赖 marker 信息即分类出 4 种细胞类型；差异表达分析则把细胞形态与基因表达连了起来。资助来自 NIH（R01AG099232、R01AG080590）。"],
limits:[
"这是未经同行评议的预印本，结论为作者自述。",
"仅覆盖单一脑区（前额叶皮层）与单一成像模态（免疫荧光），向其他脑区、其他染色方案的外推未验证。",
"AD 关联来自观察性尸检队列，因果关系与反向因果均无法排除；摘要未说明供体人口学、合并症与批次结构，混杂控制的强度本刊无法评估。",
"F1 提升的相对参照系是「零样本基础模型」，而非人工标注者间一致性上限——0.84 是否已接近该组织的天花板，摘要未给出。",
"作者机构归属本刊依据 bioRxiv 署名页标注；匹兹堡与得州的具体分工以正式署名页为准。"],
debate:[
"与同一天上线的 p94（11 种分割方法的大规模基准）构成一组有意思的对偶：p94 在方法层面论证「分割选择会改写结论」，p95 则在真实人群队列上给出了实证——零样本全军覆没，微调后才出现 4 个显著关联。一个讲可能，一个讲代价。",
"对本刊关心的虚拟细胞叙事，它的含义是双向的：一方面，它证明「通用基础模型 + 少量标注微调」能在人群尺度兑现真实的生物学发现，这是基础模型路线最扎实的一类证据；另一方面，它也给所有打算把通用分割/表征模型直接套到新组织的团队提了个醒——代价可能是统计学上什么都看不见。",
"可与 p92 并读：p92 说「校准好不等于有信息」，p95 说「分割差会让你一个信号都拿不到」。两篇都把批判的矛头从模型架构移到了容易被默认放过的工程环节。"],
takeaway:[
"情报视角：做空间蛋白质组/空间转录组产品化的团队，这篇应当与 p94 一起当作上线前的门槛读物——先量一下你的 mask 会不会把结论抹掉，再谈模型创新。",
"对本刊而言，这也是收录的第一篇以「分割质量 → 下游发现是否存在」为因果链的工作。它的 73%/83% 之外的核心数字其实是那个 0：零样本条件下，FDR 校正后无显著关联。"],
further:["p94","p92","p57"]},
{id:"p96",g:"g7",t:"Multiomic characterization of microsatellite-stable colorectal cancer reveals distinct biology and targetable vulnerabilities（iPhenMap）",a:"Sadanandam, A.; Byrne, A.; Dienstmann, R. 等（英国癌症研究院 ICR / 爱尔兰皇家外科医学院 RCSI / 巴塞罗那 Vall d'Hebron 肿瘤研究所）",v:"Cancer Cell",d:"2026-10-22",doi:"10.1016/j.ccell.2026.09.014",
summary:"用机器学习把约 2000 例结直肠肿瘤的基因组、表观组、蛋白组、代谢组与单细胞数据整合为一张「肿瘤生物图谱」，在最难治的 MSS 亚型上找出可靶向脆弱性，并在实验室模型中验证了含已获批药物的组合方案。",
background:[
"微卫星稳定（MSS）型结直肠癌占爱尔兰每年约 2500 例新发肠癌的 80%–85%，其中 40%–50% 携带 RAS 突变，RAS 突变患者预后持续劣于野生型。化疗联合靶向药或免疫检查点抑制剂的试验，相对现有标准只带来有限改善——作者直言 MSS CRC 患者的生存率近几十年没有显著提高。",
"既往研究的问题在于分层看数据。团队在论文中明确写道：据其所知，此前没有研究在 MSS CRC 场景下把 bulk 基因组、表观基因组、蛋白组、代谢组与单核/单细胞 RNA 测序及临床表型（phenome）做全局整合。iPhenMap 就是为这个整合而生的方法。",
"本刊收录说明：这并非虚拟细胞建模论文，而是「AI 整合多组学 → 可验证脆弱性 → 老药新用」的样板。它构成本刊关心的命题——计算模型的输出如何变成湿实验假设——在下游最完整的一个出口，因此破例收录并标注定位。"],
method:[
"数据侧为约 2000 例患者肿瘤样本，其中包含 300 余例此前从未被 profiling 的 MSS CRC，覆盖 DNA、RNA、表观、蛋白、代谢、单细胞/单核转录与临床参数，由 COLOSSUS 联盟（欧盟 Horizon 2020）等欧洲多国合作汇集。",
"方法侧是团队自研的机器学习方法 iPhenMap（部分早期报道写作 iPhMap，以论文正式名称为准），用于构建肿瘤的「生物图谱」——把肿瘤内部遗传特征、代谢特征等不同要素连成一张关系图，从而暴露孤立分析各模态时被漏掉的关联。"],
results:[
"图谱识别出既往未被发现的肿瘤脆弱性，即癌细胞分裂、生长、适应与微环境互作方式中可被药物打断的环节。",
"团队在实验室模型中验证了若干药物组合，其中已获批用于特定突变黑色素瘤、肺癌与甲状腺癌的靶向药 trametinib，与其他药物联用时显著减缓肿瘤生长并延长生存。",
"作者的表述相当克制：结论是「为 CRC 研究社区提供了一份丰富资源，并为具有转化潜力的联合治疗方案提供了证据」，而非宣称找到了新疗法。通信作者 Byrne 强调下一步是找出能预测响应的生物学特征，并把方案安全地推向临床评估。",
"资助来自欧盟 Horizon 2020 的 COLOSSUS 项目与 Research Ireland 对 Byrne 教授的项目资助。"],
limits:[
"全部结论为临床前：实验室模型中的肿瘤生长与生存改善，不能直接外推到患者生存获益。",
"公开报道未给出被验证组合中的具体药名（trametinib 除外）、样本量与效应量，定量强度无法从媒体口径评估。",
"iPhenMap 的整合是关联性建模：它建立的是肿瘤内部要素之间的连接与可靶向假设，不等同于因果机制。",
"队列以欧洲多中心样本为主，人群与诊疗背景的外推性未评估。"],
debate:[
"把它与 p90 SIMCO 并读最有信息量：两者都是「计算模型输出 → 进入实验验证门槛」的案例，但证据强度差一档——SIMCO 的联合方案已获 FDA 批准进入临床试验，iPhenMap 的组合仍停留在实验室模型。这条落差恰恰是本刊反复强调的分级：模型产出、实验验证、监管批准是三件事。",
"另一个值得注意的点是可复用性：iPhenMap 不是为某一种癌症定制的，团队明确认为这套作图思路可以迁移到其他肿瘤类型。若成立，它的价值不在这一次发现，而在方法本身。",
"对本刊的核心议题，它其实提出了反问：如果多组学整合 + AI 就能找出可靶向脆弱性，那么虚拟细胞模型的增量价值到底在哪里？目前没有研究正面回答这个问题。"],
takeaway:[
"情报视角：这是「老药新用（drug repurposing）」路线在 2026 年规模最大的一次多组学实践，且由 RCSI 与 ICR 联合主导、欧盟资助——对跟踪欧洲在该方向的组织方式有意义。",
"读者需要抵挡的误读是「AI 找到了结直肠癌新疗法」。所有结果均为临床前，作者自己也强调下一步才是找响应预测标志物。本刊把它归入多组学组，正是因为它的贡献在整合方法而非细胞建模。"],
further:["p90","p04","p28"]},
{id:"p97",g:"g2",t:"BLOOM: Biologically Informed Flow Matching for Transcriptomic Virtual Embryo Modeling",a:"Liang, Li, Li, Huang, Yu（香港大学；通讯：Lequan Yu）",v:"bioRxiv（预印本，未经同行评议）",d:"2026-10-27",doi:"10.64898/2026.10.26.761895",
summary:"面向「虚拟胚胎」的条件生成框架：以条件流匹配把时间群体情境与发育 / 调控先验结合，在三套小鼠图谱上于基因表达相关性与细胞表达相关性两项指标胜过 22 个时间序列预测基线，并支持未测时间点的插值与自回归外推。",
background:[
"「虚拟胚胎」是 2026 年虚拟细胞领域最具体的一条赛事化赛道：Stanford Qiu Lab 主办的 NeurIPS 2026 Virtual Embryo Challenge 把任务定义为由观测时间点预测未见时间点的细胞群体表达，测试阶段于 10-27 开启（本站 10-26 已记录）。这条赛道的科学前提很直接——发育图谱是离散采样的，而生物学问题是连续的。",
"离散采样留下的空档正是生成式建模的用武之地：若能学会细胞群体随发育时间变化的分布演化，就能在两个实测时间点之间插值，甚至向两端外推，把昂贵的时间序列实验压缩成少量锚点。此前该方向的主流做法是直接借用通用时间序列预测模型，缺少针对发育生物学结构的专门设计。",
"BLOOM 在这一时间窗口出现并非偶然：它与赛事测试阶段开启几乎同步，是「虚拟胚胎」从赛事命题走向具体方法实现的一次公开落地，且出自香港大学团队。"],
method:[
"框架核心是条件流匹配（conditional flow matching）：不直接回归表达值，而是学习从噪声分布到目标细胞表达分布的连续变换路径，条件变量为查询的发育时间点。",
"「生物学知情」体现在两处注入。其一，时间群体情境（temporal population context）——把整个细胞群体的状态分布而非单个细胞作为条件；其二，发育与调控先验（developmental and regulatory priors）——把已知的发育阶段结构与调控关系写进生成过程。",
"由于流匹配建模的是分布之间的路径，模型可以在时间轴的两个方向上生成，既向更早也向更晚的阶段推演，这在自回归 rollout 之外提供了额外的灵活性。",
"在未实测时间点上，作者给出两种用法：插值（在实测点之间补空档）与自回归的历史 / 未来 rollout（把已生成的状态再作为输入继续向前推）。"],
results:[
"评测覆盖三套小鼠单细胞图谱：产前发育、视觉皮层成熟与多器官内皮特化，代表发育生物学的三种不同时间结构。",
"在与 22 个时间序列预测基线的比较中，BLOOM 在三个数据集的基因表达相关性与细胞表达相关性两项指标上均排名第一。",
"已测阶段的评测支持其恢复发育表达模式、群体组织与标志基因的时序关系；生物学分析把这些预测连接到细胞状态身份、基因程序与调控关联。",
"在未测阶段，插值与 rollout 扩展了模拟的表达动力学范围；标志基因与时间描述符的分析识别出肌肉相关、神经与血管特化程序在时序上的候选差异。基于输入的基因扰动进一步探测了被编辑基因及其关联分子程序随时间的预测响应。"],
limits:[
"预印本，未经同行评议；全部结论来自作者自评，尚未经第三方复现，也未在赛事排行榜上获得独立验证。",
"三套图谱全部为小鼠。跨物种外推能力——尤其是向人类发育数据的迁移——未被检验。",
"未测阶段的插值与外推没有真值可比对：这部分结果本质上是模型生成的假设，而非被验证的预测。作者用「候选差异（candidate differences）」描述，措辞是克制的。",
"比较基线为 22 个通用时间序列预测方法，未包含同期其他虚拟胚胎 / 虚拟细胞专用生成模型，因此「第一」的参照系有限。"],
debate:[
"与本刊持续追踪的评测批判并读，最值得警惕的是指标本身：基因与细胞表达相关性是分布层面的相似度，它不保证标志基因的时序关系正确，也不保证扰动响应正确——而后者恰恰是虚拟胚胎模型被期待产出的东西。",
"比赛的尺子与论文的尺子未必一致。BLOOM 是否在 Virtual Embryo Challenge 的测试集上同样领先，目前无从得知；论文的自评口径与赛事的评分口径是两回事。",
"它抛出的一个真问题是插值与外推的证据分级：实测点之间补齐可以事后验证，向两端外推则要等新的实测数据才能判定。把两者混为一谈，是这类模型最常见的过度宣称。"],
takeaway:[
"情报视角：这是本刊首次收录以「虚拟胚胎」为明确任务对象的生成式方法，且出自香港大学团队——中国团队在虚拟细胞赛道的存在感正从基础模型延伸到发育建模。",
"对读者的提醒：把它理解为「能补发育时间空档的生成器」，而不是「能预测实验结果的模型」。它产出的最可靠产物是可排序的假设，不是结论。"],
further:["p04","p88","p21"]},
{id:"p98",g:"g4",t:"Evaluation design shapes estimates of cross-donor generalization in single-cell classification of cell-type",a:"Chen, Li, Battle（Johns Hopkins University；通讯：Alexis Battle）",v:"bioRxiv（预印本，未经同行评议）",d:"2026-10-27",doi:"10.64898/2026.10.26.761949",
summary:"同一批数据、同一批模型，只改切分方式就能系统性抬高单细胞细胞类型分类的报告成绩：随机细胞级切分的 macro F1 持续高于留出供体的评估，且该差距无法由批次协变量校正或供体混合效应建模消除。",
background:[
"单细胞数据有一个几乎所有评测都在回避的结构性事实：同一供体的细胞彼此不独立。它们共享基因型、年龄、疾病状态与取样批次，本质上是一簇相关样本，而非独立同分布观测。",
"但细胞类型分类器的常规评测用的是随机细胞级切分（random cell-level split），同一供体的细胞会同时落在训练集与测试集里。方法学上这等于让模型在测试时已经「见过」这个供体——测出来的泛化是跨细胞的，不是跨个体的。",
"隐患的严重性取决于任务：若目标只是给一批已知供体的细胞打标签，随机切分并无大碍；若目标是「模型能否用在新病人身上」，随机切分给出的数字就是系统性高估。Battle 组的这篇短文把问题直接摆上了台面。"],
method:[
"控制变量做得干净：在 PBMC 与肺数据集上保持数据与模型不变，只切换评测设计——随机细胞级切分对照留出供体（donor-held-out）评估，并在多种表达表示（expression representations）上重复。",
"为排除「差距只是批次效应」这一最自然的反驳，作者做两层校正：批次协变量调整，以及供体水平的混合效应建模。",
"两个对照组值得注意：一是肾、胰腺与血液这几个接近天花板的基准（差距应当消失），二是随机标签的地板对照（floor control）。它们的作用是界定偏差出现的条件，而不只是报告它存在。"],
results:[
"在 PBMC 与肺数据集上，随机细胞级切分在多种表达表示下持续给出更高的 macro F1，差距方向一致。",
"该差距在批次协变量调整与供体水平混合效应建模之后依然存在——说明它不是批次效应的简单代理。",
"相反，在接近天花板的肾、胰腺与血液基准上，以及在随机标签的地板对照中，评测差距极小。",
"作者据此给出分层结论：评测偏差取决于底层的分类状态（classification regime）；只有当声明涉及对未见个体的泛化时，留出供体评估才是必要的。代码与数据公开（GitHub / Zenodo 10.5281/zenodo.23669184）。"],
limits:[
"预印本，未经同行评议；篇幅为短文（Motivation / Results / Availability 结构），未给出完整方法学推导与全部补充实验。",
"数据集限于 PBMC 与肺（对照为肾、胰腺、血液），未覆盖空间转录组、多组学或扰动数据。",
"任务限于细胞类型分类。扰动响应预测、跨情境泛化等虚拟细胞核心任务上的对应偏差未被测量——尽管读者很容易把结论外推过去。",
"接近天花板的基准上「差距极小」，也可能源于天花板效应压缩了可观测的差异空间，两种解释无法从现有数据区分。"],
debate:[
"与本刊近期记录的评测批判放在一起，这篇属于同一家族但攻击点不同：此前的批评大多指向指标本身（MSE、Pearson(Δctrl) 的信号稀释）或基线缺失（恒等预测器拿满分），而这一篇指向数据的切分单位——在指标与基线都正确的前提下，光是「谁进测试集」就能改变结论。",
"最值得讨论的是作者那句克制的限定：评测偏差取决于底层分类状态。这意味着不能简单号召「所有评测都改成留出供体」——对接近天花板的任务，这样的改动可能只是增加方差而不改变结论。",
"读者最可能犯的过度外推，是把它直接读成「所有单细胞基础模型的成绩都注水了」。作者并没有这么说；他们说的是，当主张是跨个体泛化时，随机细胞级切分给出的证据不支持该主张。"],
takeaway:[
"情报视角：这是 Battle 组（Johns Hopkins）在评测方法学上的又一次补刀，与本站 10-24 以来连续记录的评测审计形成合力——2026 年下半年，AIVC 领域的批评火力已明显从模型转向评测本身。",
"对读者的实际用处：下次看到「细胞类型分类准确率 XX%」，先问一句测试集是随机切分还是留出供体。这一句话就能把相当一部分报告成绩打回原形。"],
further:["p36","p37","p72"]},
{id:"p99",g:"g4",t:"Prediction transfer does not imply reliability transfer in single-cell foundation models",a:"Park, Sriram, Luo, Zhang（University of Pittsburgh；通讯：Hyun Jung Park）",v:"bioRxiv（预印本，未经同行评议）",d:"2026-10-26",doi:"10.64898/2026.10.21.760716",
summary:"提出「可靠性迁移」这一与预测迁移并列的泛化维度：模型对自己何时会错的判断能否跨情境迁移，无法由预测性能推断——在 10 个扰动预测系统上，两者的表现彼此脱钩。",
background:[
"单细胞基础模型正在被跨组织、跨疾病、跨扰动筛选与跨实验平台地迁移使用。领域把大量精力投向「预测迁移」——模型在一个情境训练、在另一个情境还能不能预测对。",
"被忽略的是另一个问题：模型对自己预测可信度的评估（什么时候可能对、什么时候可能错）能不能同样迁移。在扰动筛选这类下游场景中，决定实验优先级的往往不是预测值本身，而是置信度排序。",
"匹兹堡大学 Hyun Jung Park 团队的这篇预印本把该问题单独拎出来，命名为「可靠性迁移（reliability transfer）」。"],
method:[
"定义：可靠性迁移指「对模型预测何时可能正确的准确评估」能否跨情境转移。作者在 10 个扰动预测系统上考察其行为，系统覆盖多个数据集、模型与评测设置。",
"为刻画变异来源，作者引入「可靠性归因指纹（reliability-attribution fingerprints）」：用严格交叉拟合（cross-fitted）的 SHAP 解释，汇总可靠性估计器在赋予置信度时如何组合生物学与情境信息，形成情境级别的签名。",
"分析维度包括生物学注释、网络连接度、靶点暴露度与情境因素，用以区分哪些信号是共享的、哪些是情境依赖的。"],
results:[
"可靠性迁移在不同源-目标配对之间差异显著，且无法从预测性能单独推断——作者据此主张预测迁移与可靠性迁移构成两种不同的泛化形式。",
"预测可靠性同时与共享信号和情境依赖信号相关，两者在不同系统中的相对重要性不同。",
"归因量级指纹相似的情境往往能更成功地迁移可靠性；指纹相似度能在候选集中识别出可靠性迁移表现更好的迁移源。但在更严格的跨家族迁移设置下这些关系减弱——说明可迁移的可靠性结构仍部分依赖共享的情境信息。",
"一个实际后果很直观：迁移后的可靠性估计器在预测值完全相同的情况下，给出了不同的扰动排序。"],
limits:[
"预印本，未经同行评议。",
"10 个扰动预测系统虽跨数据集与模型，仍是有限样本；指纹相似性与迁移成功率的关系是观测到的关联，而非被证明的机制。",
"作者自己指出，在更严格的跨家族迁移设置下这些关系减弱——指纹方法的适用边界尚未厘清。",
"SHAP 解释本身依赖背景分布与模型可解释性假设，交叉拟合可以缓解但不能消除这一依赖。"],
debate:[
"这篇的贡献更多在提出问题而非给出解法：它证明了一个此前被默认等价的维度其实是独立的，但并未提供提升可靠性迁移的方法。",
"与本刊记录的「评测框架的六类失效模式」并读很有意思：那篇讲指标会奖励恒等预测器，这篇讲置信度本身可能不迁移。两者指向同一个更深的问题——我们对模型输出的信任，缺乏独立于性能的校准手段。",
"「预测相同但排序不同」这个结果值得单独记一笔：它意味着在资源有限的下游筛选中，换一个迁移源就可能换一批被优先验证的基因，而预测值本身毫无变化。"],
takeaway:[
"情报视角：继「情境 vs 规模」「恒等预测器满分」之后，AIVC 的评测批判正向第三个维度扩展——从预测准不准，到模型自己知不知道准不准。",
"实用提醒：若你的流程依赖模型置信度做实验优先级排序，这篇给出的警告很具体——置信度的跨情境可迁移性需要单独验证，不能由准确率代入。"],
further:["p36","p45","p82"]},
{id:"p100",g:"g2",t:"Building virtual cell dynamics that evolve with biological measurements",a:"Zhang, Wang, Tian, Zhou, Zhou, Nie, Zhou（通讯机构：北京大学；通讯：Peijie Zhou）",v:"bioRxiv（预印本，未经同行评议）",d:"2026-10-27",doi:"10.64898/2026.10.23.761350",
summary:"提出 CellCompass——把科学智能体与可扩展动力学引擎耦合的 agentic AI 系统，让虚拟细胞的动力学形式能随新的生物学测量而增长；配套 DynBench100（100 个隐藏真值的模拟单细胞时间序列场景）作为验收基准。四个真实案例中，引入新的测量模态分别把可辨识性误差压低 31.1%、克隆命运一致性抬高 54%、未来表面蛋白分布误差压低 13.2%。",
background:[
"现有虚拟细胞模型都搭在一组写死的动力学假设上：RNA velocity、生长-死亡、状态转移核……这些形式是前人给定的，不是从数据里长出来的。",
"但实验测量在持续加入新约束：代谢 RNA 标记给出新转录本的时间分辨信息，克隆条形码给出谱系亲缘关系，时序 CITE-seq 给出蛋白与转录之间的时间差。旧公式表达不了这些关系，于是「数据增量」并不自动变成「模型增量」。",
"2026 年 agentic AI 已进入建模环节——本站已记录 CellForge 用多智能体端到端自主设计扰动预测模型。但那类工作聚焦的是「给定任务自动选架构」，而不是「给定新测量自动改动力学」。CellCompass 把问题推进到了后者，这是更难的一层。",
"还有一层现实约束：一个能自己改写公式的系统，先得有一个能判定「改得好不好」的尺子。模拟数据带隐藏真值，是唯一能严格打分的地方——这正是 DynBench100 存在的理由，也是它的说服力边界所在。"],
method:[
"系统由两部分构成：一个科学智能体（决定该建模什么生物学关系、写进公式的哪个位置、以及如何验证恢复效果）与一个可扩展的动力学引擎（负责实现与求解）。",
"工作流是「复用优先」：若已有公式足以表达新测量带来的约束，就沿用；不足时才由智能体设计、实现并迭代 refinement 新的动力学形式。",
"判定「足够」的标准不是拟合优度，而是新测量引入的约束是否被表达出来——这把建模从曲线拟合问题重新定义为约束满足问题。",
"输出覆盖三类读数：状态转移、群体变化，以及命运与分子层面的 readout，便于与不同的实验测量对齐。"],
results:[
"DynBench100 包含 100 个带隐藏动力学真值的模拟单细胞时间序列场景。CellCompass 在六类动力学任务上的综合表现高于受测的通用智能体与生物医学专用智能体。",
"药物响应数据上，纳入代谢 RNA 标记后 pulse-control 可辨识性误差下降 31.1%，并揭示出分阶段的响应程序，给出针对候选适应性程序的可检验扰动预测。",
"造血谱系追踪上，纳入克隆条形码后克隆命运一致性比最强动力学基线提升 54%，并在转录上彼此相似的祖细胞之间识别出早期谱系启动。",
"时序 CITE-seq 上，RNA 初始化的轨迹对未来表面蛋白分布的预测误差下降 13.2%，揭示转录程序与蛋白程序之间存在谱系特异性的时间偏移。四个真实案例中有一例选择了沿用既有的 velocity-growth 模型，用于重建情境依赖的上皮-间质转化。"],
limits:[
"预印本，未经同行评议；全部结论为作者自评，尚无第三方复现。",
"DynBench100 的真值是模拟出来的。在模拟里能恢复隐藏动力学，不等于在真实数据上能恢复——真实数据的动力学真值恰恰不可得。这既是必须做模拟基准的理由，也是它说服力的止步之处。",
"三个百分比提升的参照系是作者选定的基线，而非社区公认的最优方法；「最强动力学基线」由作者自行定义。",
"智能体自主写出的三个新动力学公式尚未经独立实验验证，它们是可检验的假设而非被验证的机制。"],
debate:[
"「让 AI 自己改模型公式」听上去是范式跃迁，但真正的难点在验收：一个公式能不能表达某项测量，这个判断本身依赖建模者的生物学理解。智能体在这里做的是可自动化的近似——出错时不会报错，只会给出一个看起来合理的错公式。",
"与本站持续追踪的评测批判并读：领域刚花了一年证明「指标会奖励错的东西」，现在又多了一层——当模型结构本身也是 AI 生成的，错误会从预测层下沉到结构层，更难被指标发现。",
"值得肯定的克制之处：四个真实案例中有一例明确选择了沿用既有公式，说明系统的默认行为是复用而非发明。这一点决定了它是建模工具，而不是公式生成器。"],
takeaway:[
"情报视角：这是 agentic AI 第一次落在虚拟细胞的「动力学形式」层，而非架构或超参数层；北京大学团队在该方向的动作值得持续跟踪。",
"实用提醒：DynBench100 是目前少见的自带隐藏真值的动力学基准，即使不采用 CellCompass 也值得被独立使用。反过来说，任何只报 DynBench100 分数的工作，其结论边界都止于模拟。"],
further:["p21","p84","p88"]},
{id:"p101",g:"g2",t:"ProtCell: a foundation model for single-cell proteomics",a:"Hu, Li, Jiang, Yin, Liu, Jiang（清华大学；通讯：Rui Jiang）",v:"bioRxiv（预印本，未经同行评议）",d:"2026-10-27",doi:"10.64898/2026.10.22.760932",
summary:"面向单细胞蛋白质组的基础模型：以约 3.8 亿个细胞、98 个数据集做预训练与评测，用「蛋白质身份嵌入 + 连续丰度嵌入」的双通道 Transformer 编码器，通过掩码丰度建模学习细胞与蛋白两层表征，目标是打通不同实验间互相割裂的蛋白面板，并把有限面板外推到未测蛋白。",
background:[
"单细胞蛋白质组是细胞状态最直接的功能读数——转录本只说明「打算做什么」，蛋白才更接近「正在做什么」。但现实里，靶向检测（流式、质谱流式、CITE-seq 等）每次只能测几十到几百个蛋白，而且不同实验测的面板还不一样。",
"结果是信息被切成碎片：同一个细胞群体在两项实验里的蛋白画像不可比，跨实验整合、跨队列复用都因此受阻。这与转录组领域曾经的局面很像——后者是靠基础模型 + 大规模预训练才把碎片连起来的。",
"转录组基础模型的经验不能直接搬：表达值是计数、可用离散 token 化；蛋白丰度是连续的、且面板不固定，模型必须同时理解「这是哪个蛋白」和「它有多少」。",
"因此 ProtCell 的站位很清楚：不是再做一个更大的转录组模型，而是把基础模型范式平移到「面板不统一」这一蛋白质组特有的结构约束上。"],
method:[
"数据规模：约 3.8 亿个细胞、98 个数据集，用于预训练与评测。",
"编码器采用双通道嵌入：蛋白质身份（protein-identity）嵌入处理「测的是哪个蛋白」，连续丰度（continuous-abundance）嵌入处理「测到多少」，二者在 Transformer 编码器内融合。",
"预训练任务是掩码丰度建模（masked abundance modeling）：遮住一部分蛋白的丰度值让模型预测，从而同时学到细胞级表征与蛋白级表征。",
"由于面板可变，模型天然处理「部分观测」——这使它能把碎片化的 profile 放进同一个表征空间，而不要求所有实验测同一套蛋白。"],
results:[
"连接碎片化 profile：ProtCell 在跨数据集的注释迁移与批次校正上可用，同时保留原有的生物学组织结构。",
"外推有限面板：模型能重建未测蛋白的丰度，并推断出一个未被测量的细胞毒性蛋白程序——该程序在自然杀伤细胞与记忆 CD8+ T 细胞中富集。",
"学到的蛋白间依赖关系还能反过来指导实验设计：据此挑选的紧凑蛋白面板，在 profile 重建与生物学分类上仍能保留大部分信息。",
"换言之，模型不只是「补数据」，还给出了「下一次该测哪几个蛋白」的选板建议。"],
limits:[
"预印本，未经同行评议；3.8 亿细胞这一规模与 98 个数据集的构成（物种、组织、平台分布）未在摘要中展开，数据同质化程度待核实。",
"重建出的未测蛋白丰度是模型推断值，不是测量值；文中报告的细胞毒性蛋白程序需要独立的湿实验验证才能确认。",
"「保留生物学组织结构」这类结论依赖作者选择的可视化与量化口径，缺少与其他整合方法（Harmony、totalVI 等）在同一协议下的横向对比。",
"面板选择的建议只在作者自己的重建 / 分类任务上验证过，未证明能迁移到别的下游任务。"],
debate:[
"最有价值的一点可能不是模型本身，而是它把「该测哪些蛋白」变成了可被模型优化的对象——这把基础模型从被动的数据消费者变成了实验设计的参与者，与本站记录的 lab-in-the-loop 思路同源。",
"但要抵挡的误读是「模型补出了真实蛋白数据」。丰度重建与丰度测量是两回事：前者给出的是在给定面板条件下的条件期望，用它做统计推断会把模型的先验当成证据。",
"另一个值得警惕的对照：转录组领域刚刚经历了一轮「补出来的数据能不能用」的争论（本站已记录的多篇评测批判都指向这一点）。蛋白质组若直接沿用同样的做法，很可能重演同样的争议。"],
takeaway:[
"情报视角：这是本站收录的首个以单细胞蛋白质组为对象的基础模型，来自清华大学团队。它把 AIVC 的模态竞争从转录组推进到了蛋白层——而蛋白层恰恰是「功能读数」最硬的地方。",
"对读者的提醒：把它当作「跨面板整合器 + 选板顾问」来理解是安全的；把它当作「未测蛋白的测量替代品」则超出了当前证据。"],
further:["p09","p24","p11"]},
{id:"p102",g:"g7",t:"CPS: mapping physical coordinates to high-fidelity spatial transcriptomics via privileged multi-scale context distillation",a:"Zhang, Cao, Zheng, Liang, Wan（同济大学 / Broad Institute / 中国科学院数学与系统科学研究院；通讯：Shu Liang、Lin Wan）",v:"Bioinformatics（期刊，已同行评议）",d:"2026-10-28",doi:"10.1093/bioinformatics/btag218",
summary:"把物理坐标映射为高保真空间转录组的隐式神经表示框架：以「特权多尺度上下文蒸馏」让教师网络在训练时利用多尺度组织微环境信息，再把这种结构知识蒸馏进只吃坐标的学生网络，从而在推理阶段仅凭坐标生成具备上下文感知的表达图谱。DLPFC 基准上在插补与去噪两项取得 SOTA，并支持超分辨重建。",
background:[
"空间转录组能在原生组织语境里解析异质性，但现有平台普遍受限于高稀疏与低信噪比，细粒度的生物学信号被噪声埋掉。",
"已有的恢复思路分两类，各有硬伤：一类依赖图像配准，把组织学图像的信息搬过来，于是效果高度绑定配准质量与图像可得性；另一类用隐式神经表示，但这类方法本质上是上下文盲的——它把每个坐标独立处理，看不见邻域。",
"这两条路都绕开了同一个事实：空间转录组的信号本来就是多尺度的。一个 spot 的表达既受近邻细胞影响，也受更大范围的微环境结构影响。",
"CPS（Cell Positioning System）的切入点是：既然推理时只有坐标，那就把多尺度上下文当作「特权信息」——只在训练阶段可用，通过蒸馏把它的效果固化进坐标网络。"],
method:[
"框架由教师网络与学生网络组成。教师网络配备多尺度微环境注意力机制（multi-scale niche attention），在训练时显式建模不同尺度上的生物学相互作用。",
"学生网络只接收物理坐标。通过特权多尺度上下文蒸馏，教师学到的结构知识被显式蒸馏进学生网络，使后者在推理时无需图像配准、无需邻域输入，仅凭坐标即可生成上下文感知的表达图谱。",
"「特权信息」是关键设计：多尺度微环境在训练时可计算，在推理时并非必需——这让模型既用上了上下文，又不依赖推理期的额外模态。",
"由于学生网络是坐标到表达的连续映射，它天然支持任意分辨率的采样，这构成了超分辨能力的来源。"],
results:[
"在 DLPFC（人脑背外侧前额叶皮层）数据集上，CPS 在空间插补、基因表达插补与去噪三项任务上取得当前最优表现。",
"超分辨：模型可恢复更高分辨率的小鼠脑解剖细节，即由低分辨率观测重建出更细的空间结构。",
"可解释性：通过识别人乳腺癌组织中生物学相互作用的有效尺度，模型能给出「相互作用发生在多大尺度上」的读数——这本身是一个生物学量，而非单纯的模型副产品。",
"可扩展性：框架对大规模数据集呈线性计算复杂度。"],
limits:[
"虽已通过同行评议正式发表，但全部结果为作者自评；DLPFC 是空间转录组领域被反复使用的单一基准，在该基准上领先不等于跨组织、跨平台通用。",
"上线日期存在口径不一致：Crossref 登记日期与期刊上线 / 机构报道日期不一致，本条按机构报道日 2026-10-28 记录，精确上网日期待核实。",
"超分辨结果缺乏同分辨率的真实观测作对照——「恢复出更细结构」的判定依赖于与低分辨率输入及已有解剖先验的比较，而非独立测量。",
"「有效相互作用尺度」这一读数目前缺少外部生物学验证，应视为可检验的假设。"],
debate:[
"与本刊记录的空间转录组分割基准并读，两者指向同一条规律：空间组学的结论对「如何处理空间结构」极度敏感。分割算法能改写生物学结论，坐标模型同样能——区别在于后者改写的是表达值本身，更难以事后察觉。",
"特权信息蒸馏是个聪明的设计，但它把风险也一并蒸馏了进去：教师网络对多尺度上下文的理解若有偏，学生网络会把这个偏差固化成看似平滑的表达图谱，且在推理时无从诊断。",
"真正的价值可能在于它证明了「只需要坐标」这一极简输入也能携带上下文信息——这对那些拿不到配对组织学图像的旧数据集是个实用消息；但同样的性质也意味着，一旦模型被误用，输出会看起来非常合理。"],
takeaway:[
"情报视角：这是本站收录的首个以「坐标 → 高保真表达」为任务的空间转录组表示学习工作，来自同济大学 / Broad / 中科院数学院的组合。它属于空间组学的方法层，不是虚拟细胞建模本身。",
"对读者的提醒：超分辨与插补产出的是模型重建值。把它用于下游统计推断前，需要先确认你的结论不会随重建方式改变——这正是分割基准已经给过一次的警告。"],
further:["p92","p94","p56"]},
{id:"p103",g:"g6",t:"Identification of gene kinetics patterns improves RNA velocity and cell fate prediction using JuloVelo",a:"Tung, Tu, Hsieh, Juan, Huang（阳明交通大学；通讯：Hsuan-Cheng Huang）",v:"bioRxiv（预印本，未经同行评议）",d:"2026-10-27",doi:"10.64898/2026.10.24.761531",
summary:"RNA velocity 的改进来自初始化而非架构：先判定每个基因属于环形、完全诱导或完全抑制三类动力学模式中的哪一类，再用模式匹配的预训练权重初始化网络，把细胞特异的动力学优化从生物学上不合理的参数区间里引开。八个数据集上稳定优于恒定速率与细胞特异模型，并比 cellDancer 减少约 70% 计算时间。",
background:[
"RNA velocity 让研究者能从测序快照预测细胞的未来状态，是单细胞分析里少见的「带方向」的工具。但主流方法都建立在恒定或二值的动力学假设上，抓不住分化过程中异质的剪接动力学。",
"深度学习方法（如 cellDancer）放开了这个假设，代价是优化问题变得很难：细胞特异的动力学参数空间大，网络容易落到拟合良好但生物学上讲不通的解上。",
"JuloVelo 的诊断是——问题不在模型容量，在起点。如果初始化时就把每个基因的动力学类型告诉网络，后续的优化就不需要再摸索这个基本形状。",
"这与本站记录的「层深度也是超参数」属于同一类发现：在这类模型里，被当成实现细节的东西（初始化、提取深度）往往决定结果。"],
method:[
"第一步是模式判定：根据基因在细胞分化过程中的表现，预先判定其属于环形（Circle）、完全诱导（Complete induction）还是完全抑制（Complete repression）动力学模式。",
"第二步是模式匹配的初始化：用与该模式对应的预训练网络权重初始化，而非随机初始化，从而把细胞特异动力学的优化约束在合理的参数区间内。",
"多组学扩展： promoter 染色质可及性可用于指导动力学模式的预先判定，使多组学数据也能纳入同一框架。",
"另集成 in silico 扰动框架，用于模拟转录因子调控对细胞命运的影响。代码开源（Julia 实现）。"],
results:[
"在涵盖红细胞生成、神经发生与内分泌发生的八个数据集上，JuloVelo 的表现持续优于恒定速率模型与细胞特异模型。",
"在海马神经发生数据中，它解析出了完整的五谱系分化程序。",
"多组学处理同时改善了内源性与外源性 velocity 的稳定性。",
"计算效率：相比 cellDancer 减少约 70% 的执行时间。"],
limits:[
"预印本，未经同行评议；八个数据集的具体构成与基线选择由作者决定，缺少与更广泛 velocity 方法（scVelo、veloVI 等）的系统横向对比。",
"「解析出完整五谱系分化程序」的判定依赖作者的下游分析口径，缺少独立的谱系追踪数据作验证。",
"in silico 转录因子扰动的结果是模型推演，不是实验扰动；作者未报告对应的湿实验验证。",
"70% 的加速比在不同硬件与数据规模下未必稳定，需按作者提供的开源实现自行复算。"],
debate:[
"这项工作最值得记的其实是一条方法论结论：在这个子领域，初始化策略的价值可能超过架构创新。这与本站记录的「层深度也是超参数」形成了呼应——当模型的自由度足够大时，约束从哪里注入比模型有多大更关键。",
"对虚拟细胞的直接意义在于：velocity 是把静态快照变成动态预测的关键环节，而它长期以来的可靠性问题（估计不稳、对预处理敏感）正是限制其作为虚拟细胞输入模态的主要原因。初始化若能稳定估计，意义不止于 velocity 本身。",
"需要抵挡的误读是「动力学模式被识别出来了」。模式是预先判定并用于初始化的先验，不是从数据里学到的结论——判定错了，模型不会报错。"],
takeaway:[
"情报视角：本站此前已记录 isCORAL 从快照反推细胞亲缘、为虚拟细胞补「记忆」的工作；JuloVelo 属于同一条支线——给静态单细胞数据补上时间维度，是虚拟细胞动力学层的输入准备。",
"对读者的提醒：这是一个方法学改进，不是新的生物学发现。它让 velocity 更稳、更快，但 velocity 本身的解释边界并没有因此改变。"],
further:["p84","p93","p21"]},
{id:"p104",g:"g3",t:"How Much Can AI Virtual Cells Gain from Unified Perturbational Modeling?",a:"Wei, Ye, Cui, Ma, You（香港中文大学（深圳）理工学院；通讯：Yuning You）",v:"bioRxiv（预印本，未经同行评议）",d:"2026-10-27",doi:"10.64898/2026.10.25.761625",
summary:"把「数据集拼不起来」当成建模对象而不是障碍：在一个 VAE 扰动预测器里插入三个统一化模块（基因通道对齐、共享扰动编码、表达与身份联合嵌入），把测量基因集不同、扰动类型不同、细胞情境不同的 Perturb-seq 数据塞进同一个预测器。作者据此整合出 1.1 亿细胞、2.2 万+ 基因、4 类扰动、76 个情境的语料，用其中 8970 万细胞 / 71 个情境训练了一个十亿参数以上的统一模型，在 Tahoe-100M 留出的 5 条细胞系上四项指标全面优于 STATE，在细胞因子基准上全面优于 Stack。",
background:[
"Perturb-seq 数据的实际问题不是规模不够，是拼不起来：不同实验测的基因集不同、扰动类型（CRISPR / 药物 / 细胞因子 / 组合）不同、细胞情境不同。",
"现有 AIVC 预测器多为单一设定量身定制——STATE 之于大规模观测加扰动、GEARS 之于组合遗传扰动，换一个数据集往往要重训。",
"于是「统一建模到底能带来多少增益」这个问题一直没人给出量化答案，本文标题就是这个问题本身。",
"本站此前记录的两条结论与之直接相关：一是情境数比细胞数更能决定性能（Context, Not Just Scale），二是切分口径足以改写评测结论（p98）。统一建模换的其实就是情境数。"],
method:[
"在 VAE 架构的 AIVC 预测器上插入三个统一化模块：基因通道对齐（把不同数据集测到的基因集对齐到统一通道）、共享扰动编码（不同扰动类型共用一套编码器）、表达与身份的联合嵌入（把细胞表达谱与细胞身份标签嵌到同一空间）。",
"对三个模块逐一做消融，分别验证其独立贡献，而不是只报整体提升。",
"数据侧：整合出 1.1 亿细胞、覆盖 2.2 万+ 基因、4 类扰动、76 个细胞情境的语料；训练用 8970 万细胞、71 个情境，模型参数量超 10 亿。",
"代码开源（github.com/youlab2025/UPM）。"],
results:[
"在遗传扰动基准上，UPM 在受评模型中取得最高的 PES 与逐基因响应相关性。",
"在 Tahoe-100M 留出的 5 条细胞系上，四项评测指标全面优于 STATE。",
"在细胞因子基准上，四项评测指标全面优于 Stack。",
"组合扰动预测上，相对专用预测器也有改进。",
"HSC 应用：在「重现肝星状细胞（HSC）相关靶点敲低效应」的下游任务上准确率提升 40.0%。"],
limits:[
"预印本，未经同行评议；受评模型的名单由作者选定，STATE 与 Stack 是否为各自场景下的最强基线未做独立确认。",
"「十亿参数」与「1.1 亿细胞」是规模陈述而非能力证明——本文没有给出参数量或数据量的边际收益曲线，因此无法判断统一化的收益有多少其实来自规模。",
"76 个情境中 71 个用于训练，留出情境的构成与留出方式（随机还是系统性）在摘要中未充分展开，跨情境泛化的真实难度可能被低估。",
"训练语料包含 Tahoe-100M，评测也在 Tahoe-100M 留出的细胞系上进行：留出的是细胞系而非数据集，属情境留出值得肯定，但同一平台的数据风格一致性会抬高成绩。",
"HSC 的 40.0% 提升出自单一应用任务，「重现敲低效应」的判定口径由任务定义决定，且缺少湿实验验证。",
"代码开源但尚未见第三方复现。"],
debate:[
"最值得记的不是又一个更大的模型，而是它把「不同来源的扰动数据能不能合并」变成了一个可消融、可量化的工程问题。三个模块各自有贡献，说明异构性确实是可拆解的，而不必靠规模硬压过去。",
"与本站记录的「情境数比细胞数更重要」放在一起看，UPM 的路线其实是用统一化换情境数——76 个情境是它真正的资本，1.1 亿细胞更像副产品。",
"需要抵挡的误读是「统一模型已证明优于专用模型」。这里的「全面优于」成立于作者选定的基准与留出口径，而留出口径恰恰是本刊反复记录的高敏感变量（p98 已证明换切分方式就能系统性改变成绩）。",
"对本刊的意义：这是迄今收录的第一篇以「跨数据集统一」为唯一研究问题、并给出模块级消融的扰动预测工作。它提供的不是 SOTA，而是一份「异构数据能不能合并、合并能换来多少」的账本。"],
takeaway:[
"情报视角：统一化路线的价值不取决于它这次赢了 STATE 多少，而取决于它能否让后续研究者不再为每份新数据集重训一个模型。这个判断要等第三方复现。",
"对读者的提醒：十亿参数模型的复现成本不低。在第三方复现出现之前，本文成绩应按「机构自述 + 预印本」处理。"],
further:["p32","p48","p83","p98"]},
{id:"p105",g:"g4",t:"Ground-truth evaluation of sparse autoencoder features on spatial, single-cell and language-model embeddings",a:"Shahsavand, Forghani, Akbarzadeh, Mahdavi Sabet（德黑兰医科大学血液恶性肿瘤研究中心；通讯：Amirhossein Shahsavand）",v:"bioRxiv（预印本，未经同行评议）",d:"2026-10-29",doi:"10.64898/2026.10.27.762296",
summary:"用概念已知的嵌入给稀疏自编码器（sparse autoencoder，SAE）特征打真值分：五套结直肠癌空间转录组嵌入、以细胞谱系为概念的 Geneformer 单细胞嵌入、植入了细胞状态的合成数据，以及一个小语言模型的残差流（以 token 类别为概念）。结论是重复率高的特征未必有意义——旋转类方法（PCA / varimax / ICA）几乎完全可复现，却最多只覆盖七个谱系中的三个、八个 token 类别中的三个；单次 SAE 拟合恰恰相反，覆盖多数概念、基因程序更纯，但只有 27-46% 的特征可复现。五次拟合取共识可以兼得，也有代价。",
background:[
"SAE 正成为从生物基础模型嵌入里提取可解释特征的主流工具。",
"由于不同随机种子训出的 SAE 学到的特征不同，「跨种子可复现」被普遍当成特征是否可信的检验。",
"本文要问的是：可复现的特征，是否同时也是有意义的特征？",
"这个问题需要概念已知的嵌入才能回答——否则「有意义」无从判定，这正是以往工作绕开的地方。"],
method:[
"四类概念已知的嵌入：五套结直肠癌切片的空间转录组嵌入（概念为空间结构）、Geneformer 单细胞嵌入（概念为细胞谱系）、植入了已知细胞状态的合成数据、以及一个小语言模型的残差流（概念为 token 类别）。",
"对照双方：同一嵌入的旋转类分解（PCA / varimax / ICA）与稀疏自编码器 SAE。",
"关键控制：把 varimax 稀疏化到与 SAE 相同的稀疏度再比，避免稀疏度差异混入结论。",
"额外测试：对五次 SAE 拟合取共识，并检验更长的单次拟合、以及在共识残差上再训练第二个 SAE 能否找回被丢弃的概念。"],
results:[
"同一嵌入的 varimax 旋转几乎完全可复现，但旋转类特征（PCA / varimax / ICA）最多只覆盖七个谱系中的三个、八个 token 类别中的三个。",
"单次 SAE 拟合呈现相反的画像：覆盖多数概念、基因程序更纯，但只有 27-46% 的特征可复现。",
"五次拟合的共识兼得两者：跨来源可复现率 78-98%，纯度与单次拟合相当——11-40% 的特征携带另一谱系的标志基因，而 varimax 为 44-70%。",
"相对最强基线（稀疏化到 SAE 稀疏度的 varimax），共识在 PCA 与 Geneformer 嵌入上覆盖同样多的概念，在学到的空间嵌入与文本嵌入上覆盖更多。",
"代价：共识覆盖的谱系比单次拟合少；且和所有 SAE 一样会漏掉旋转类方法能找回的弱植入状态——更长的单次拟合与在共识残差上再训一层 SAE 都找不回来。"],
limits:[
"预印本，未经同行评议。",
"「概念已知」是本文成立的前提，也是它的边界：真实场景里概念通常未知，真值评估框架无法直接平移。",
"谱系与 token 类别属粗粒度概念，能否代表生物学家真正关心的对象（通路、调控关系、扰动响应）未经验证。",
"小语言模型的规模有限，结论向更大模型迁移的可靠性未知。",
"「覆盖」与「纯度」的判定阈值由作者设定，换阈值可能改变排序。"],
debate:[
"对本站特别重要的一条结论：可复现性本身是个糟糕的排序指标。如果一个领域把「跨种子稳定」当成可信度的代理，而稳定的东西恰好是覆盖最少的，那么整个筛选流程就会系统性地偏好安全但没有信息的特征。",
"与本站已收录的 Attention Is Not Regulation（p39）属于同一类工作：都是在问「我们用来解释模型的那个量，是否真的携带我们以为它携带的东西」。前者否定注意力，这一篇给可复现性划了边界。",
"它给出的替代方案很具体：报告 SAE 特征时同时报告「覆盖了多少已知概念」与「基因程序有多纯」，对照组必须是同一嵌入稀疏化到相同稀疏度的旋转。可操作性很强，值得本刊在后续评测报道中直接采用。",
"悲观的一面同样值得记：共识丢掉的东西，用更长训练或在残差上再训一层都找不回来。这说明 SAE 的遗漏不是训练不足，而是结构性的。"],
takeaway:[
"情报视角：随着 SAE 越来越多地被用于「解释」单细胞与空间基础模型，这个子领域第一次有了带真值的评估框架，而不只是彼此比较可复现率。",
"对读者的提醒：本文不是要否定 SAE，而是给出一个报告规范和一种对照组选择。在采用这个规范之前，任何「我们的 SAE 特征是稳健的」的说法都缺少对照。"],
further:["p39","p37","p99"]},
{id:"p106",g:"g7",t:"Molecule-resolved inference reveals the spatial organization of transcriptional programs",a:"Si, Lee, Cheng, Sweeney, Yun, Kim, Jun, Lee, Kang（密歇根大学生物统计与统计遗传学中心；通讯：Hyun Min Kang）",v:"bioRxiv（预印本，未经同行评议）",d:"2026-10-30",doi:"10.64898/2026.10.29.762960",
summary:"不做分割、不做分箱，直接推断每一个 RNA 分子是由哪个转录程序产生的——只依赖基因身份与空间上下文。学到的程序带有各自不同的空间分布，尺度跨度从毫米级的连续过渡到微米级的亚细胞定位；这些共存模式同时给出细胞身份与生理活动的统一解释。作者称效率比替代方案高几个数量级，因而可在多种组织、多种空间技术平台的大规模数据上做系统分析。",
background:[
"转录程序编码细胞身份与生理活动，是连接基因调控与细胞表型的中间层。",
"空间转录组能测到完整组织里的单个 RNA 分子，但绝大多数分析会先把分子聚合到细胞或像素，分子层面的功能动态因此被抹平。",
"聚合的必要前提是分割，而分割本身是空间转录组公认的瓶颈——本站 p94 的 11 方法基准与 p95 的零样本 mask 全军覆没，已经两次记录分割如何改写结论。",
"FICTURE2 的出发点因此很直接：能不能跳过分割，直接在分子层面推断转录程序。"],
method:[
"统计模型：以基因身份与空间上下文为唯一输入，推断每个分子来自哪个转录程序，不需要细胞分割也不需要空间分箱。",
"同时支持无监督推断与参考引导（reference-guided）推断两种模式。",
"效率上的关键声明：比替代方案快几个数量级，因而可做大规模空间数据的系统性分析。",
"验证覆盖多种组织类型、由多种空间技术平台产出的数据。"],
results:[
"学到的程序带有明显不同的空间分布，尺度跨度从毫米级连续过渡到微米级亚细胞定位。",
"这些共存模式可同时给出细胞身份与生理活动的统一解释。",
"效率比替代方案高几个数量级，支持大规模空间数据集的系统分析。",
"在多种组织类型与多种空间技术平台的数据上完成演示。",
"（公开摘要未给出量化对比数字，性能声明按预印本自述处理，待核实）"],
limits:[
"预印本，未经同行评议。",
"公开摘要未给出与其他方法的量化对比表；「快几个数量级」与「覆盖多种组织与技术」缺少可核验数字，按待核实处理。",
"不依赖分割是优势也是风险：分子层面没有细胞边界，程序归属缺少独立金标准。",
"参考引导模式依赖参考数据的质量与跨数据集可比性。",
"微米级亚细胞定位的判定精度受平台分辨率限制，不同平台间未必一致。"],
debate:[
"值得记的是它绕开的那个环节：本站已两次记录分割如何改写结论，FICTURE2 的做法是干脆不做分割。这是同一问题的两种解法——一种把分割做对，一种让结论不再依赖分割。",
"分子级分辨率换来的不只是更细的图：亚细胞定位与毫米级梯度能同时出现在一套程序里，这在聚合到细胞的分析中是看不到的。",
"需要抵挡的误读是「分子级一定优于细胞级」。分子层面缺少细胞这一层生物学单位，任何要落到「哪种细胞做了什么」的问题，仍须回到细胞。",
"与本站刚收录的 CPS（p102）构成对照：CPS 把坐标蒸馏成表达，FICTURE2 从分子反推程序，两者都在绕开传统流水线的某个环节。"],
takeaway:[
"情报视角：这是本站 g7 空间支线上第一次出现「以分子而非细胞为分析单元」的统计方法，方向值得盯住。",
"对读者的提醒：方法的核心声明（不分割、快几个数量级）目前只有作者自述，等正式评测出现再判断。"],
further:["p102","p94","p95"]},
{id:"p107",g:"g7",t:"Live Spatial Transcriptomics Enables Longitudinal Tissue Mapping",a:"Reynolds, Lee, Lee, Kumar, Liu, Huynh, Kim, Hornet, Oh, Bracht … Ko（宾夕法尼亚大学生物工程系 / 病理与检验医学系；通讯：Jina Ko）",v:"bioRxiv（预印本，未经同行评议）",d:"2026-10-30",doi:"10.64898/2026.10.28.761959",
summary:"把空间转录组从「一次性的切片快照」变成「同一块活组织的重复测量」：用电转做细胞内取样、再用空间条码标记，通过测序在完整活组织上反复获取带空间位置的 mRNA 信息。三项演示——图案化二维细胞体系上的空间 mRNA 捕获基准、在保持组织活性的前提下对患者来源活体黑色素瘤组织做空间转录组描绘、以及在肿瘤微环境内纵向追踪药物响应动态。",
background:[
"空间转录组的价值在于保留基因表达的空间上下文，但现有方法给出的都是单个组织标本的静态快照。",
"因此发育、疾病进展与治疗响应的分子动力学，只能靠比较不同标本去推断，而不是在同一块活组织里直接追踪。",
"这个「用空间换时间」的替身做法，是所有纵向生物学结论的隐性误差来源——不同个体之间的差异被当成了时间上的变化。"],
method:[
"电转介导的细胞内取样 + 空间条码标记：在完整活组织上反复取样，通过下一代测序读出带空间位置的 mRNA。",
"基准：在图案化二维细胞体系上标定空间 mRNA 捕获。",
"应用一：在患者来源的完整活体黑色素瘤组织上做空间转录组描绘，同时保持组织活性。",
"应用二：在肿瘤微环境内纵向追踪药物响应动态。"],
results:[
"在图案化二维细胞体系上完成空间 mRNA 捕获的基准测试。",
"可在保持组织活性的前提下，完成患者来源活体黑色素瘤组织的空间转录组描绘。",
"可在肿瘤微环境内纵向追踪药物响应动态。",
"（摘要未给出捕获效率、空间分辨率、重复次数等量化指标，按预印本自述处理，待核实）"],
limits:[
"预印本，未经同行评议；摘要未报告捕获效率、空间分辨率、可重复测量次数与组织损伤程度等可核验数字。",
"电转取样的侵入性是否改变被测量的细胞状态，是这类方法的核心隐患，本文未给出对照证据。",
"「保持组织活性」的判定标准与可维持时长未披露。",
"活体黑色素瘤应用的样本数与患者数未在摘要中给出。",
"患者来源组织的异质性意味着纵向追踪的普适性尚未可知。"],
debate:[
"如果这个方法站得住，它改变的是实验设计的单位：从「一批标本拼出一条时间线」变成「一块组织给出自己的时间线」。对虚拟细胞而言，时间序列数据一直是稀缺品，真正的纵向数据更是几乎不存在。",
"与本站已收录的 BLOOM（p97）形成互补：BLOOM 用条件流匹配去补发育图谱的时间空档，Live-ST 则试图让时间空档根本不出现。一个是算法补，一个是测量补。",
"若与本站记录的 JuloVelo（p103）同看，本刊近期连续记录了三条从不同角度给静态单细胞数据补时间维度的工作——说明时间维度已被公认为虚拟细胞最缺的一层输入。",
"需要抵挡的误读是「纵向等于因果」。同一块组织上反复测到的是关联的时间序列，不等于干预的因果响应。"],
takeaway:[
"情报视角：本刊此前记录的时间维度缺口（BLOOM 从算法侧补、JuloVelo 从初始化侧稳），第一次出现了一个从测量侧直接补的尝试。",
"对读者的提醒：方法学演示阶段，尚无量化性能数据与第三方复现，不宜作为可用工具评估。"],
further:["p97","p102","p103"]},
{id:"p108",g:"g7",t:"Joint localization and testing reveals spatial context of differential expression",a:"Stotzem, Chang, Cai, Casale（Helmholtz Munich；通讯：Francesco Paolo Casale）",v:"bioRxiv（预印本，未经同行评议）",d:"2026-10-29",doi:"10.64898/2026.10.28.758685",
summary:"多主体空间转录组要做的是「找出分子差异，并指出差异发生在组织的哪个位置」，但主体级差异表达分析通常要求先划定空间区域，把定位与检验拆成两步。SpaceDX 用基因特异的注意力式空间加权，把差异表达检验与驱动这些关联的空间表达模式定位合成一步完成。慢性应激小鼠脑模型中比分区 DESeq2 pseudobulk 多检出 45.8% 的差异表达基因；阿尔茨海默病模型中与 DESeq2 组合使用使发现量提升 19.1%。",
background:[
"多主体空间转录组越来越多地被用于跨个体、跨条件识别分子差异，并定位这些差异发生在组织的何处。",
"但主体级差异表达分析通常要求预先指定空间区域（聚类分区或解剖分区），定位因此与检验分离。",
"一旦真实差异不与预定义边界对齐，区域聚合就会把信号稀释掉——这是空间差异表达的结构性漏检来源。"],
method:[
"基因特异的注意力式空间加权：为每个基因学一套空间权重，在检验差异表达的同时定位贡献这些关联的空间表达模式。",
"不需要预先指定相关组织上下文。",
"模拟：在差异表达不与预定义空间边界对齐的场景下，与基于聚类的差异表达方法比较。",
"实测：两套多主体小鼠脑数据集——慢性应激模型与阿尔茨海默病模型。"],
results:[
"模拟中，当差异表达不与预定义空间边界对齐时，SpaceDX 优于基于聚类的差异表达方法。",
"慢性应激模型：检出的差异表达基因比分区 DESeq2 pseudobulk 多 45.8%。",
"阿尔茨海默病模型：SpaceDX 与 DESeq2 组合使用，相对单独使用 DESeq2 使发现量提升 19.1%。",
"学到的空间图为条件相关表达信号提供了基因层面显著性之外的空间上下文。",
"慢性应激模型中，少突胶质细胞与髓鞘相关基因表现出与对应脑结构一致的共定位。"],
limits:[
"预印本，未经同行评议。",
"两个数据集均为小鼠脑，跨组织与跨平台的迁移性未验证。",
"「多检出 45.8%」是发现数量的增加，缺少独立的假阳性率核验；模拟之外真值不可得。",
"注意力式空间权重的可解释性本身没有独立验证——学到的是统计上的权重分布，不等于解剖结构的恢复。",
"与 DESeq2 组合使用（+19.1%）意味着方法并非替代而是叠加，组合策略的选择空间未系统探讨。"],
debate:[
"这条结论与本站反复记录的一个模式同构：先定分区再统计，会把不对齐的信号平均掉。p82 说的是基准平均化掩盖扰动强度差异，p98 说的是切分方式抬高分类成绩，SpaceDX 说的是空间分区掩盖差异表达——三次出现在不同子领域，指向同一个方法论问题。",
"「多检出 45.8%」要小心读：它同时包含真阳性的找回与可能的假阳性增加。模拟里能做真值核验，真实数据里不能。",
"对虚拟细胞的意义在于：空间差异表达是空间基础模型最常用的下游任务之一。如果任务本身的漏检率是结构性的，那么模型在这个任务上的成绩也要相应打折。",
"本站已收录的 p94（分割基准）与 p95（分割决定有没有发现）讲的都是「上游处理决定下游结论」，SpaceDX 把这条链再往下延伸一步——统计口径本身也是上游处理的一环。"],
takeaway:[
"情报视角：空间差异表达是空间基础模型的高频下游任务，本文给出了这个任务本身的漏检估计方法。",
"对读者的提醒：45.8% 与 19.1% 是发现量而非准确率，不要当成性能提升读。"],
further:["p94","p95","p82"]},
{id:"p109",g:"g7",t:"NicheCorr: Identifying Niche-Specific Differential Gene Co-Expression in Spatial Transcriptomics",a:"Yang, Ho, Fan（南卡罗来纳大学；通讯：Shuyi Yang）",v:"bioRxiv（预印本，未经同行评议）",d:"2026-10-28",doi:"10.64898/2026.10.23.761453",
summary:"问的不是「生态位里平均表达怎么变」，而是「生态位里基因与基因的关系怎么变」。NicheCorr 是一套统计流程，识别细胞类型特异的、与生态位关联的基因共表达变化。模拟中功效最高，且是受评方法里唯一在「平均表达随生态位非线性变化」时仍能控制一类错误的方法——CS-CORE、未做均值校正的 scHOT 与 Pearson 检验在该设定下假阳性率均 inflated。实测在 CosMx 人肝脏与 Xenium 人胰腺癌数据上分别找出 52 与 48 个生态位依赖的基因对，并整合配体-受体推断。",
background:[
"细胞间通讯是免疫响应与肿瘤进展等过程的核心，但不同细胞类型之间的空间邻近如何塑造基因共表达，一直不清楚。",
"现有方法主要识别组织区域间平均表达的差异，忽略了局部细胞微环境如何重塑细胞内部的基因-基因相互作用。",
"换句话说，大家在看「表达量变没变」，很少有人看「关系变没变」。"],
method:[
"NicheCorr：统计流程，在不同空间生态位内分别估计细胞类型特异的、生态位关联的基因共表达变化。",
"模拟中比较功效与一类错误控制，特别设置「平均表达随生态位非线性变化」这一困难设定。",
"整合配体-受体（ligand-receptor, LR）推断，把差异共表达模式与可能的信号互作联系起来。",
"实测：CosMx SMI 人肝脏 FFPE 数据集与 Xenium 人胰腺癌数据集。"],
results:[
"模拟：NicheCorr 在检测生态位依赖共表达上功效最高。",
"是受评方法中唯一在平均表达随生态位非线性变化时维持一类错误控制的方法；CS-CORE、未做均值校正的 scHOT 与 Pearson 检验均出现 inflated 假阳性率。",
"人肝脏：在肝肿瘤细胞中识别出 52 个随 T 细胞生态位组成变化而改变共表达的基因对。",
"人胰腺癌：识别出 48 个在成纤维细胞生态位依赖的共表达上、在肿瘤细胞与 CFTR- 肿瘤细胞之间存在差异的基因对。",
"并给出可能解释这些差异共表达模式的配体-受体互作。"],
limits:[
"预印本，未经同行评议。",
"生态位的定义（如何划分、邻域半径多大）由分析者设定，不同定义下的稳定性未系统评估。",
"52 与 48 个基因对的生物学含义有待实验验证，目前只是统计发现。",
"配体-受体推断依赖 LR 数据库的覆盖与质量，存在已知的数据库偏倚。",
"「唯一维持一类错误控制」成立于作者设定的模拟，模拟是否贴近真实数据分布未独立检验。"],
debate:[
"值得记的是它选的那个困难设定：平均表达随生态位非线性变化。这是真实且常见的情形——生态位往往同时改变均值与关系，也是多数共表达方法会翻车的地方。作者把对照摆在这个设定上，比在理想设定下刷功效更有说服力。",
"与本站的记录放在一起看：p98 说切分方式抬高分类成绩，p82 说平均化掩盖强度差异，SpaceDX 说分区掩盖差异表达——NicheCorr 说的是另一回事，但方向一致：把「关系」当作分析单元能看到「均值」看不到的东西，代价是对一类错误控制的要求更高。",
"需要抵挡的误读是「共表达等于互作」。共表达是统计相关，配体-受体推断是数据库注释，两者叠加不等于机制。"],
takeaway:[
"情报视角：空间转录组的分析单元正从「区域」下沉到「生态位」再下沉到「基因对关系」，这是本站 g7 分组里一条正在成形的支线。",
"对读者的提醒：本文的对照设计（非线性均值设定）比它的实测发现更值得借鉴。"],
further:["p56","p108","p94"]},
{id:"p110",g:"g5",t:"Spatial coordination in the codevelopment of the human urogenital system during organogenesis",a:"Guo, Cai, Li, Ren, Cui, Hao, Jiang, Zhang, Wang, Guo（中国科学院动物研究所 / 北京大学第三医院 / 青岛大学附属妇女儿童医院；通讯：郭靖涛、王晓琰、张哲）",v:"Science（期刊，已同行评议）",d:"2026-10-29",doi:"10.1126/science.aee5093",
summary:"泌尿系统与生殖系统来自同一个胚胎结构域，但以往分子研究都是逐个器官做的。团队把高分辨率空间转录组与单细胞多组学结合，分析 Carnegie 分期 15-23 期（约孕 5-8 周）的人类胚胎，得出三点：中肾与肾上腺原基发出的信号促进性腺特化（并在体外高效诱导出早期性腺样细胞）；性腺支持细胞可能经睾丸网或卵巢网来自中肾；三种转录上不同的类固醇生成谱系分别在胆固醇来源、皮质醇合成与性激素产生上分工，共同编排性别分化。",
background:[
"人类泌尿生殖系统起源于共同的胚胎结构域，泌尿与生殖系统的紧密关联提示早期器官发生中存在器官间调控。",
"但大多数分子研究分别考察单个器官：中肾、肾上腺与性腺如何协同参与器官原基特化与谱系分化、并调控性别分化，一直不清楚。",
"胚胎材料获取困难与伦理限制，使人类胚胎的直接研究长期受限，跨器官协同尤其缺乏数据。"],
method:[
"整合高分辨率空间转录组（空间增强分辨率组学测序）与单细胞多组学测序。",
"样本：Carnegie 分期 15 至 23 期人类胚胎，覆盖性腺原基形成、性别决定与外生殖器分化前的关键窗口。",
"补充手段：计算机模拟基因调控网络分析、组织蛋白成像、以及人胚胎干细胞来源的中胚层 / 性腺样细胞模型。",
"功能性验证：把候选信号分子组合施加于人胚胎干细胞来源的中间中胚层细胞，观察是否获得早期性腺样转录特征。"],
results:[
"空间图谱显示，在早期性腺细胞特化阶段（约孕 5 周），来自邻近中肾与肾上腺原基的信号可被性腺原基接收（WNT、BMP、NCAM 等）。",
"把鉴定出的信号分子组合施加于人胚胎干细胞来源的中间中胚层细胞，可促使其向早期性腺谱系特化——为「跨器官信号促进性腺特化」提供了功能性证据。",
"发现性腺与中肾交界处的 PAX8 阳性 rete 细胞，提示性腺支持细胞可能的中肾起源（经睾丸网或卵巢网连接中肾）。",
"描绘三种转录上不同的类固醇生成谱系：肾上腺胎儿带分别偏向胆固醇从头合成与从循环脂蛋白摄取并合成皮质醇，男性胎儿 Leydig 细胞负责雄激素合成，共同协调性别分化。",
"为理解泌尿生殖器官协同中断如何导致先天性异常与性发育差异提供了框架。"],
limits:[
"人类胚胎样本数量受伦理与获取限制，Carnegie 分期覆盖为离散时间点，发育过程需由跨期样本拼接而非连续追踪。",
"「可能的中肾起源」是谱系推断（基于转录相似性、免疫荧光共定位与小鼠 Pax8 谱系数据），不是人类体内的直接谱系追踪。",
"体外诱导获得的是「早期性腺样」转录特征，不等同于功能性性腺细胞。",
"类固醇生成谱系的激素产生差异基于转录推断，缺少直接的激素测定。",
"临床外推（先天性异常、性发育差异）为框架性提示，未在患者样本中验证。"],
debate:[
"这篇值得收录的理由不是它有多「AI」——核心贡献是空间图谱与跨器官信号，方法上属于空间多组学的标准组合。收录理由是它为虚拟细胞提供了一个稀缺的东西：人类胚胎发育的原位空间真值。",
"与本站已收录的 BLOOM（p97，面向虚拟胚胎的条件流匹配建模）形成直接对照：BLOOM 试图用生成模型补出发育图谱缺的时间点，这篇给出的正是那些模型需要拿来对齐的东西——真实的人类胚胎空间数据。一个造数据，一个造参照。",
"需要抵挡的误读是「跨器官信号等于已证实的因果」。WNT / BMP / NCAM 的空间表达与通讯预测相互吻合，加上体外诱导的功能性证据，证据链比纯生信强不少，但体内因果仍需干预实验。"],
takeaway:[
"情报视角：本站收录的第一篇人类胚胎泌尿生殖系统空间图谱，也是最稀缺的一类数据——真实、原位、带空间的人类发育参照。虚拟胚胎类模型今后的可信度，取决于有多少这类数据可供对齐。",
"对读者的提醒：这是 Science 期刊论文、已同行评议，但样本规模与伦理限制决定了结论边界；把它当作参照系而非机制终审。"],
further:["p97","p102","p05"]},
];
